-- Update Religious Guided content from the supplied DOCX manuscripts.
-- Match chapters by title so the chapter 8–10 reorder preserves IDs and learner progress.
do $$
declare
  chapter_item jsonb;
  lesson_item jsonb;
  block_item jsonb;
  course_version uuid;
  chapter_record uuid;
  lesson_record uuid;
  block_record uuid;
  block_position integer;
begin
  select cv.id into strict course_version
  from course_versions cv join courses c on c.id = cv.course_id
  where c.slug = 'uprooting-drug-abuse' and cv.guidance_path = 'religious';

  for chapter_item in select value from jsonb_array_elements('[{"number": 1, "title": "The Stage of Creation", "description": "Chapter 1 lays the foundation for your recovery journey.\n\nIt begins by exploring the original purpose and design for humanity, then traces how identity, purpose, freedom, temptation, choices, consequences, stewardship, and heart-level pain all connect to the roots of addiction.\n\nThe goal of this chapter is to help you understand that addiction is not your identity, that every person was created with inherent worth and purpose, and that lasting healing requires truth, responsibility, spiritual growth, and restoration of the heart.", "lessons": [{"number": 1, "title": "Original Design for Humanity", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Welcome to Your Journey", "message": "Before we can understand drug abuse and addiction, we must first understand who we were created to be, what the original human design was. Many people see themselves through the lens of their mistakes, addictions, failures, or past experiences. However, most traditions teach that humanity has inherent worth, purpose, and dignity that existed long before life''s struggles began.\n\nThis lesson explores the original design for humanity and reminds us that every person was created with value and purpose. Regardless of your tradition or the path your life has taken, you were never intended to live in hopelessness, bondage, or destruction.\n\nToday we begin by exploring humanity''s original purpose and what that can mean for your recovery journey."}}, {"type": "reading", "content": {"title": "Created With Purpose", "body": "Traditions teach that the universe and all living things were created with intention and purpose.\n\nAcross different faiths, humanity is understood to hold a unique place within creation, entrusted with dignity, responsibility, and the ability to choose between what builds life and what harms it.\n\nThis reminds us that our value is not determined by our appearance, achievements, possessions, social status, or past mistakes.\n\nThe original design for humanity includes:\n\nA relationship with the Divine or Higher Power according to your faith.\n\nPurpose and meaning.\n\nResponsibility and stewardship.\n\nFreedom to choose.\n\nA life free from shame.\n\nA life guided by wisdom, compassion, and truth.\n\nMany teachings describe creation as fundamentally good. Humanity was not created to be broken, addicted, or trapped in destructive cycles. People were created to live in harmony with their Creator, with others, and with the world around them.\n\nWhen drug abuse and addiction enters a person''s life, it eventually convinces them that they are worthless, damaged, or beyond recovery. Your faith teaches something different. It reminds us that every person possesses inherent worth that cannot be erased by failure or addiction.\n\nRecovery begins when we learn to see ourselves through the truth and wisdom of our faith rather than through the mistakes we have made.\n\nYour addiction is something you have experienced. It is not your identity.\n\nYou were created for far more than survival. You were created with purpose, dignity, and the ability to grow into the person you were always meant to become.\n\nKey Teaching: Reflect on a creation teaching or passage from your own traditional belief system that reminds you of humanity''s value and purpose."}}, {"type": "mentor_note", "content": {"note": "One of the first steps toward healing is recognizing that your worth does not come from your past. Your worth comes from the value placed within you by your Creator and your faith."}}, {"type": "video", "content": {"title": "Humanity''s Original Design", "description": "Explain how many faith traditions teach that humanity was created with dignity, purpose, and value, and how addiction can distort a person''s understanding of their true identity. Encourage viewers to begin seeing themselves through the wisdom of their faith rather than through past mistakes."}}, {"type": "pause_reflect", "content": {"question": "When you think about yourself, what words usually come to mind?", "context": "Keep reflecting as you answer:\n\nHow has drug abuse or addiction affected the way you view yourself?\n\nWhat does it mean to you that you were created with purpose?\n\nDo you believe your faith teaches that your life still has meaning today? Why or why not?\n\nWhat would begin to change if you truly believed that your worth could never be taken away?"}}, {"type": "journal_prompt", "content": {"prompt": "Take ten minutes today and write down:\n\nThree negative labels you have placed on yourself.\n\nThree truths your faith teaches about your value and dignity.\n\nOne area of your life where you want to begin believing those truths instead of your past experiences."}}, {"type": "mood_checkin", "content": {"question": "How connected do you feel today to the belief that you were created with value, dignity, and purpose?"}}, {"type": "daily_action", "content": {"title": "Today''s Action Step", "action": "Spend a few quiet moments in prayer or personal reflection according to your faith. Ask your Creator or Higher Power to help you see yourself through the truth of your spiritual identity rather than through the labels created by addiction or past mistakes."}}, {"type": "mentor_note", "content": {"note": "You are more than your addiction.\n\nYou are more than your failures.\n\nYou are more than your worst day.\n\nYou were created with intention, dignity, and purpose. The Divine, according to your faith, knows your struggles, understands your pain, and desires your healing. No matter how far you feel you have fallen, your story is not finished.\n\nRecovery begins when you remember who you truly are—not through the eyes of addiction, but through the wisdom and hope found in your faith.\n\nMemory Reflection:\n\nChoose a passage from your own teachings that reminds you of your worth, purpose, or the hope of renewal, and spend a few minutes reflecting on its meaning today."}}, {"type": "quiz", "content": {"question": "According to this lesson, where does your true worth come from?", "options": [{"text": "Your achievements", "is_correct": false}, {"text": "Your past mistakes", "is_correct": false}, {"text": "Your Creator and inherent human dignity", "is_correct": true}, {"text": "Other people''s opinions", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Addiction is your identity.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "Which of the following is part of humanity''s original design?", "options": [{"text": "Living without purpose", "is_correct": false}, {"text": "Being trapped by addiction", "is_correct": false}, {"text": "Living with purpose and truth", "is_correct": true}, {"text": "Believing you have no value", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 1.", "encouragement": "Today you discovered that your identity is not rooted in drug abuse or addiction, shame, or failure. Your identity begins with the inherent worth, dignity, and purpose that your faith teaches every person possesses.\n\nAs you continue your recovery journey, remember that healing becomes possible when you begin seeing yourself through the wisdom of your faith instead of through your past.\n\nIn the next lesson, we will explore what it truly means to be created with inherent worth and purpose, and why that truth is essential for lasting recovery."}}]}, {"number": 2, "title": "Created with Inherent Worth and Purpose", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "More Than What You Have Done", "message": "Many people struggling with addiction eventually begin defining themselves by their mistakes. Some see themselves only as addicts. Others see themselves as failures. Many believe they are too damaged to live meaningful lives or to experience spiritual healing.\n\nYet across many belief systems, humanity is understood to possess inherent worth that existed long before failure or addiction entered life. This truth changes everything.\n\nToday we will explore what it means to be created with dignity, purpose, and spiritual value, and why remembering that truth is essential for lasting recovery."}}, {"type": "reading", "content": {"title": "The Worth Within Every Person", "body": "Many teachings describe humanity as holding a unique place within creation. People have been entrusted with the ability to love, to choose wisely, create, learn, build relationships, care for others, and grow spiritually.\n\nThis unique position reminds us that every person possesses value that cannot be measured by success, failure, possessions, or the opinions of others.\n\nDrug abuse and addiction often attacks these very qualities.\n\nInstead of freedom, drug abuse creates bondage.\n\nInstead of clear thinking, it brings confusion.\n\nInstead of healthy relationships, it often creates isolation.\n\nInstead of purpose, it can leave people feeling hopeless.\n\nYet addiction cannot erase the value placed within you.\n\nIt may cloud your thinking.\n\nIt may cover your life with pain and brokenness.\n\nBut it cannot remove your inherent dignity or your ability to heal.\n\nRecovery is not about becoming someone completely different.\n\nRecovery is about rediscovering the person you were always meant to become.\n\nKey Teaching:\n\nReflect on a passage from your own teachings that reminds you of humanity''s dignity, value, or spiritual purpose."}}, {"type": "mentor_note", "content": {"note": "When we understand that our value comes from our Creator and the wisdom of our faith, we become less likely to seek worth through abusing substances, seeking approval, destructive pleasure, or escape."}}, {"type": "video", "content": {"title": "Understanding Your True Identity", "description": "Explain how your belief system teaches that every person possesses inherent worth and purpose, and how addiction can distort a person''s understanding of themselves. Encourage viewers to see themselves as valuable, capable of healing, and created for a meaningful life."}}, {"type": "pause_reflect", "content": {"question": "How would you describe yourself today?", "context": "Reflect further as you answer:\n\nDo you believe you have value apart from your achievements or failures?\n\nHow has drug addiction affected your sense of identity?\n\nWhat would change if you truly believed your worth could never be taken away?\n\nWhich part of yourself would you most like to restore during recovery?"}}, {"type": "journal_prompt", "content": {"prompt": "Find a quiet place and write down:\n\nThree ways addiction has negatively shaped how you see yourself.\n\nThree qualities your faith teaches every person possesses.\n\nOne practical step you can take this week to honor the value that already exists within you."}}, {"type": "mood_checkin", "content": {"question": "How strongly do you feel connected to your own worth and dignity today?"}}, {"type": "daily_action", "content": {"title": "Today''s Action Step", "action": "Spend a few moments in prayer or quiet reflection according to your faith. Give thanks for the value that already exists within you, and ask for wisdom and strength as you continue your recovery journey."}}, {"type": "mentor_note", "content": {"note": "You may have made mistakes.\n\nYou may have hurt yourself and others.\n\nYou may feel broken.\n\nNone of these things determine your worth.\n\nYour value existed before your struggles began and remains with you today.\n\nThe Divine, according to your faith, has not abandoned you. Healing is still possible. Your purpose still exists. Your future can be different from your past.\n\nToday, choose to see yourself through the wisdom and hope of your faith instead of through the lens of addiction.\n\nMemory Reflection:\n\nChoose a passage from your own teachings that reminds you of your value, dignity, or ability to begin again, and spend time reflecting on it today."}}, {"type": "quiz", "content": {"question": "According to this lesson, what determines your worth?", "options": [{"text": "Society''s opinions", "is_correct": false}, {"text": "Your past mistakes", "is_correct": false}, {"text": "The inherent dignity given to every person", "is_correct": true}, {"text": "Your achievements", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Addiction can permanently remove your worth and dignity.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "Which of the following reflects humanity''s intended design?", "options": [{"text": "Hopelessness", "is_correct": false}, {"text": "Isolation", "is_correct": false}, {"text": "Purpose and dignity", "is_correct": true}, {"text": "Bondage", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 2.", "encouragement": "Today you learned that your worth is not determined by your addiction, your past mistakes, or the negative opinions of others. Every person possesses inherent dignity and purpose, and no mistake can erase that truth.\n\nIn the next lesson, we will explore the purpose of life and how understanding that purpose can provide direction, meaning, and hope throughout the recovery journey."}}]}, {"number": 3, "title": "The Purpose of Life", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Why Am I Here?", "message": "One of the most common questions people ask is, \"Why am I here on earth?\" Many people struggling with drug abuse and addiction feel lost, confused, and disconnected from any sense of normal life let alone purpose. Life can begin to feel like an endless cycle of simply getting through each day.\n\nMany belief systems teach that every person was created with real purpose and that each life has meaning. While different religions may express this in different ways, they share the belief that life is not without purpose.\n\nToday we will explore how discovering your purpose can become a powerful part of your recovery journey and help you move toward a healthier future."}}, {"type": "reading", "content": {"title": "Created for More Than Survival", "body": "Many religions teach that humanity was created with purpose with the beginning of creation.\n\nPeople were entrusted with brotherly kindness and caring for others, acting with compassion, serving their communities, protecting creation, growing spiritually, and living according to the values of their faith.\n\nPurpose gives vision.\n\nVision gives meaning.\n\nMeaning gives hope.\n\nOne of the most damaging effects of drug abuse and addiction is that it slowly replaces purpose with survival.\n\nInstead of asking, \"What am I here to do?\" a person begins asking, \"How do I make sense of life?\"\n\nInstead of building a future, they become trapped managing difficulties and consequences.\n\nInstead of pursuing purpose, they pursue temporary relief.\n\nYour faith teaches that life offers more than survival.\n\nYou are called to continue growing, strengthening your character, building healthy relationships, serving others, using your unique gifts, and living according to the values that bring peace, wisdom, and compassion.\n\nRecovery becomes stronger when it is connected to purpose.\n\nWhen people discover something meaningful to live for, they become more willing to protect their healing.\n\nPurpose becomes fuel for recovery.\n\nKey Teaching:\n\nReflect on a passage from your own sacred teachings that speaks about purpose, hope, service, or living a meaningful life."}}, {"type": "mentor_note", "content": {"note": "Addiction often narrows life to immediate needs and temporary relief. Recovery expands life by reconnecting us with a greater purpose."}}, {"type": "video", "content": {"title": "Discovering Your Purpose", "description": "Discuss how abusing drugs can distract people from living meaningful lives and how recovery involves rediscovering the gifts, opportunities, and purpose that exist within each person. Encourage viewers to see recovery as part of a larger journey rather than simply overcoming addiction."}}, {"type": "pause_reflect", "content": {"question": "When was the last time you felt your life had purpose?", "context": "Keep reflecting as you answer:\n\nHow has addiction affected your goals, dreams, or ambitions?\n\nWhat gifts, talents, or strengths do you believe you have?\n\nWhat kind of person would you like to become?\n\nIf addiction no longer controlled your life, what would you pursue?"}}, {"type": "journal_prompt", "content": {"prompt": "Take a notebook and write down:\n\nThree dreams or goals you had before addiction became a major part of your life.\n\nThree strengths or positive qualities you believe have been placed within you.\n\nOne small step you can take this week toward a healthier and more meaningful future."}}, {"type": "mood_checkin", "content": {"question": "How connected do you feel to your life''s purpose today?"}}, {"type": "daily_action", "content": {"title": "Today''s Action Step", "action": "Spend a few quiet moments in prayer or personal reflection according to your faith. Ask for wisdom and guidance as you take one small step toward living with greater purpose and intention."}}, {"type": "mentor_note", "content": {"note": "Your life is not without meaning.\n\nYou were created with value and purpose.\n\nEven if addiction has taken years from your life, it does not have the power to erase your future.\n\nMany people throughout history and across different faith traditions experienced failure, hardship, and brokenness before discovering renewed purpose.\n\nYour story is still unfolding.\n\nYour future does not have to look like your past.\n\nEach step you take in recovery brings you closer to the life you were meant to live.\n\nMemory Reflection:\n\nChoose a passage from your own teachings that inspires hope, purpose, or perseverance, and spend a few moments reflecting on its meaning today."}}, {"type": "quiz", "content": {"question": "According to this lesson, does every person have purpose?", "options": [{"text": "Yes", "is_correct": true}, {"text": "No", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "Which of the following supports a meaningful life?", "options": [{"text": "Living only for temporary relief", "is_correct": false}, {"text": "Avoiding responsibility", "is_correct": false}, {"text": "Serving a greater purpose", "is_correct": true}, {"text": "Remaining isolated", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Addiction often causes people to focus only on survival rather than purpose.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 3.", "encouragement": "Today you discovered that your life has meaning, direction, and purpose. Recovery is not only about leaving something harmful behind—it is also about moving toward the life you were created to live.\n\nIn the next lesson, we will explore the beginning of creation and the lessons it offers about harmony, responsibility, trust, and the foundations of a healthy life."}}]}, {"number": 4, "title": "The Beginning of Creation", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "A Place of Harmony, Relationship, and Trust", "message": "Many faith traditions describe a beginning where humanity lived in harmony with the Divine, with one another, and with creation. The Beginning of Creation represents a place of peace, trust, purpose, and balance.\n\nThis account reminds us that people were never meant to live in constant chaos, emptiness, or slavery to destructive desires. We were created for meaningful relationships, responsible living, and inner peace."}}, {"type": "reading", "content": {"title": "You Were Created for Connection, Not Isolation", "body": "A drug abusive lifestyle often separates people from what matters most. It can damage relationships, weaken spiritual life, and create distance between us, those we love, and even ourselves.\n\nMany faith traditions teach that healing begins by restoring these important connections. Recovery is more than breaking free from substances—it is about rebuilding trust, strengthening relationships, caring for ourselves and others, and reconnecting with our spiritual foundation.\n\nHealthy relationships, clear boundaries, and a life guided by wisdom create an environment where healing can grow.\n\nReflection Question:\n\nHow has addiction pulled you away from healthy relationships with your faith, other people, or yourself?"}}, {"type": "mentor_note", "content": {"note": "Traditional  teachings remind us that humanity was created to live in harmony with the Divine, with others, and with creation."}}, {"type": "video", "content": {"title": "The Garden of Eden", "description": "A mentor-led explanation of how the Beginning of Creation reflects humanity''s original design of harmony, trust, stewardship, meaningful relationships, and inner peace, and how these principles continue to guide recovery today."}}, {"type": "pause_reflect", "content": {"question": "What healthy boundaries or daily habits could help you move closer to a life of balance and peace?", "context": "Think about the areas of your life that feel chaotic, isolated, or unprotected, and consider what changes could help restore greater harmony and stability."}}, {"type": "journal_prompt", "content": {"prompt": "Write down one area of your life where you would like to restore greater balance, peace, or healthy structure this week."}}, {"type": "mood_checkin", "content": {"question": "How ready do you feel to rebuild a life of balance, peace, and healthy relationships today?"}}, {"type": "daily_action", "content": {"title": "Take One Step Toward Peace", "action": "Spend a few moments in prayer or quiet reflection according to your faith. Ask for wisdom, peace, and guidance as you work toward restoring balance in your life."}}, {"type": "mentor_note", "content": {"note": "Your story did not begin with brokenness.\n\nIt began with dignity, purpose, and the possibility of living in harmony.\n\nThe original creation reminds us that healing is possible because restoration has always been part of humanity''s spiritual journey."}}, {"type": "quiz", "content": {"question": "What did the original and undefiled creation represent?", "options": [{"text": "Chaos", "is_correct": false}, {"text": "Harmony, trust, and peace", "is_correct": true}, {"text": "Isolation", "is_correct": false}, {"text": "Fear", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Human beings were created to live under the control of destructive cravings.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "Recovery begins by returning to:", "options": [{"text": "A life guided by wisdom and healthy relationships", "is_correct": true}, {"text": "Secrecy", "is_correct": false}, {"text": "Fear", "is_correct": false}, {"text": "Self-hatred", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 4.", "encouragement": "Today you explored how the Garden of Eden symbolizes humanity''s original design for harmony, trust, and meaningful relationships. Recovery becomes stronger as we rebuild these foundations in our own lives.\n\nIn the next lesson, we will explore how freedom, choice, and responsibility work together to support lasting healing."}}]}, {"number": 5, "title": "Freedom, Choice, and Responsibility", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "True Freedom Is Choosing What Leads to Life", "message": "Many faith traditions teach that humanity has been given the freedom to make choices. This freedom is a gift, but it also carries responsibility. The choices we make shape our character, our relationships, and the purpose of our lives.\n\nRecovery begins when we recognize that while we cannot always control what has happened to us, we can choose how we respond today. Every positive choice, no matter how small, becomes another step toward healing."}}, {"type": "reading", "content": {"title": "Responsibility Opens the Door to Change", "body": "Freedom is not simply doing whatever we want whenever we want. True freedom is the ability to make choices that lead to growth, healing, and lasting peace.\n\nThere are teachings that remind us that every choice carries consequences. Wise choices strengthen us, while destructive choices often lead us further away from the life we hope to build.\n\nDrug abusive behavior often convinces people that they have no control over their future. While addiction is a powerful struggle, recovery invites us to begin making intentional choices again.\n\nTaking responsibility does not mean carrying endless guilt or shame.\n\nIt means honestly acknowledging where we are today, learning from the past, and choosing a healthier path forward.\n\nResponsibility is not punishment.\n\nIt is an opportunity to grow.\n\nReflection Question:\n\nWhat choices have had the greatest influence on your life, both positive and negative?"}}, {"type": "mentor_note", "content": {"note": "Freedom becomes meaningful when it is guided by wisdom, truth, and responsibility."}}, {"type": "video", "content": {"title": "Freedom, Choice, and Responsibility", "description": "A mentor-led explanation of how freedom and responsibility work together, and why the choices we make each day either strengthen or weaken our recovery."}}, {"type": "pause_reflect", "content": {"question": "Where do you need to take responsibility without carrying unnecessary shame?", "context": "Think about the difference between accepting responsibility and condemning yourself. How can taking ownership of your choices help you move toward healing instead of remaining stuck in guilt?"}}, {"type": "journal_prompt", "content": {"prompt": "Write down one choice you can make today that supports your healing and reflects the person you want to become."}}, {"type": "mood_checkin", "content": {"question": "How prepared do you feel to make healthy choices today?"}}, {"type": "daily_action", "content": {"title": "Choose Healing Today", "action": "Spend a few quiet moments in prayer or personal reflection according to your faith. Ask for wisdom, strength, and courage to make one healthy decision before the day ends."}}, {"type": "mentor_note", "content": {"note": "Every wise decision strengthens the life you are building.\n\nTrue freedom grows when your choices are guided by truth, wisdom, and the values of your faith.\n\nEven small decisions, repeated consistently, can transform your future."}}, {"type": "quiz", "content": {"question": "What gives freedom its greatest strength?", "options": [{"text": "Acting on impulse", "is_correct": false}, {"text": "Wisdom and truth", "is_correct": true}, {"text": "Fear", "is_correct": false}, {"text": "Confusion", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Responsibility and shame are the same thing.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "According to this lesson, what strengthens recovery?", "options": [{"text": "Blaming others", "is_correct": false}, {"text": "Making intentional, healthy choices", "is_correct": true}, {"text": "Avoiding responsibility", "is_correct": false}, {"text": "Giving up", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 5.", "encouragement": "Today you learned that freedom is strengthened by responsibility, wisdom, and intentional choices. Every healthy decision you make helps build a stronger foundation for lasting recovery.\n\nIn the next lesson, we will explore how temptation begins, why it can be so convincing, and how recognizing deception can help protect your recovery."}}]}, {"number": 6, "title": "The First Temptation", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Temptation Often Begins by Challenging What We Believe", "message": "Many religious teachings show that temptation is about more than simply making a wrong choice. It often begins by creating doubt, twisting truth, and making harmful choices appear attractive or harmless.\n\nConsistent drug abuse frequently follows the same pattern. It promises comfort, relief, control, or escape, while hiding the pain and consequences that follow.\n\nRecovery becomes stronger when we learn to recognize these deceptive thoughts before they become destructive actions."}}, {"type": "reading", "content": {"title": "Truth Exposes Deception", "body": "Tradition teaches that temptation gains its power through deception. Harmful thoughts often sound convincing because they appeal to our fears, pain, desires, or weaknesses.\n\nCommon thoughts might include:\n\n\"Just this once won''t matter.\"\n\n\"I am still ok.\"\n\n\"No one will ever know.\"\n\n\"I can stop whenever I want.\"\n\nThese thoughts can feel true in the moment, but they often lead us further away from living a normal life with family and friends..\n\nRecovery invites us to pause before acting.\n\nWhen we compare our thoughts with the wisdom found in our faith, we become better equipped to recognize deception and choose a healthier path.\n\nThe more we practice replacing harmful thoughts and actions with truth, the weaker those lies become.\n\nReflection Question:\n\nWhat false beliefs have influenced your choices in the past?"}}, {"type": "mentor_note", "content": {"note": "Temptation often begins with a lie that feels believable."}}, {"type": "video", "content": {"title": "The First Temptation", "description": "A mentor-led explanation of how temptation often begins with deception, distorted thinking, and misplaced trust, and how the wisdom of our faith helps us recognize truth."}}, {"type": "pause_reflect", "content": {"question": "What truths from your faith can help you challenge those false beliefs today?", "context": "Think about the thoughts that have repeatedly led you toward unhealthy choices. Which teachings or principles from your faith remind you of a healthier path?"}}, {"type": "journal_prompt", "content": {"prompt": "Write down:\n\nOne false thought process that has influenced your recovery.\n\nOne truth from your faith or traditional teachings that challenges negative thinking.\n\nOne practical way you can remind yourself of that truth when temptation arises."}}, {"type": "mood_checkin", "content": {"question": "How aware do you feel of deceptive thoughts and false promises today?"}}, {"type": "daily_action", "content": {"title": "Replace Deception with Truth", "action": "Spend a few moments in prayer or quiet reflection according to your faith. Ask for wisdom to recognize harmful thoughts and the strength to choose what leads toward healing."}}, {"type": "mentor_note", "content": {"note": "Every temptation begins with a choice about what we will believe.\n\nThe wisdom found in your faith can help you recognize deception before it becomes destructive.\n\nTemptation is real, but truth, wisdom, and spiritual awareness are stronger when we choose to rely on them."}}, {"type": "quiz", "content": {"question": "What often comes before destructive choices?", "options": [{"text": "Honest wisdom", "is_correct": false}, {"text": "Deception or distorted thinking", "is_correct": true}, {"text": "Perfect understanding", "is_correct": false}, {"text": "Lasting peace", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Temptation often appears harmless at first.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What helps weaken deception?", "options": [{"text": "Keeping it hidden", "is_correct": false}, {"text": "Bringing it into the light through truth and self-awareness", "is_correct": true}, {"text": "Ignoring it", "is_correct": false}, {"text": "Following every feeling", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 6.", "encouragement": "Today you learned that temptation often begins with deception rather than obvious danger. By recognizing harmful thoughts early and responding with the wisdom of your faith, you strengthen your ability to make healthier choices.\n\nIn the next lesson, we will explore how destructive choices affect our lives and how honesty opens the door to healing and restoration."}}]}, {"number": 7, "title": "The Fall of Humanity", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Choices Shape Our Lives and Their Consequences", "message": "Many religious belief systems describe a moment when humanity chose a path that led away from wisdom and harmony. This decision to abandon truth and wisdom in life caused separation, shame, fear, and life changing brokenness into human experience. This you see clearly in today''s life.\n\nDrug abuse and addiction follows in this path of destruction and deterioration of life. It encourages secrecy, isolation, and distance from the people, values, and beliefs that a healthy and holistic life requires.\n\nThis lesson reminds us that while unhealthy choices can have lasting consequences, they do not have to define the rest of our lives. Every faith tradition offers hope that healing, forgiveness, and restoration remain possible."}}, {"type": "reading", "content": {"title": "Shame Hides, but Healing Begins with Honesty", "body": "When people experience guilt or shame, the natural response is often to hide.\n\nWe may hide from others.\n\nWe may hide from our faith community.\n\nWe may even hide from ourselves by denying the truth or avoiding difficult emotions.\n\nAddiction thrives in secrecy.\n\nThe longer pain remains hidden, the stronger it often becomes, the longer the person stays self imprisoned.\n\nMany faith traditions teach that healing begins when we bring our struggles into the light with honesty, humility, and a willingness to change.\n\nBeing honest about our mistakes is not a sign of weakness.\n\nIt is the beginning of freedom.\n\nRecovery becomes possible when we stop hiding and begin facing reality with courage, supported by our faith and by those who genuinely want to help us.\n\nReflection Question:\n\nWhen you feel ashamed or fearful, where do you tend to hide?"}}, {"type": "mentor_note", "content": {"note": "Shame encourages us to hide. Healing begins when we choose honesty."}}, {"type": "video", "content": {"title": "The Fall of Humanity", "description": "A mentor-led explanation of how unhealthy choices can lead to shame, fear, and isolation, and how honesty, compassion, and spiritual guidance help us begin the journey toward restoration."}}, {"type": "pause_reflect", "content": {"question": "What would complete honesty look like in your life today?", "context": "Think about the places where shame has caused you to hide, avoid responsibility, or isolate yourself.\n\nWhat would it look like to begin bringing those areas into the light with courage and humility?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about one area of your life where you are ready to stop hiding and begin living with greater honesty."}}, {"type": "mood_checkin", "content": {"question": "How willing do you feel to face the truth about your life today?"}}, {"type": "daily_action", "content": {"title": "Choose Honesty Today", "action": "Spend a few quiet moments in prayer or personal reflection according to your faith.\n\nBe completely honest about one struggle you have been avoiding, and ask for the wisdom, strength, and courage to begin facing it."}}, {"type": "mentor_note", "content": {"note": "No matter how far you have wandered, healing remains possible.\n\nYour mistakes do not remove your worth.\n\nYour faith reminds you that compassion, forgiveness, and restoration are always greater than shame.\n\nEvery honest step you take brings you closer to freedom."}}, {"type": "quiz", "content": {"question": "What often follows unhealthy choices?", "options": [{"text": "Peace", "is_correct": false}, {"text": "Shame, guilt and hiding", "is_correct": true}, {"text": "Greater freedom", "is_correct": false}, {"text": "Lasting happiness", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Addiction often pushes people toward denial and isolation.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What is one of the first steps toward healing?", "options": [{"text": "Hiding your struggles", "is_correct": false}, {"text": "Honest self-reflection and action", "is_correct": true}, {"text": "Pretending everything is fine", "is_correct": false}, {"text": "Blaming others", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 7.", "encouragement": "Today you learned how shame can lead people into secrecy and isolation, while honesty opens the door to healing and restoration. Recovery grows stronger every time you choose truth over hiding.\n\nIn the next lesson, we will explore how our choices create consequences and how those consequences can become opportunities for growth, wisdom, and lasting change."}}]}, {"number": 8, "title": "The Consequences of Disobedience", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Every Choice Has Consequences", "message": "Our choices shape the direction of our lives and the outcome of our lives. Positive choices often lead to growth, peace, and stronger relationships, while destructive choices can bring pain to ourselves and those around us.\n\nDrug abuse and addiction reflects and enhances this reality even more. What may begin as a private struggle often grows into consequences that affect our health, families, friendships, work, and spiritual well-being. Drug abuse and addiction is a powerful force that causes such havoc.\n\nThe good news is that while we cannot change the past, we can choose how we respond today. Every step toward honesty and healing creates the opportunity for a different future."}}, {"type": "reading", "content": {"title": "Consequences Can Teach, and Healing Can Transform", "body": "Every action produces a result.\n\nCommon teachings remind us that our choices carry consequences—not as punishment alone, but as opportunities to learn, grow, and return to a healthier path.\n\nDrug abuse and addiction often leaves behind broken trust, damaged relationships, emotional pain, financial hardship, and spiritual emptiness.\n\nFacing these consequences can feel overwhelming.\n\nHowever, avoiding them usually allows them to grow more out of control.\n\nRecovery invites us to face reality with honesty, humility, and courage.\n\nWhen we accept responsibility and seek guidance from our faith, painful experiences can become valuable lessons that strengthen our character and deepen our compassion.\n\nHealing does not erase the past.\n\nIt transforms how we live because of it.\n\nReflection Question:\n\nWhat consequences of destructive choices have had the greatest impact on your life?"}}, {"type": "mentor_note", "content": {"note": "Every choice leaves an impact, but every new choice also creates the possibility for healing."}}, {"type": "video", "content": {"title": "The Consequences of Disobedience", "description": "A mentor-led explanation of how destructive choices create consequences, and how honesty, responsibility, and spiritual growth help transform painful experiences into opportunities for lasting recovery."}}, {"type": "pause_reflect", "content": {"question": "How can honesty help you respond differently instead of repeating the same cycle?", "context": "Think about the consequences you are facing today.\n\nHow can truth, responsibility, forgiveness, and the wisdom of your faith help you begin moving forward?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about one consequence you are ready to face honestly, and describe one healthy step you can take this week toward repairing or improving that area of your life."}}, {"type": "mood_checkin", "content": {"question": "How ready do you feel to face the consequences of your choices with honesty and courage today?"}}, {"type": "daily_action", "content": {"title": "Face Today with Courage", "action": "Spend a few moments in prayer or personal reflection according to your faith.\n\nAsk for the courage to face reality honestly, accept responsibility where needed, and continue moving toward healing one step at a time."}}, {"type": "mentor_note", "content": {"note": "Consequences can be painful, but they do not have to define the rest of your life.\n\nMany people discover their greatest growth after facing their greatest struggles with honesty, humility, and faith.\n\nEvery challenge you face with courage becomes another step toward lasting recovery."}}, {"type": "quiz", "content": {"question": "What do consequences often reveal?", "options": [{"text": "That choices have no effect", "is_correct": false}, {"text": "The impact of our choices", "is_correct": true}, {"text": "That hiding solves problems", "is_correct": false}, {"text": "That growth is impossible", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Facing consequences honestly can become part of the healing process.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What can help transform painful consequences into opportunities for growth?", "options": [{"text": "Denial", "is_correct": false}, {"text": "Honest responsibility and spiritual growth", "is_correct": true}, {"text": "Ignoring the problem", "is_correct": false}, {"text": "Blaming others", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 8.", "encouragement": "Today you learned that every choice carries consequences, but those consequences do not have to determine your future. Recovery grows stronger when we face reality honestly, accept responsibility, and allow our faith to guide us toward healing and transformation.\n\nIn the next lesson, we will explore creation, the plant kingdom, and the importance of using the gifts of creation with wisdom and responsibility."}}]}, {"number": 9, "title": "Creation and the Plant Kingdom", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Creation Was Given to Support Life, Not Harm It", "message": "Certain traditions teach that the plant and vegetation creation was given as a gift to sustain life and provide for humanity. The natural world offers food to eat, medicine for all ailments, and many other elements in nature being the resource for people to use wisely for the benefit of all.\n\nLike any gift, however, what is good can become harmful when it is misused or abused.\n\nThis lesson reminds us that the greatest challenge is often not the gift itself, but how we choose to use it. Recovery invites us to approach life''s gifts with wisdom, gratitude, and responsibility."}}, {"type": "reading", "content": {"title": "Wisdom Guides the Way We Use What Has Been Given", "body": "Many sacred teachings encourage people to care for creation with respect and responsibility.\n\nThe natural world provides many things that support life and healing, but human choices determine whether those gifts are used wisely or abused.\n\nThroughout history, people have discovered both beneficial and harmful uses for the same natural resources.\n\nThe difference often lies in intention, self-control, and wisdom.\n\nAddiction reminds us that even something that appears harmless can become destructive when it is used to escape pain, avoid responsibility, or satisfy unhealthy desires.\n\nRecovery teaches us to develop wisdom in what we do in life rather than simply seeking temporary relief.\n\nWhen we learn to respect both ourselves and the gifts of resources found in creation, we become better equipped to make choices that promote a healthy life, instead of harm.\n\nReflection Question:\n\nCan you think of something good that became harmful because it was used without wisdom or self-control?"}}, {"type": "mentor_note", "content": {"note": "The value of a gift is revealed by the wisdom with which it is used."}}, {"type": "video", "content": {"title": "Creation and the Plant Kingdom", "description": "A mentor-led explanation of how many faith traditions teach respect for creation, responsible stewardship, and the importance of using life''s gifts with wisdom rather than misuse."}}, {"type": "pause_reflect", "content": {"question": "What does wise stewardship look like in your everyday life?", "context": "Reflect on the difference between appreciating life''s gifts with gratitude and using them in ways that create harm.\n\nHow can your faith help guide your choices?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about one gift, ability, relationship, or resource in your life that you want to use more wisely as you continue your recovery journey."}}, {"type": "mood_checkin", "content": {"question": "How mindful do you feel about making wise choices with the gifts and opportunities in your life today?"}}, {"type": "daily_action", "content": {"title": "Choose Wisdom Today", "action": "Spend a few quiet moments in prayer or personal reflection according to your faith.\n\nExpress gratitude for one blessing in your life, and ask for wisdom to use your abilities, relationships, and resources in ways that support healing and growth."}}, {"type": "mentor_note", "content": {"note": "Life offers many gifts.\n\nWisdom teaches us how to receive them with gratitude, respect, and self-control.\n\nThe choices we make determine whether those gifts become sources of healing and progressive living or sources of harm."}}, {"type": "quiz", "content": {"question": "What often turns a good gift into something harmful?", "options": [{"text": "Owning it", "is_correct": false}, {"text": "Using it without wisdom or self-control", "is_correct": true}, {"text": "Being thankful for it", "is_correct": false}, {"text": "Sharing it with others", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: The problem is always the gift itself rather than how people choose to use it.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What helps us use life''s gifts in healthy ways?", "options": [{"text": "Impulse", "is_correct": false}, {"text": "Wisdom and responsible stewardship", "is_correct": true}, {"text": "Ignoring consequences", "is_correct": false}, {"text": "Isolation", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 9.", "encouragement": "Today you learned that creation offers many gifts, but wisdom determines how those gifts are used. Recovery grows stronger as we learn to approach life with gratitude, responsibility, and self-control.\n\nIn the final lesson of this chapter, we will bring these principles together to better understand the deeper roots of drug abuse and the path toward lasting healing."}}]}, {"number": 10, "title": "Understanding the Origins of Drug Abuse", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Drug Abuse Is About More Than the Substance", "message": "Drug abuse is rarely only about the substance itself. It is often rooted in deeper emotional, mental, and spiritual needs, but what makes inducing drugs unique is that it makes the person feel good.\n\nPeople may initially turn to drugs when advised that it makes your body and person feel good. Although substances may seem to offer temporary comfort, they cannot provide lasting good feeling effects, hence the reason the person uses drugs again and again that eventually leads to addiction.\n\nRecovery begins when we are willing to look beyond the good feeling drug gives the person and honestly explore what our hearts, minds, and spirits have truly been searching for."}}, {"type": "reading", "content": {"title": "Healing Begins at the Root", "body": "Lasting healing comes from addressing the root of a problem rather than only its outward symptoms.\n\nDrug abuse often develops for many reasons, and it''s normally personal to the individual. Each person is created differently and has different qualities under the same elements that make up all humanity. And it''s often this search for meaning and understanding in life that makes people fall to the temptation, the voice that lies and misleads people to abuse drugs.\n\nWhile substances may temporarily numb common inner pain and difficult experiences, they do not remove the underlying causes, which could be a desire to seek fulfilment, peace and understanding of life.\n\nRecovery invites us to slow down and ask deeper questions:\n\nWhat am I trying to escape?\n\nWhat fears continue to influence my decisions?\n\nWhat needs and desires remain unmet?\n\nWhat am I truly searching for?\n\nAs we answer these questions honestly, we create some space for genuine healing.\n\nOur faith reminds us that transformation begins within. When our hearts, minds, and spirits begin to heal, our choices gradually begin to change as well.\n\nUnderstanding the root of drug abuse and addiction allows us to stop treating only the symptoms and begin looking to inner fulfillment to lasting freedom.\n\nReflection Question:\n\nWhat do you believe your heart has been searching for through destructive choices?"}}, {"type": "mentor_note", "content": {"note": "Addiction often grows where emotional pain, unhealthy beliefs, and spiritual disconnection remain unaddressed."}}, {"type": "video", "content": {"title": "Understanding the Origins of Drug Abuse", "description": "A mentor-led explanation of how emotional pain, unhealthy thinking, shame, trauma, and the desire to escape can contribute to addiction, and why lasting recovery begins by healing the deeper issues beneath the surface."}}, {"type": "pause_reflect", "content": {"question": "How can honesty become the beginning of real change?", "context": "Consider the deeper needs beneath your addiction.\n\nWhat emotional, mental, or spiritual needs have you been trying to satisfy through substances?\n\nHow might your faith help you begin meeting those needs in healthier ways?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about one root issue you are ready to face honestly.\n\nDescribe one practical step you can take this week toward healing that deeper part of your life."}}, {"type": "mood_checkin", "content": {"question": "How ready do you feel to honestly explore the deeper causes of your struggle today?"}}, {"type": "daily_action", "content": {"title": "Begin at the Root", "action": "Spend a few quiet moments in prayer or personal reflection according to your faith.\n\nAsk for wisdom, courage, and understanding as you begin facing the deeper needs beneath your addiction with honesty and hope."}}, {"type": "mentor_note", "content": {"note": "Lasting freedom begins when we understand the roots beneath our struggles.\n\nThe more honestly we understand ourselves, the more intentionally we can move toward healing and a productive life.\n\nRecovery is not simply about stopping destructive behavior.\n\nIt is about becoming whole again, body, soul and spirit."}}, {"type": "quiz", "content": {"question": "What often lies beneath drug abuse?", "options": [{"text": "Only the substance itself", "is_correct": false}, {"text": "Emotional pain, unhealthy thinking, and spiritual struggles", "is_correct": true}, {"text": "A lack of intelligence", "is_correct": false}, {"text": "Nothing at all", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Lasting healing begins when we honestly face the deeper causes of our struggles.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "According to this lesson, what can become the beginning of real change?", "options": [{"text": "Hiding from the truth", "is_correct": false}, {"text": "Honest self-reflection supported by faith", "is_correct": true}, {"text": "Denying your struggles", "is_correct": false}, {"text": "Numbing emotional pain", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 10.", "encouragement": "Today you discovered that drug abuse and addiction is often rooted in deeper emotional, mental, and spiritual needs rather than the drug and substances alone. By honestly exploring these roots and allowing your faith to guide your healing, you are building a stronger foundation for lasting recovery and a better life.\n\nThis chapter has taken you from humanity''s original purpose to a deeper understanding of the roots of addiction. Carry these insights with you as you continue your journey into the next chapter, where you will continue building the knowledge, wisdom, and practical skills needed for lifelong recovery."}}]}]}, {"number": 2, "title": "The Tree of Knowledge of Good and Evil", "description": "Chapter 2 explores how brokenness became part of the human experience and how it continues to influence our desires, choices, identity, and addictions. It examines the meaning of the forbidden tree as a symbol, also as symbolic truth and real physical chemical potency. The progression from temptation to destructive choices, the impact of brokenness on human nature, spiritual disconnection, inherited patterns, addictive cycles, the consequences of our actions, and the journey toward restoration.\n\nThe goal of this chapter is to help you understand that addiction is connected to deeper emotional, spiritual, and human realities. Lasting recovery becomes possible when we recognize unhealthy beliefs, face the consequences of our choices with honesty, and embrace the path of healing, restoration, and renewed purpose offered through our faith.", "lessons": [{"number": 1, "title": "Understanding the Forbidden Tree", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "This Chapter Begins Where Trust Was Tested", "message": "The story of the Tree of the Knowledge of Good and Evil is an account where the command from God to the man and woman was not to partake of the fruit of the tree of the knowledge of good and evil. Across many faith traditions, it represents a moment when obedience, wisdom, and human desire were tested. The disobedience of the command from God not to eat of the forbidden fruit was the key, disobedience of the command of His Word, His Truth.\n\nTo understand actions like drug abuse and addiction, we must also understand how unhealthy desires develop and what happens when we begin questioning the boundaries that are meant to protect us.\n\nThis lesson explores why healthy boundaries matter and how respecting them becomes an important part of lasting recovery."}}, {"type": "reading", "content": {"title": "Healthy Boundaries Reveal the Condition of the Heart", "body": "Many teachings describe boundaries as acts of wisdom and protection rather than punishment.\n\nThe forbidden tree represented a clear boundary. The issue was not that the tree itself was evil, but that it marked a limit that invited humanity to choose obedience, trust and wisdom over immediate desire to fulfil human senses.\n\nDrug abuse and addiction often follows a similar pattern.\n\nA person encounters a healthy limit.\n\nThey begin questioning whether that limit is really necessary.\n\nThe mind starts imagining that crossing the boundary will bring freedom, relief, pleasure, or happiness.\n\nEventually, desire becomes stronger than wisdom.\n\nThis teaches us that destructive behavior usually begins long before the action itself.\n\nIt begins when we negotiate with our values instead of honoring them.\n\nRecovery requires learning to see healthy boundaries as protection rather than restriction.\n\nThe boundaries that support recovery are not there to limit your life—they exist to protect your healing, your relationships, your future, and your peace.\n\nReflection Question:\n\nWhat healthy boundaries have been most difficult for you to respect during your recovery journey?"}}, {"type": "mentor_note", "content": {"note": "The way we respond to healthy boundaries often reveals what we truly believe about trust, wisdom, and ourselves."}}, {"type": "video", "content": {"title": "Understanding the Forbidden Tree", "description": "A mentor-led explanation of why the forbidden tree represented trust, wisdom, and healthy boundaries, and how temptation often begins by convincing us that protection is actually restriction."}}, {"type": "pause_reflect", "content": {"question": "Which healthy boundaries do you struggle with most when your desires become strong?", "context": "Think about what happens inside you when a boundary feels frustrating or restrictive.\n\nIs the problem the boundary itself, or the way you respond to it?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about one boundary you know is important for your recovery.\n\nWhy has it been difficult to maintain?\n\nHow could respecting that boundary strengthen your healing?"}}, {"type": "mood_checkin", "content": {"question": "How willing do you feel to respect healthy boundaries today?"}}, {"type": "daily_action", "content": {"title": "Honor One Healthy Boundary Today", "action": "Choose one boundary that protects your recovery and commit to respecting it today without negotiating or making excuses."}}, {"type": "mentor_note", "content": {"note": "Healthy boundaries are not meant to reduce your freedom.\n\nThey exist to protect your well-being, strengthen your character, and help you become the person your faith calls you to be."}}, {"type": "quiz", "content": {"question": "What did the forbidden tree represent in this lesson?", "options": [{"text": "A meaningless object", "is_correct": false}, {"text": "A test of obedience, wisdom, and healthy boundaries", "is_correct": true}, {"text": "Random punishment", "is_correct": false}, {"text": "An excuse for failure", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Destructive behavior often begins before the action itself.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What does lasting recovery require regarding healthy boundaries?", "options": [{"text": "Ignoring them", "is_correct": false}, {"text": "Resenting them", "is_correct": false}, {"text": "Respecting life-giving boundaries", "is_correct": true}, {"text": "Replacing them with impulse", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 1.", "encouragement": "Today you discovered that temptation often begins with the way we think about healthy boundaries. Recovery becomes stronger when we stop seeing boundaries as restrictions and begin recognizing them as protection for our healing and future.\n\nIn the next lesson, we will explore how destructive choices begin—not simply with temptation, but with the moment we choose to believe unhealthy thoughts and eventually act upon them."}}]}, {"number": 2, "title": "The Entrance of Destructive Choices", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Destructive Choices Begin When We Accept Deception", "message": "Destructive choices rarely begin the moment we act. They usually begin much earlier—when we accept a false belief as truth. There is Christian scriptures that claim the heart is evil above all else, meaning evil desire is already in the heart from the first action of disobedience since all creation.\n\nMany faith traditions teach that harmful actions grow from unhealthy thinking, distorted desires, or beliefs that pull us away from wisdom. Drug abuse and addiction often follows this same pattern.\n\nUnderstanding how this process unfolds helps us recognize destructive thinking before it becomes destructive behavior."}}, {"type": "reading", "content": {"title": "Destructive Choices Grow Through Agreement with False Beliefs", "body": "Many religious and cultural teachings show that temptation could begin with an idea in the heart, and destructive choices develop when we accept that idea either as true or not but allow it to guide our actions.\n\nDrug abuse has a similar pattern of progression.\n\nA thought appears.\n\nThat thought becomes a justification.\n\nThe justification becomes a choice.\n\nThe choice becomes an action.\n\nMany people focus only on the visible behavior while overlooking the beliefs that came before it and connected to it.\n\nReal recovery begins by examining those deeper beliefs.\n\nWhen we believe statements such as:\n\n\"This will make me feel better.\"\n\n\"I deserve this.\"\n\n\"One more time won''t matter.\"\n\n\"Nothing else will help.\"\n\nWe slowly give those thoughts permission to influence our choices.\n\nRecovery is not only about developing stronger self-control.\n\nIt is also about learning to recognize false beliefs, challenge them with the wisdom of our faith, and replace them with truth.\n\nThe more we refuse to agree with harmful thinking, the stronger our recovery becomes.\n\nReflection Question:\n\nWhat unhealthy beliefs have you accepted during moments of weakness?"}}, {"type": "mentor_note", "content": {"note": "The moment we accept a false belief, we move one step closer to acting on it."}}, {"type": "video", "content": {"title": "The Entrance of Destructive Choices", "description": "A mentor-led explanation of how temptation develops through deception, unhealthy thinking, agreement, and action, and why replacing false beliefs with truth is essential for lasting recovery."}}, {"type": "pause_reflect", "content": {"question": "What false beliefs have influenced your choices most often?", "context": "Look beneath your behavior and ask yourself:\n\nWhat belief made that behavior seem reasonable?\n\nWhat emotional need was I trying to satisfy?\n\nWhat truth from my faith challenges that belief?"}}, {"type": "journal_prompt", "content": {"prompt": "Write down:\n\nOne destructive behavior you want to overcome.\n\nThe false belief that usually comes before it.\n\nOne truth from your faith that challenges that belief."}}, {"type": "mood_checkin", "content": {"question": "How aware are you of the thoughts and beliefs influencing your choices today?"}}, {"type": "daily_action", "content": {"title": "Replace One False Belief Today", "action": "Identify one unhealthy belief you often struggle with.\n\nWrite it down.\n\nThen replace it with a healthier truth based on your faith and read it aloud several times today."}}, {"type": "mentor_note", "content": {"note": "Freedom grows when we stop treating harmful beliefs as possibilities and begin recognizing them for what they truly are.\n\nEvery truth you choose weakens the power of deception."}}, {"type": "quiz", "content": {"question": "According to this lesson, destructive choices usually begin when:", "options": [{"text": "Temptation appears", "is_correct": false}, {"text": "We accept false beliefs and act on them", "is_correct": true}, {"text": "Difficult circumstances arise", "is_correct": false}, {"text": "We experience uncomfortable emotions", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Self-control alone is enough if unhealthy beliefs remain unchanged.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What should recovery help us break?", "options": [{"text": "Every emotion", "is_correct": false}, {"text": "Agreement with unhealthy beliefs", "is_correct": true}, {"text": "Every desire", "is_correct": false}, {"text": "Every boundary", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 2.", "encouragement": "Today you learned that destructive choices often begin long before the behavior itself. They begin when unhealthy beliefs are accepted without being questioned. As you continue your recovery journey, practice recognizing those beliefs and replacing them with the wisdom and truth found in your faith.\n\nIn the next lesson, we will explore how brokenness affects human nature and why lasting recovery must reach deeper than outward behavior."}}]}, {"number": 3, "title": "How Brokenness Changed Human Nature", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Brokenness Affects More Than Our Actions", "message": "Religions and traditions teach that in the beginning when humanity turned away from wisdom and truth, the effects reached far beyond individual actions. Fear, shame, confusion, self-protection, and inner conflict became part of the human experience.\n\nUnderstanding this helps us recognize that addiction is not simply about behavior. It often reflects deeper emotional, mental, and spiritual struggles that need healing."}}, {"type": "reading", "content": {"title": "Brokenness Begins Within Before It Appears Outwardly", "body": "Brokenness changes the way people relate to themselves, to others, and affects our spiritual life.\n\nWhere trust once existed, fear may take its place.\n\nWhere peace once existed, confusion may grow.\n\nWhere openness once existed, people may begin hiding behind shame, blame, or isolation.\n\nThese inner struggles often create the conditions in which drug addiction and other addictions develops.\n\nMany people turn to substances not simply because they want to use them, but because they are searching for answers, identity, belonging, freedom , acceptance and the like. Many seem to search in alternative or wrong places.\n\nThis reminds us that drug abuse is not as simple as many think it is.\n\nIt often reflects wounds or desires that exist much deeper.\n\nRecovery therefore involves more than changing behavior.\n\nIt also involves renewing the way we think, strengthening our beliefs, healing emotional wounds, and allowing our hearts and minds to grow through the wisdom of our faith.\n\nAs our inner lives become healthier, our outward choices begin to change naturally.\n\nReflection Question:\n\nWhere do you notice inner struggles influencing your daily choices?"}}, {"type": "mentor_note", "content": {"note": "When inner healing begins, healthier choices often follow."}}, {"type": "video", "content": {"title": "How Brokenness Changed Human Nature", "description": "A mentor-led explanation of how brokenness affects the inner life and why addiction often reflects deeper emotional, mental, and spiritual struggles rather than behavior alone."}}, {"type": "pause_reflect", "content": {"question": "Where do you see inner struggles affecting your life today?", "context": "Think about feelings such as fear, shame, loneliness, anger, confusion, guilt, or the need to fit into society.\n\nHow might these struggles be influencing your decisions?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about one inner struggle that repeatedly appears beneath your outward behavior.\n\nHow has it influenced your recovery journey?\n\nWhat healthy step could you begin taking to address it?"}}, {"type": "mood_checkin", "content": {"question": "How aware are you of your deeper emotional and spiritual struggles today?"}}, {"type": "daily_action", "content": {"title": "Face One Inner Struggle Honestly", "action": "Spend a few quiet moments in prayer or personal reflection according to your faith.\n\nChoose one inner struggle you normally avoid and bring it into the light with honesty, asking for wisdom, healing, and strength."}}, {"type": "mentor_note", "content": {"note": "Real healing reaches far deeper than changing behavior, and has to begin in the heart.\n\nAs your inner life becomes healthier, your choices become healthier as well.\n\nLasting recovery begins deep within."}}, {"type": "quiz", "content": {"question": "According to this lesson, what changed as brokenness became part of the human experience?", "options": [{"text": "Only external rules", "is_correct": false}, {"text": "Human nature and the inner life", "is_correct": true}, {"text": "Only physical health", "is_correct": false}, {"text": "Nothing significant", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Addiction is only a surface behavior problem.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What does lasting recovery require?", "options": [{"text": "Only changing outward behavior", "is_correct": false}, {"text": "Renewal of thoughts, beliefs, emotions, and inner life", "is_correct": true}, {"text": "Only stronger discipline", "is_correct": false}, {"text": "Only avoiding consequences", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 3.", "encouragement": "Today you learned that addiction often reflects deeper emotional, mental, and spiritual struggles rather than behavior alone. Lasting recovery becomes possible when healing reaches the heart, the mind, and the beliefs that shape your life.\n\nIn the next lesson, we will explore spiritual disconnection, the emptiness it can create, and how reconnecting with your faith can become an important part of lasting recovery."}}]}, {"number": 4, "title": "Understanding Spiritual Disconnection", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Spiritual Disconnection Creates an Inner Emptiness", "message": "Many religions teach that people are created with a spiritual dimension or spiritual man that longs for connection with the Divine. When that connection weakens or is neglected, people may experience feelings of emptiness, loneliness, confusion, or restlessness.\n\nMany individuals unknowingly try to fill that emptiness with temporary comforts, including illegal substances, abuse of legal substances, unhealthy relationships, material possessions, unhealthy sexual encounters and anything that causes spiritual bondage.\n\nThis lesson explores how spiritual disconnection can contribute to susceptibility to drug abuse and eventual addiction and why reconnecting with your faith can become an important part of lasting recovery."}}, {"type": "reading", "content": {"title": "Temporary Solutions Cannot Fill Lasting Spiritual Needs", "body": "Some teachings describe the human spirit as longing for truth, peace, purpose, love, and connection with the Divine.\n\nWhen those deeper needs go unmet, people often experience an inner emptiness that they struggle to explain.\n\nThat emptiness may appear as:\n\nRestlessness\n\nLoneliness\n\nAnxiety\n\nFear\n\nDissatisfaction\n\nA constant search for something more\n\nSeeking to fill those parts of our lives often get filled with another vice.\n\nPeople may turn to abusing substances because they provide temporary relief from emotional or spiritual confusion or satisfaction.\n\nHowever, while abusing substances may entertain for a short time, they cannot provide the lasting peace, purpose, or healing that the human spirit truly seeks.\n\nRecovery invites us to recognize the difference between temporary entertainment and satisfaction as opposed to a healthy mind and body lifestyle.\n\nAs we strengthen our spiritual lives through prayer, reflection, community, and the practices of our faith, we begin filling those deeper needs in healthier and more lasting ways.\n\nReflection Question:\n\nWhere have you looked for lasting peace in places that could only offer temporary relief?"}}, {"type": "mentor_note", "content": {"note": "Temporary comfort may quiet pain for a moment, but lasting healing begins by nourishing the spirit."}}, {"type": "video", "content": {"title": "Understanding Spiritual Disconnection", "description": "A mentor-led explanation of how spiritual disconnection can contribute to feelings of emptiness and why reconnecting with the wisdom, practices, and hope found in one''s faith supports lasting recovery."}}, {"type": "pause_reflect", "content": {"question": "Where have you tried to fill emotional or spiritual emptiness with something that could never truly satisfy?", "context": "Reflect on whether your coping strategies have been attempts to escape loneliness, fear, uncertainty, grief, or a deeper longing for meaning and connection."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one area of unfulfilled desire you have been trying to manage through drug abuse rather than sober healing.\n\nDescribe one healthy spiritual practice that could help you begin addressing that need."}}, {"type": "mood_checkin", "content": {"question": "How connected do you feel to your spiritual life and your faith today?"}}, {"type": "daily_action", "content": {"title": "Nourish Your Spirit Today", "action": "Spend a few quiet moments in prayer, meditation, or personal reflection according to your faith.\n\nAsk for wisdom, peace, and guidance as you seek healthier ways to care for your emotional and spiritual well-being."}}, {"type": "mentor_note", "content": {"note": "Many cravings point toward a deeper need.\n\nAs we strengthen our connection with our faith, we often discover that what we truly long for cannot be found in temporary escape, but in lasting peace, purpose, and spiritual growth."}}, {"type": "quiz", "content": {"question": "According to this lesson, what can spiritual disconnection create?", "options": [{"text": "Lasting peace", "is_correct": false}, {"text": "Inner emptiness and lack of purpose", "is_correct": true}, {"text": "Perfect happiness", "is_correct": false}, {"text": "Freedom from struggle", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Temporary comfort can permanently satisfy deeper spiritual needs.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What supports lasting healing?", "options": [{"text": "Escaping difficult emotions", "is_correct": false}, {"text": "Strengthening your spiritual life through your faith", "is_correct": true}, {"text": "Ignoring deeper needs", "is_correct": false}, {"text": "Depending only on temporary relief", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 4.", "encouragement": "Today you explored how spiritual disconnection can contribute to drug abuse and  addiction and why lasting recovery involves caring for your emotional, mental, and spiritual well-being. As you continue strengthening your connection with your faith, you build a stronger foundation for healing, peace, and lasting freedom.\n\nIn the next lesson, we will explore inherited patterns of brokenness and learn how understanding them can help us respond with honesty, hope, and personal responsibility."}}]}, {"number": 5, "title": "Understanding Inherited Patterns of Brokenness", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Broken Patterns Often Have Deep Roots", "message": "Many people discover that some unhealthy patterns seem to have been present long before the person became aware of them. It is not always that drug abuse and addiction is influenced by family experiences, childhood environments, personal trauma, culture, or generations of learned behavior. Drug and substance abuse could just be a sign and symptom of an already broken spiritual environment or life born into.\n\nUnderstanding these deeper patterns does not remove personal responsibility, but it helps us approach recovery with greater honesty, compassion, and hope.\n\nThis lesson explores how recognizing long-standing patterns can help us break free from them instead of allowing them to define our future."}}, {"type": "reading", "content": {"title": "Understanding the Struggle Without Accepting Defeat", "body": "Many faith traditions teach that humanity shares common struggles such as fear, pride, selfishness, avoidance, unhealthy desires, and emotional brokenness.\n\nThese patterns often influence the way people think, react, and cope with life''s challenges.\n\nDrug abuse and addiction frequently grows alongside other social issues like other forms of abuse that perhaps occur in the house or the living environment.\n\nRecognizing these additional influences of abuse could be used as a reason for drug abuse and not have the real clarity we need.\n\nIf the reasons and real signs and symptoms are not brought under truth, our perception of freedom from drug abuse and addiction can be more difficult.\n\nRecovery begins when we stop denying our struggles while also refusing to believe they are permanent.\n\nYour past may explain some of your challenges.\n\nIt does not determine your future.\n\nHealing becomes possible when we honestly acknowledge unhealthy patterns, seek guidance through our faith, and intentionally choose healthier ways of thinking and living.\n\nThe goal is not to become discouraged by what has shaped you.\n\nThe goal is to become empowered to grow beyond it.\n\nReflection Question:\n\nWhat recurring emotional, mental, or behavioral patterns continue to appear in your life?"}}, {"type": "mentor_note", "content": {"note": "Understanding your struggles should lead to greater humility, self-awareness, and hope—not hopelessness."}}, {"type": "video", "content": {"title": "Understanding Inherited Patterns of Brokenness", "description": "A mentor-led explanation of how long-standing patterns develop, why they can feel deeply rooted, and how faith, personal responsibility, and intentional growth help break unhealthy cycles."}}, {"type": "pause_reflect", "content": {"question": "Which recurring patterns seem to influence your life the most?", "context": "Think about repeated habits, emotional reactions, fears, beliefs, or coping mechanisms that continue to appear during difficult situations.\n\nHow have these patterns affected your recovery?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about one recurring pattern you are ready to confront.\n\nDescribe:\n\nWhere you think it began.\n\nHow it affects your life today.\n\nOne healthy step you can take this week to begin changing it."}}, {"type": "mood_checkin", "content": {"question": "How hopeful do you feel about changing long-standing patterns in your life?"}}, {"type": "daily_action", "content": {"title": "Acknowledge the Pattern and Choose a New Direction", "action": "Identify one unhealthy pattern you often repeat.\n\nSpend a few moments in prayer or personal reflection according to your faith, asking for wisdom, strength, and perseverance as you begin replacing that pattern with healthier choices."}}, {"type": "mentor_note", "content": {"note": "Your past may explain some of your struggles, but it does not have to determine your future.\n\nWith honesty, perseverance, and the guidance of your faith, long-standing patterns can be transformed into opportunities for growth and healing."}}, {"type": "quiz", "content": {"question": "According to this lesson, what can understanding long-standing patterns help us do?", "options": [{"text": "Accept defeat", "is_correct": false}, {"text": "Understand the struggle while working toward change", "is_correct": true}, {"text": "Avoid responsibility", "is_correct": false}, {"text": "Believe change is impossible", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Understanding the roots of unhealthy patterns means you are no longer responsible for your choices.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What strengthens lasting recovery?", "options": [{"text": "Denying unhealthy patterns", "is_correct": false}, {"text": "Honest self-awareness combined with hope and action", "is_correct": true}, {"text": "Believing nothing can change", "is_correct": false}, {"text": "Blaming the past for every decision", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 5.", "encouragement": "Today you learned that many unhealthy patterns have deep roots, but they do not have to define your future. Recovery becomes stronger when you understand your struggles with honesty while believing that lasting change is possible through faith, wisdom, and intentional action.\n\nIn the next lesson, we will explore addiction and the human condition, examining why people seek false solutions to real pain and how understanding those deeper needs supports lasting recovery."}}]}, {"number": 6, "title": "Addiction and the Human Condition", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Addiction Reflects a Deeper Human Struggle", "message": "Drug abuse and addiction is not simply a problem experienced by a few people. It reflects many of the same emotional, mental, and spiritual struggles that people across all walks of life face.\n\nPain, fear, loneliness, shame, unmet needs, and the desire for relief are part of the human experience. Drug abuse and addiction is a strong bondage that visibly destroys lives, and keeps other inner issues embedded in the person''s life without proper realization.\n\nUnderstanding this helps us replace judgment with compassion and position ourselves to be strong in this battle."}}, {"type": "reading", "content": {"title": "Addiction Often Magnifies Deeper Human Struggles", "body": "Traditional beliefs recognize that every person experiences inner conflict.\n\nPeople naturally seek peace, belonging, comfort, purpose, security,hope and spirituality.\n\nWhen these needs remain unmet, many begin searching for relief in unhealthy places.\n\nAddiction often follows a familiar cycle:\n\nPain creates behavior dysfunction.\n\nDysfunction creates the desire for relief.\n\nRelief appears through a temporary solution.\n\nTemporary relief strengthens unhealthy habits.\n\nThose habits create greater pain.\n\nThe cycle then begins again.\n\nThis is why addiction often feels repetitive and difficult to escape.\n\nThe substance itself is very addictive after consistent drug abuse.\n\nIt soon becomes a lifestyle choice.\n\nRecovery invites us to ask deeper questions.\n\nInstead of asking only, \"How do I stop using it?\" we also ask:\n\nWhat pain am I trying to escape?\n\nWhat emotional need remains unmet?\n\nWhat am I truly searching for?\n\nHow can my faith help me meet these needs in healthier ways?\n\nAs we understand the deeper causes of addiction, we become better equipped to build lasting recovery instead of temporary relief.\n\nReflection Question:\n\nWhat deeper need has your addiction been trying to satisfy?"}}, {"type": "mentor_note", "content": {"note": "When we understand the deeper need beneath our addiction, we become better prepared to find healthier solutions."}}, {"type": "video", "content": {"title": "Addiction and the Human Condition", "description": "A mentor-led explanation of how emotional pain, unmet needs, unhealthy beliefs, and the search for relief contribute to addiction, and how understanding these deeper struggles supports lasting recovery."}}, {"type": "pause_reflect", "content": {"question": "What has your heart been searching for through destructive behavior?", "context": "Think beyond the substance itself.\n\nHave you been seeking:\n\nIdentity?\n\nPeace?\n\nAcceptance?\n\nBelonging?\n\nPurpose?\n\nUnderstanding of life?\n\nRelief from emotional pain?\n\nHow could these needs be met in healthier ways?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about the deeper need you believe has most often influenced your addiction.\n\nThen describe one healthy way you can begin meeting that need through your faith, supportive relationships, or positive daily habits."}}, {"type": "mood_checkin", "content": {"question": "How honestly do you feel you are facing the deeper causes of your addiction today?"}}, {"type": "daily_action", "content": {"title": "Look Beneath the Surface", "action": "Spend a few moments in prayer or personal reflection according to your faith.\n\nComplete this sentence in your journal:\n\n\"My addiction has often been an attempt to find...\"\n\nAllow yourself to answer honestly without judging yourself."}}, {"type": "mentor_note", "content": {"note": "Healing becomes stronger when we understand the root of addiction and begin understanding the deeper levels of our heart. That''s where true healing starts.\n\nWhen the true need is recognized, healthier paths toward healing become possible."}}, {"type": "quiz", "content": {"question": "According to this lesson, addiction often magnifies:", "options": [{"text": "Poor discipline alone", "is_correct": false}, {"text": "Deeper emotional, mental, and spiritual struggles", "is_correct": true}, {"text": "Curiosity only", "is_correct": false}, {"text": "Outside pressure alone", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Addiction is only about access to substances.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "Which question best supports lasting recovery?", "options": [{"text": "How can I hide my addiction?", "is_correct": false}, {"text": "What deeper heart levels need correction?", "is_correct": true}, {"text": "How can I avoid uncomfortable emotions?", "is_correct": false}, {"text": "Why does recovery take time?", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 6.", "encouragement": "Today you learned that addiction often reflects deeper emotional, mental, and spiritual struggles rather than the substance alone. Lasting recovery begins when you understand those deeper needs and start meeting them through healthier choices, supportive relationships, and the guidance of your faith.\n\nIn the next lesson, we will explore the fruit of destructive choices and learn how honestly recognizing their impact can strengthen your commitment to lasting recovery."}}]}, {"number": 7, "title": "Recognizing the Fruit of Destructive Choices", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Every Choice Produces Results", "message": "Every decision we make shapes the direction of our lives, even when the results are not immediately visible.\n\nOur actions eventually produce an outcome, whether good or bad. Healthy choices tend to produce growth, peace, and stronger relationships, while destructive choices often lead to pain, instability, and further struggle.\n\nRecovery becomes clearer when we honestly examine what our choices have been producing over time."}}, {"type": "reading", "content": {"title": "The Results Reveal the Pattern", "body": "One of the most effective ways to understand whether a pattern is healthy is to examine its results.\n\nDestructive choices often promise immediate comfort while hiding their long-term consequences.\n\nAddiction is a powerful example of this.\n\nIt may provide temporary relief, but over time it often produces:\n\nBroken trust\n\nDamaged relationships\n\nPoor physical and emotional health\n\nFinancial hardship\n\nIsolation\n\nShame\n\nLoss of peace\n\nSpiritual disconnection\n\nMany people remain trapped because they focus only on the temporary relief while ignoring the lasting consequences.\n\nRecovery begins when we become willing to honestly evaluate what our choices have been producing.\n\nThis is not about judging ourselves.\n\nIt is about gaining clarity.\n\nOnce we clearly recognize the results of unhealthy patterns, we become better prepared to choose a different path.\n\nReflection Question:\n\nWhat results have your destructive choices been producing in your life?"}}, {"type": "mentor_note", "content": {"note": "The choices we repeat eventually shape the life we live."}}, {"type": "video", "content": {"title": "Recognizing the Fruit of Destructive Choices", "description": "A mentor-led explanation of how destructive choices produce long-term consequences and why honestly recognizing those outcomes is essential for lasting recovery."}}, {"type": "pause_reflect", "content": {"question": "What results have your choices produced in the different areas of your life?", "context": "Think about:\n\nYour relationships\n\nYour health\n\nYour finances\n\nYour emotional well-being\n\nYour spiritual life\n\nYour ability to trust yourself and others\n\nWhich areas have been most affected?"}}, {"type": "journal_prompt", "content": {"prompt": "Write down three ways your current patterns have affected your life.\n\nThen write one healthy change you believe could begin producing better results in the future."}}, {"type": "mood_checkin", "content": {"question": "How ready are you to honestly face the results of your choices today?"}}, {"type": "daily_action", "content": {"title": "Name the Results Honestly", "action": "Choose one consequence of your addiction that you have been minimizing or avoiding.\n\nWrite it down honestly without making excuses.\n\nThen write one practical step you can take today to begin changing that pattern."}}, {"type": "mentor_note", "content": {"note": "Honesty may be uncomfortable, but it is one of the greatest strengths in recovery.\n\nWhen we clearly see where our choices have been leading, we become empowered to choose a different direction."}}, {"type": "quiz", "content": {"question": "According to this lesson, repeated good choices eventually produce:", "options": [{"text": "Only temporary feelings", "is_correct": false}, {"text": "Lasting healthy results over time", "is_correct": true}, {"text": "Nothing significant", "is_correct": false}, {"text": "Only short-term problems", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Recognizing the consequences of our choices is mainly about condemning ourselves.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "Why is honestly recognizing the results of our choices important?", "options": [{"text": "It creates clarity and supports healthier decisions", "is_correct": true}, {"text": "It removes all consequences", "is_correct": false}, {"text": "It allows us to avoid responsibility", "is_correct": false}, {"text": "It excuses destructive behavior", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 7.", "encouragement": "Today you learned that every repeated choice produces lasting results. Recovery becomes stronger when you honestly examine the direction your choices have been leading and commit yourself to building healthier patterns that reflect the life you truly want.\n\nIn the final lesson of this chapter, we will explore the path to restoration and discover how healing becomes a process of rebuilding your life through truth, hope, and the guidance of your faith."}}]}, {"number": 8, "title": "The Path to Restoration", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Restoration Is Always Possible", "message": "Throughout this chapter, we will explore how brokenness develops, how destructive patterns take root, and how addiction affects every part of a person''s life.\n\nYet nearly every traditional religion shares a message of hope: brokenness does not have to be the end of the story.\n\nRestoration is possible.\n\nRecovery is more than escaping addiction—it is the opportunity to rebuild your life through truth, healing, responsibility, and the guidance of your faith."}}, {"type": "reading", "content": {"title": "Restoration Is the Journey Back to Wholeness", "body": "Restoration means more than simply stopping harmful behavior.\n\nIt is a process of rebuilding every area of life.\n\nHealing begins when we honestly acknowledge our struggles while remaining open to wisdom, forgiveness, growth, and transformation.\n\nRestoration includes:\n\nHonest self-reflection.\n\nAccepting responsibility for our choices.\n\nRenewing the way we think.\n\nEstablishing healthy boundaries.\n\nSeeking support from trusted people.\n\nGrowing spiritually through the practices of our faith.\n\nChoosing actions that strengthen rather than weaken our future.\n\nRecovery becomes more meaningful when we stop asking only,\n\n\"How do I avoid falling again?\"\n\nand begin asking,\n\n\"How do I build a healthier, more purposeful life?\"\n\nRestoration reminds us that every positive choice helps rebuild what addiction has damaged.\n\nHope gives meaning to the hard work of recovery.\n\nReflection Question:\n\nWhat area of your life most needs restoration today?"}}, {"type": "mentor_note", "content": {"note": "Restoration does not ignore the damage caused by addiction. It creates a path toward healing, growth, and a renewed life."}}, {"type": "video", "content": {"title": "The Path to Restoration", "description": "A mentor-led explanation of how restoration involves truth, healing, responsibility, hope, and rebuilding a meaningful life through the guidance of one''s faith."}}, {"type": "pause_reflect", "content": {"question": "Which part of your life needs the most healing right now?", "context": "Think about whether you need:\n\nGreater honesty.\n\nEmotional healing.\n\nStronger relationships.\n\nFinancial provisions.\n\nCrimes that were committed.\n\nForgiveness.\n\nRenewed purpose.\n\nSpiritual growth.\n\nWhich of these areas feels most important today?"}}, {"type": "journal_prompt", "content": {"prompt": "Write one paragraph describing what restoration would look like in your own life.\n\nImagine yourself continuing to move forward with honesty, faith, healthy choices, and hope.\n\nWhat would your daily life look like one year from now?"}}, {"type": "mood_checkin", "content": {"question": "How hopeful do you feel about rebuilding your life today?"}}, {"type": "daily_action", "content": {"title": "Take One Step Toward Restoration", "action": "Choose one practical action today that helps rebuild your life rather than repeating old patterns.\n\nSpend a few moments in prayer or personal reflection according to your faith, asking for wisdom, strength, and perseverance as you continue your recovery journey."}}, {"type": "mentor_note", "content": {"note": "Recovery becomes stronger when you stop focusing only on avoiding failure and begin focusing on building the life you truly want.\n\nEvery healthy decision becomes another step toward restoration."}}, {"type": "quiz", "content": {"question": "According to this lesson, restoration means:", "options": [{"text": "Pretending nothing happened.", "is_correct": false}, {"text": "Returning toward healing, truth, and a renewed life.", "is_correct": true}, {"text": "Avoiding responsibility.", "is_correct": false}, {"text": "Simply feeling better emotionally.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Restoration ignores the consequences of past choices.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What changes when we embrace restoration?", "options": [{"text": "Recovery becomes a dedication to rebuilding.", "is_correct": true}, {"text": "Responsibility disappears.", "is_correct": false}, {"text": "Hope is no longer needed.", "is_correct": false}, {"text": "Recovery becomes effortless.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 8.", "encouragement": "Throughout this chapter, you have explored how brokenness develops, how destructive choices become patterns, and how addiction often reflects deeper emotional, mental, and spiritual struggles.\n\nMost importantly, you have learned that restoration is always possible. Regardless of your past, every healthy decision, every honest conversation, every act of faith, and every step toward healing helps rebuild the life you were created to live.\n\nAs you continue into Chapter 3, carry with you the understanding that recovery is not simply about avoiding addiction—it is about becoming whole, rebuilding your life with purpose, and continuing to grow through the wisdom, hope, and guidance of your faith."}}]}]}, {"number": 3, "title": "The Concept of Abuse", "description": "Chapter 3 explores the meaning of abuse and demonstrates how it can appear not only through substances, but also through thoughts, attitudes, motives, relationships, coping strategies, and the inner life. It examines the progression from healthy use to misuse, the destructive nature of harmful choices, self-destructive behaviors, hidden struggles of the heart, unhealthy thought patterns, deeply rooted strongholds, and the importance of taking responsibility for lasting change.\n\nThe goal of this chapter is to help you recognize harmful patterns without minimizing them, understand how abuse affects every area of life, and embrace personal responsibility as an essential part of faith-centered healing, growth, and recovery.", "lessons": [{"number": 1, "title": "What Is Abuse?", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Abuse Is Any Repeated Pattern That Causes Harm", "message": "Many people think abuse only refers to physical violence or extreme situations. In reality, abuse is much broader. It includes any repeated misuse or abnormal use of something that causes harm to ourselves or to others.\n\nAbuse can affect ourselves, others, our body, mind, emotions, spirit, relationships, and sense of purpose.\n\nUnderstanding what abuse truly is helps us recognize harmful patterns that may have become abnormally normal over time. Recovery begins with seeing those patterns truthfully rather than minimizing or ignoring them."}}, {"type": "reading", "content": {"title": "Abuse Is the Destructive Misuse of Something Good", "body": "Traditional ways teach that we are called to care for ourselves, others, and the gifts we have been given with wisdom and responsibility.\n\nAbuse occurs when something that was meant to support life begins causing harm instead.\n\nSubstance abuse is one example.\n\nHowever, abuse can also appear through:\n\nThe way we speak to others.\n\nThe way we treat ourselves.\n\nHarmful thought patterns.\n\nManipulation or controlling behavior.\n\nEmotional neglect.\n\nUnhealthy relationships.\n\nMisuse of power.\n\nExcessive behaviors that damage our well-being.\n\nThe important question is not simply what is being used.\n\nIt is how it is being used.\n\nDoes it bring health, growth, peace, and balance?\n\nOr does it produce harm, fear, dependence, conflict, or destruction?\n\nMany unhealthy behaviors become familiar over time, normalizing such behavior.\n\nThat is why learning to define abuse clearly is such an important part of recovery.\n\nOnce harmful patterns are recognized for what they truly are, vision becomes clearer and lasting change becomes possible.\n\nReflection Question:\n\nWhat behaviors or patterns in your life have you minimized even though they were causing harm?"}}, {"type": "mentor_note", "content": {"note": "Healing often begins the moment we honestly name what has been harming us."}}, {"type": "video", "content": {"title": "What Is Abuse?", "description": "A mentor-led explanation of abuse as the destructive misuse or abnormal use of something that should support life, and why recognizing harmful patterns honestly is one of the first steps toward lasting recovery."}}, {"type": "pause_reflect", "content": {"question": "Where have you overlooked or minimized harmful patterns in your life?", "context": "Think about habits, words, relationships, coping strategies, or attitudes that have caused harm, even if you did not recognize them as abuse at the time."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one pattern you now recognize as harmful.\n\nDescribe:\n\nHow it affected you or others.\n\nWhy did it continue for so long.\n\nWhat would begin to change if you addressed it honestly."}}, {"type": "mood_checkin", "content": {"question": "How ready do you feel to honestly recognize harmful patterns in your life today?"}}, {"type": "daily_action", "content": {"title": "Name One Harmful Pattern", "action": "Before the day ends, write one sentence that clearly identifies a harmful pattern you want to change.\n\nAvoid minimizing it or making excuses.\n\nSimply describe it honestly."}}, {"type": "mentor_note", "content": {"note": "Honesty is the beginning of healing.\n\nThe moment we stop hiding harmful patterns, we give ourselves the opportunity to change them."}}, {"type": "quiz", "content": {"question": "According to this lesson, abuse is:", "options": [{"text": "Only physical violence.", "is_correct": false}, {"text": "Any repeated pattern that causes harm through destructive misuse.", "is_correct": true}, {"text": "Every mistake a person makes.", "is_correct": false}, {"text": "Only criminal behavior.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Abuse can include the way a person treats themselves.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "Why is it important to clearly recognize harmful patterns?", "options": [{"text": "It allows us to ignore them.", "is_correct": false}, {"text": "It helps challenge denial and begin healing.", "is_correct": true}, {"text": "It removes responsibility.", "is_correct": false}, {"text": "It makes harmful behavior acceptable.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 1.", "encouragement": "Today you learned that abuse is not limited to extreme situations or physical harm. It can appear in many areas of life whenever something that should support well-being instead causes damage. Recognizing these patterns honestly is one of the first and most important steps toward lasting recovery.\n\nIn the next lesson, we will explore the important difference between healthy use and destructive misuse, helping you better recognize when a behavior has crossed the line into abuse."}}]}, {"number": 2, "title": "The Difference Between Use and Abuse", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Healthy Use Supports Life. Abuse Slowly Damages It.", "message": "Not everything we use becomes harmful. Many things in life are meant to benefit us when they are used wisely, responsibly, and in moderation.\n\nThe challenge begins when something that once served us starts controlling us, harming us, or replacing what truly brings health and balance.\n\nThis lesson will help you recognize the difference between healthy use and destructive misuse or abnormal use so you can evaluate your own patterns with greater honesty."}}, {"type": "reading", "content": {"title": "The Difference Is Found in Purpose, Control, and Results", "body": "Many faith traditions encourage us to use life''s gifts with wisdom, gratitude, and self-control.\n\nHealthy use supports growth, peace, and well-being.\n\nAbuse begins when something intended for good gradually becomes harmful.\n\nOne helpful way to recognize the difference is by asking three questions:\n\n1. What is my purpose?\n\nAm I using this to support my health and well-being, or to escape pain, avoid responsibility, or numb difficult emotions? Or what other reason?\n\n2. Who is in control?\n\nAm I choosing this freely, or does it feel like it controls my thoughts, emotions, or daily decisions?\n\n3. What are the results?\n\nDoes this strengthen my life, relationships, health, peace, and spiritual growth?\n\nOr does it create shame, secrecy, conflict, dependence, or harm?\n\nDrug abuse and addiction often blurs this line.\n\nPeople may convince themselves that destructive behavior is still under control, even when the evidence suggests otherwise.\n\nRecovery requires the courage to honestly evaluate not only our intentions, but also the real impact our choices are having on our lives.\n\nThe truth is often found in the results.\n\nReflection Question:\n\nWhat pattern in your life may have quietly moved from healthy use into harmful misuse?"}}, {"type": "mentor_note", "content": {"note": "Anything that begins serving your life but slowly starts controlling it deserves honest attention."}}, {"type": "video", "content": {"title": "The Difference Between Use and Abuse", "description": "A mentor-led explanation of how purpose, self-control, and the results of our choices help distinguish healthy use from destructive misuse."}}, {"type": "pause_reflect", "content": {"question": "What signs tell you that something has crossed the line from healthy use into abuse?", "context": "Think about:\n\nLoss of control.\n\nSecrecy.\n\nShame.\n\nDamaged relationships.\n\nEmotionally volatile.\n\nDeclining health.\n\nLoss of peace.\n\nSpiritual disconnection.\n\nWhich of these have you experienced?"}}, {"type": "journal_prompt", "content": {"prompt": "Choose one habit or behavior in your life.\n\nWrite about:\n\nWhy did you first start it.\n\nHow it affects your life today.\n\nWhether it supports your well-being or causes harm.\n\nOne healthy change you could begin making this week."}}, {"type": "mood_checkin", "content": {"question": "How clearly can you recognize the difference between healthy use and harmful misuse today?"}}, {"type": "daily_action", "content": {"title": "Evaluate One Habit Honestly", "action": "Choose one daily habit.\n\nEvaluate it using these three questions:\n\nWhat is my purpose?\n\nWho is in control?\n\nWhat results is this producing?\n\nWrite your answers honestly without making excuses."}}, {"type": "mentor_note", "content": {"note": "The true measure of any habit is not how normal it feels, but what it is producing in your life.\n\nHealthy choices strengthen your future.\n\nHarmful patterns quietly weaken it."}}, {"type": "quiz", "content": {"question": "According to this lesson, what best distinguishes healthy use from abuse?", "options": [{"text": "Other people''s opinions.", "is_correct": false}, {"text": "Purpose, control, and results.", "is_correct": true}, {"text": "How enjoyable it feels.", "is_correct": false}, {"text": "How often it happens.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Drug abuse often convinces people they can still control their cravings.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What should we evaluate honestly when examining a habit?", "options": [{"text": "Only our intentions.", "is_correct": false}, {"text": "Only how frequently we do it.", "is_correct": false}, {"text": "The results the habit is producing in our lives.", "is_correct": true}, {"text": "Whether other people notice it.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 2.", "encouragement": "Today you learned that the difference between healthy use and abuse is revealed through purpose, self-control, and the results our choices produce. Recovery becomes stronger when we honestly evaluate our habits and choose patterns that support healing, peace, and lasting well-being.\n\nIn the next lesson, we will explore the destructive nature of harmful choices and discover why they often promise satisfaction while quietly producing pain and loss."}}]}, {"number": 3, "title": "The Destructive Nature of Harmful Choices", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Harmful Choices Often Promise More Than They Can Deliver", "message": "Many harmful choices appear attractive at first. They may seem to offer comfort, pleasure, relief, control, or escape from life''s responsibilities or difficulties.\n\nHowever, many beliefs teach that what appears beneficial in the moment can eventually lead to pain, loss, and spiritual emptiness.\n\nDrug abuse and addiction is one of the clearest examples of this pattern. It promises relief but often leaves behind deeper suffering.\n\nThis lesson will help you recognize why harmful choices can be so convincing and how understanding their true nature strengthens recovery."}}, {"type": "reading", "content": {"title": "Harmful Choices Promise Life but Often Produce Loss", "body": "There are teachings that remind us not everything that feels good in the moment and generally leads to lasting well-being.\n\nHarmful choices often begin with attractive promises.\n\nThey may promise:\n\nRelief from emotional pain.\n\nGreater confidence.\n\nAcceptance (the popular).\n\nComfort.\n\nControl.\n\nHappiness.\n\nFreedom from stress.\n\nYet over time, these same choices often produce the opposite:\n\nShame.\n\nFear.\n\nBroken trust.\n\nDamaged relationships.\n\nEmotional pain.\n\nDependence.\n\nLoss of peace.\n\nSpiritual disconnection.\n\nThis is why drug addiction can be so difficult to overcome.\n\nPeople often remain attached to the promise while overlooking the reality.\n\nRecovery becomes stronger when we stop focusing only on what destructive behavior seems to offer and begin honestly examining what it consistently produces.\n\nThe more clearly we see the long-term results, the easier it becomes to choose a healthier path.\n\nReflection Question:\n\nWhat has addiction or another harmful pattern promised you, and what has it actually delivered?"}}, {"type": "mentor_note", "content": {"note": "Anything that repeatedly takes more from your life than it gives deserves to be questioned honestly."}}, {"type": "video", "content": {"title": "The Destructive Nature of Harmful Choices", "description": "A mentor-led explanation of how harmful choices often promise comfort and relief while gradually producing greater pain, loss, and dependence."}}, {"type": "pause_reflect", "content": {"question": "Think about one harmful pattern in your life.", "context": "What did you believe it would give you?\n\nNow compare that with what it has actually produced.\n\nHas it brought:\n\nGreater peace?\n\nBetter relationships?\n\nMore freedom?\n\nBetter health?\n\nOr has it led to greater struggle?"}}, {"type": "journal_prompt", "content": {"prompt": "Draw two columns.\n\nIn the first column write:\n\nWhat I believed abusing drugs would give me.\n\nIn the second column write:\n\nWhat abusing drugs has actually given me.\n\nReflect on the difference between the promise and the reality."}}, {"type": "mood_checkin", "content": {"question": "How clearly do you recognize the long-term effects of harmful choices today?"}}, {"type": "daily_action", "content": {"title": "Expose the False Promise", "action": "Choose one unhealthy belief that has kept you trapped.\n\nWrite:\n\nWhat it promised.\n\nWhat actually happened.\n\nOne healthier truth your faith teaches that you want to believe instead."}}, {"type": "mentor_note", "content": {"note": "Recovery becomes stronger when you know how to dismantle attractive illusions, so that it loses its power.\n\nThe more honestly we see reality, the more freely we can choose healing instead of temporary escape."}}, {"type": "quiz", "content": {"question": "According to this lesson, harmful choices often:", "options": [{"text": "Always improve our lives.", "is_correct": false}, {"text": "Promise relief while producing harm.", "is_correct": true}, {"text": "Have no lasting consequences.", "is_correct": false}, {"text": "Only affects physical health.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Harmful choices often leave people with the opposite of what they originally promised.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What helps people break free from destructive patterns?", "options": [{"text": "Ignoring the consequences.", "is_correct": false}, {"text": "Acknowledging the true results of harmful choices.", "is_correct": true}, {"text": "Believing the promises more strongly.", "is_correct": false}, {"text": "Avoiding self-reflection.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 3.", "encouragement": "Today you discovered that harmful choices often promise comfort, freedom, or relief while gradually producing pain, dependence, and loss. Lasting recovery begins when you stop believing the false promises of addiction and start choosing the truth, wisdom, and lasting hope found through your faith.\n\nIn the next lesson, we will explore self-destruction and addiction, helping you understand how repeated harmful choices can quietly work against your own well-being and how those patterns can be broken."}}]}, {"number": 4, "title": "Self-Destruction and Addiction", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Addiction Can Quietly Turn Us Against Ourselves", "message": "Most people do not begin using drugs or other harmful substances or behaviors because they want to destroy their lives.\n\nThey often begin because they are searching for something meaningful, or to identify with groups in society. Other reasons could be relief from pain, stress, loneliness, fear, trauma, or emotional suffering. But that could be secondary reasons to things like finding purpose and meaning to life.\n\nOver time, however, what once seemed like the answer can slowly become a pattern that harms the very person seeking comfort.\n\nThis lesson explores how addiction can become self-destructive and how recognizing these patterns is an important step toward lasting recovery."}}, {"type": "reading", "content": {"title": "Self-Destructive Patterns Often Begin as Attempts to Cope", "body": "Many belief systems teach that every person has inherent worth and that life should be treated with care, wisdom, and compassion.\n\nSelf-destructive behavior often develops when people repeatedly use unhealthy ways to cope with difficult emotional, mental and spiritual life.\n\nAt first, these behaviors may seem helpful.\n\nThey may temporarily reduce stress or emotional confusion.\n\nBut over time they often begin damaging:\n\nPhysical health.\n\nEmotional well-being.\n\nRelationships.\n\nSelf-respect.\n\nFinancial stability.\n\nSpiritual growth.\n\nHope for the future.\n\nMany people become trapped between wanting to change and continuing the very behaviors that cause their suffering.\n\nThis creates confusion, frustration, and shame.\n\nRecovery begins when we recognize that these self-destructive patterns are not who we are.\n\nThey are learned behaviors that can be interrupted, replaced, and transformed.\n\nOur faith reminds us that healing is possible.\n\nWith honesty, support, wisdom, and perseverance, harmful patterns can give way to healthier choices that protect life instead of damaging it.\n\nReflection Question:\n\nWhat behaviors in your life have repeatedly worked against your own well-being?"}}, {"type": "mentor_note", "content": {"note": "Something that brings temporary comfort but lasting harm is not helping you heal."}}, {"type": "video", "content": {"title": "Self-Destruction and Addiction", "description": "A mentor-led explanation of how addiction often begins as an attempt to cope with pain but gradually becomes a pattern of self-destruction, and how recovery helps replace those patterns with healthier ways of living."}}, {"type": "pause_reflect", "content": {"question": "Where have you been working against your own healing?", "context": "Think about habits, routines, or thoughts that promise relief but consistently leave you feeling weaker, more discouraged, or further from the life you want."}}, {"type": "journal_prompt", "content": {"prompt": "Write about one self-destructive pattern you recognize.\n\nThen answer:\n\nWhat need was it you trying to meet?\n\nHow has it affected your life?\n\nWhat healthier response could begin replacing it?"}}, {"type": "mood_checkin", "content": {"question": "How ready do you feel to stop cooperating with patterns that harm your well-being?"}}, {"type": "daily_action", "content": {"title": "Interrupt One Harmful Pattern Today", "action": "Choose one unhealthy impulse that commonly leads you toward destructive behavior.\n\nWhen it appears today, pause before acting.\n\nReplace it with one healthy response such as prayer, reflection, speaking with someone you trust, taking a walk, journaling, or another positive coping strategy that aligns with your faith."}}, {"type": "mentor_note", "content": {"note": "Your harmful patterns are not your identity.\n\nThey are behaviors that can be recognized, challenged, and changed.\n\nEvery healthy decision weakens the cycle of self-destruction and strengthens the path toward healing."}}, {"type": "quiz", "content": {"question": "According to this lesson, self-destructive patterns often begin as:", "options": [{"text": "A desire to ruin one''s life.", "is_correct": false}, {"text": "Attempts to cope with emotional or spiritual life.", "is_correct": true}, {"text": "A lack of intelligence.", "is_correct": false}, {"text": "Public acts of rebellion.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Self-destructive behaviors define who you are.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What helps strengthen recovery from self-destructive patterns?", "options": [{"text": "Ignoring the damage.", "is_correct": false}, {"text": "Interrupting harmful patterns with healthier responses.", "is_correct": true}, {"text": "Accepting destructive behavior as permanent.", "is_correct": false}, {"text": "Keeping struggles hidden.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 4.", "encouragement": "Today you learned that addiction often begins as an attempt to cope with life''s issues but can gradually become a pattern that works against your own well-being. The encouraging truth is that these patterns do not define you. With honesty, support, healthy choices, and the guidance of your faith, you can begin replacing self-destructive behaviors with habits that promote healing, hope, and lasting recovery.\n\nIn the next lesson, we will explore the hidden struggles of the heart and discover how our inner attitudes, beliefs, and emotions often influence the choices we make every day."}}]}, {"number": 5, "title": "Hidden Abuse of the Heart", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Not Every Harmful Pattern Can Be Seen", "message": "Some of the most damaging struggles are hidden beneath the surface.\n\nSome teach that our thoughts, attitudes, motives, and emotions influence the way we live long before our actions become visible in our environment.\n\nResentment, pride, bitterness, fear, jealousy, self-hatred, unhealthy desires, and unforgiveness may remain hidden for years as the person grows in age.\n\nThat''s why our lives are a journey, going through the different levels of aging. Growing and aging plays a major role in who we become, what changes in our lives and what we allow to happen with us."}}, {"type": "reading", "content": {"title": "The Inner Life Shapes the Outer Life", "body": "It is with understanding that to emphasize that lasting change begins within.\n\nOur thoughts, beliefs, emotions, and attitudes eventually influence our words, decisions, relationships, and habits.\n\nHidden struggles may include:\n\nHarsh self-criticism.\n\nBitterness toward others.\n\nUnforgiveness.\n\nPride.\n\nFear.\n\nJealousy.\n\nSecret resentment.\n\nManipulative behavior.\n\nUsing people to meet emotional needs.\n\nThese patterns are often invisible to others, but it can be a living force in our lives.\n\nWhat''s sad is that drug abuse and addiction frequently grows alongside these hidden struggles that remain unaddressed.\n\nThis does not mean drug abuse is always the outcome of these struggles.\n\nHealing on all levels begins when we bring these hidden struggles into the light with honesty, humility, and a willingness to grow and make the change.\n\nOur faith teaches that transformation begins from the inside out.\n\nReflection Question:\n\nWhat hidden attitudes or emotional struggles continue influencing your life today?"}}, {"type": "mentor_note", "content": {"note": "What remains hidden continues to shape us until we are willing to face it honestly."}}, {"type": "video", "content": {"title": "Hidden Abuse of the Heart", "description": "A mentor-led explanation of how hidden thoughts, attitudes, emotions, and beliefs influence outward behavior, and why lasting recovery requires healing from the inside out."}}, {"type": "pause_reflect", "content": {"question": "Which hidden attitudes or emotions need your honest attention today?", "context": "Think about areas such as:\n\nResentment.\n\nFear.\n\nPride.\n\nSelf-hatred or self dislike.\n\nJealousy.\n\nUnforgiveness.\n\nEmotional dependence.\n\nNegative self-talk.\n\nHow have these affected your recovery?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about one hidden struggle you no longer want to ignore.\n\nDescribe:\n\nHow it affects your thoughts and behavior.\n\nWhere you believe it may have started.\n\nOne healthy step you can take toward healing it."}}, {"type": "mood_checkin", "content": {"question": "How willing are you to honestly examine your inner life today?"}}, {"type": "daily_action", "content": {"title": "Bring One Hidden Struggle Into the Light", "action": "Spend a few quiet moments in prayer or personal reflection according to your faith.\n\nIdentify one hidden emotional or spiritual struggle that you have been avoiding.\n\nName it honestly, without minimizing or defending it.\n\nThen ask for wisdom, healing, and strength to begin addressing it."}}, {"type": "mentor_note", "content": {"note": "Healing begins when we stop hiding from ourselves.\n\nAs truth enters the hidden places of our hearts, lasting transformation becomes possible."}}, {"type": "quiz", "content": {"question": "According to this lesson, hidden struggles:", "options": [{"text": "Remain harmless if no one sees them.", "is_correct": false}, {"text": "Influence our thoughts, choices, and behavior.", "is_correct": true}, {"text": "Only affect our emotions.", "is_correct": false}, {"text": "Disappear on their own over time.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Lasting recovery only requires changing outward behavior.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What supports deeper healing?", "options": [{"text": "Ignoring hidden struggles.", "is_correct": false}, {"text": "Bringing them into the light with honesty and self-reflection.", "is_correct": true}, {"text": "Pretending they do not exist.", "is_correct": false}, {"text": "Blaming other people for them.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 5.", "encouragement": "Today you learned that some of the most important work in recovery happens beneath the surface. Hidden attitudes, beliefs, and emotional struggles often shape our outward behavior, but they do not have to control our future. As you continue bringing these areas into the light through honesty, self-reflection, and the guidance of your faith, you create space for deeper healing and lasting transformation.\n\nIn the next lesson, we will explore how repeated thoughts can lead to bondage and discover practical ways to replace destructive thinking with healthier, life-giving truth."}}]}, {"number": 6, "title": "Thoughts That Lead to Bondage", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Lasting Change Begins with the Way We Think", "message": "Our thoughts have tremendous influence and power when we make decisions.\n\nThere are many teachings that the mind plays a central role in shaping our attitudes, emotions, actions, and character. Repeated thoughts gradually become belief sets, and those beliefs often influence and drive the direction of our lives.\n\nThis lesson explores how unhealthy thinking can contribute to addiction and how renewing the mind is an essential part of full recovery."}}, {"type": "reading", "content": {"title": "Repeated Thoughts Become Powerful Patterns", "body": "Most destructive thinking does not begin with dramatic ideas.\n\nInstead, it often starts with quiet, familiar thoughts such as:\n\n\"I can''t change.\"\n\n\"Just one more time won''t matter.\"\n\n\"No one understands me.\"\n\n\"I need this to cope.\"\n\n\"I''ll never be free.\"\n\n\"This is simply who I am.\"\n\nWhen these thoughts are repeated often enough, they begin to feel like facts and not just coping mechanisms.\n\nOver time they create permission for destructive choices and strengthen unhealthy habits.\n\nLasting transformation begins by renewing the way we think.\n\nRecovery is not simply about trying harder.\n\nIt is also about learning to recognize unhealthy thoughts, question them honestly, and replace them with beliefs that encourage healing, hope, wisdom, and growth.\n\nAs healthier thinking becomes consistent, healthier choices become more natural.\n\nChanging your thoughts will not solve every challenge overnight.\n\nBut it contributes to the development in which your life is moving.\n\nReflection Question:\n\nWhich repeated thought has most often pulled you toward unhealthy choices?"}}, {"type": "mentor_note", "content": {"note": "The thoughts we repeatedly believe gradually shape the life we live."}}, {"type": "video", "content": {"title": "Thoughts That Lead to Bondage", "description": "A mentor-led explanation of how repeated thoughts influence beliefs and behavior, and how renewing the mind helps break unhealthy cycles and strengthen lasting recovery."}}, {"type": "pause_reflect", "content": {"question": "What repeated thoughts appear most often before you make unhealthy choices?", "context": "Think about the inner conversations you have with yourself.\n\nWhich thoughts make destructive behavior seem acceptable, unavoidable, and happen naturally?\n\nHow could the wisdom of your faith help you challenge those beliefs?"}}, {"type": "journal_prompt", "content": {"prompt": "Write down:\n\nOne repeated unhealthy thought.\n\nWhy you believe it has become so powerful.\n\nOne healthier truth that challenges it.\n\nOne practical way you will remind yourself of that truth this week."}}, {"type": "mood_checkin", "content": {"question": "How aware are you of your daily thought patterns today?"}}, {"type": "daily_action", "content": {"title": "Challenge One Unhealthy Thought", "action": "When you notice one recurring unhealthy thought today, pause before accepting it.\n\nWrite it down.\n\nThen write one healthier truth that replaces it, based on your faith, your recovery goals, or the reality you want to build.\n\nRead that truth several times throughout the day."}}, {"type": "mentor_note", "content": {"note": "A harmful thought loses its power when it is challenged instead of believed.\n\nEvery healthier belief strengthens the foundation of lasting recovery."}}, {"type": "quiz", "content": {"question": "According to this lesson, repeated unhealthy thoughts often become:", "options": [{"text": "Harmless background noise.", "is_correct": false}, {"text": "Internal permission for destructive choices.", "is_correct": true}, {"text": "Proof that they are true.", "is_correct": false}, {"text": "Permanent facts.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Lasting recovery requires renewing the way we think, not simply trying harder.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What should you do when you recognize a repeated unhealthy thought?", "options": [{"text": "Ignore it.", "is_correct": false}, {"text": "Accept it without question.", "is_correct": false}, {"text": "Challenge it with an important truth.", "is_correct": true}, {"text": "Hide it from yourself.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 6.", "encouragement": "Today you learned that repeated thoughts gradually become beliefs, and those beliefs influence your choices. Recovery grows stronger as you learn to recognize unhealthy thinking, replace it with life-giving truth, and build habits that support healing rather than addiction.\n\nIn the next lesson, we will explore personal strongholds and discover how deeply rooted patterns can be identified, challenged, and gradually overcome through honesty, wisdom, and the guidance of your faith."}}]}, {"number": 7, "title": "Identifying Personal Strongholds", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Strongholds Are Patterns That Keep Holding Us Back", "message": "Some belief systems recognize that people can develop deeply rooted habits that influence the way they think, feel, and behave.\n\nThese habits and patterns are often built over time through repeated beliefs, emotional wounds, bad habits, and destructive choices. They can become so familiar that they begin to feel normal, even when they continue causing harm.\n\nThis lesson will help you identify these strongholds so you can begin breaking its influence over your life."}}, {"type": "reading", "content": {"title": "Lasting Change Begins by Identifying What Has Taken Root", "body": "A stronghold is worse than just a bad habit.\n\nIt is a deeply established pattern of actions that repeatedly influences your thinking, emotions, reactions, or behavior.\n\nStrongholds may involve:\n\nDrug addiction.\n\nFear.\n\nShame.\n\nBitterness.\n\nHopelessness.\n\nAnger.\n\nPride.\n\nSelf-hatred.\n\nThe need to control everything.\n\nUnhealthy dependence on people or substances.\n\nThese patterns can as easily become stronger through repetition.\n\nThe longer they remain unchallenged, the more autonomous they become.\n\nMany people believe they cannot change simply because these patterns have existed for so long.\n\nHowever, our faith teaches that deeply rooted patterns can be overcome.\n\nThe first step is recognizing them truthfully.\n\nOnce a stronghold is clearly identified, it becomes possible to challenge it through truth, healthy boundaries, supportive relationships, spiritual growth, and consistent positive daily choices.\n\nRecovery begins gaining momentum when we stop pretending and accepting harmful strongholds have been part of our lives, but now we can overcome it.\n\nStrongholds may influence us, but they do not define us.\n\nReflection Question:\n\nWhat recurring pattern has had the strongest influence over your life?"}}, {"type": "mentor_note", "content": {"note": "A pattern cannot begin to lose its power until it is honestly and thoughtfully recognized."}}, {"type": "video", "content": {"title": "Identifying Personal Strongholds", "description": "A mentor-led explanation of how deeply rooted patterns develop, why they can feel difficult to change, and how identifying them honestly becomes the first step toward lasting freedom."}}, {"type": "pause_reflect", "content": {"question": "Which pattern in your life feels the most deeply rooted?", "context": "Think about:\n\nThoughts you repeat.\n\nEmotional reactions.\n\nHabits.\n\nFears.\n\nBeliefs about yourself.\n\nBehaviors you struggle to change.\n\nWhich one feels strongest?"}}, {"type": "journal_prompt", "content": {"prompt": "Choose one stronghold you want to overcome.\n\nWrite about:\n\nHow long it has been part of your life.\n\nHow it affects your relationships, health, emotions, or spiritual life.\n\nWhat keeps reinforcing it.\n\nOne healthy truth or boundary that can begin weakening its influence."}}, {"type": "mood_checkin", "content": {"question": "How ready do you feel to confront deeply rooted patterns in your life today?"}}, {"type": "daily_action", "content": {"title": "Name the Stronghold Clearly", "action": "Spend a few quiet moments in prayer or personal reflection according to your faith.\n\nWrite the name of one stronghold you are committed to overcoming.\n\nThen write one practical action you can take this week to weaken its influence."}}, {"type": "mentor_note", "content": {"note": "Strongholds grow stronger when they remain hidden or unconcerned.\n\nThey begin losing their influence the moment they are brought into the light with honesty, courage, and hope."}}, {"type": "quiz", "content": {"question": "According to this lesson, a stronghold is:", "options": [{"text": "A temporary bad day.", "is_correct": false}, {"text": "A deeply rooted inner struggle reinforced over time.", "is_correct": true}, {"text": "A physical illness.", "is_correct": false}, {"text": "A problem that can never change.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Strongholds should be ignored because acknowledging them gives them more power.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What helps weaken a stronghold?", "options": [{"text": "Pretending it does not exist.", "is_correct": false}, {"text": "Honest recognition combined with truth, healthy boundaries, and mindset change.", "is_correct": true}, {"text": "Waiting for it to disappear.", "is_correct": false}, {"text": "Blaming other people.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 7.", "encouragement": "Today you learned that strongholds are deeply rooted patterns of inner struggles—not permanent identities. As you continue recognizing them with honesty and responding with truth, healthy boundaries, and the guidance of your faith, you weaken its influence and strengthen your recovery more.\n\nIn the final lesson of this chapter, we will focus on taking personal responsibility for change and discovering how consistent daily choices help build lasting healing and freedom."}}]}, {"number": 8, "title": "Taking Responsibility for Change", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Lasting Healing Begins with Personal Responsibility", "message": "Throughout this chapter, you have learned how drug abuse, unhealthy thinking, hidden struggles, and deeply rooted patterns can influence your life.\n\nUnderstanding these challenges is important, but understanding alone does not create change.\n\nWorld belief systems teach that healing begins when we accept responsibility for our choices while also recognizing that we do not have to walk the journey alone.\n\nResponsibility is not about guilty feelings or self-condemnation.\n\nIt is about choosing to actively participate in your own healing."}}, {"type": "reading", "content": {"title": "Responsibility Creates the Opportunity for Change", "body": "Real recovery requires honesty.\n\nIt means recognizing harmful patterns of bahavior, accepting responsibility for your actions, and making intentional choices that support healing.\n\nResponsibility does not mean blaming yourself for everything that has happened in your life.\n\nIt also does not mean carrying every burden alone.\n\nInstead, responsibility means choosing how you will respond today and going forward.\n\nMany people remain trapped because they continue protecting the very bad patterns and habits they hope to escape.\n\nExcuses.\n\nBlame.\n\nDenial.\n\nAvoidance.\n\nFear.\n\nThese may not seem a big deal when struggling with addiction, but it plays major roles in preventing freedom from drugs.\n\nRecovery becomes stronger when we say:\n\n\"This pattern is harming me.\"\n\n\"I am responsible for choosing a different path.\"\n\n\"With the support of my faith, healthy relationships, and consistent action, I can continue growing.\"\n\nEvery responsible decision strengthens the foundation of lasting recovery.\n\nEvery small act of courage becomes another step toward freedom.\n\nReflection Question:\n\nWhere do you need to stop making excuses and begin taking positive action?"}}, {"type": "mentor_note", "content": {"note": "Responsibility is not about carrying too heavy loads.\n\nIt is about choosing growth."}}, {"type": "video", "content": {"title": "Taking Responsibility for Change", "description": "A mentor-led explanation of how personal responsibility strengthens recovery by replacing excuses with honest action, consistent choices, and the guidance of one''s faith."}}, {"type": "pause_reflect", "content": {"question": "What area of your life requires greater personal responsibility today?", "context": "Think about where fear, blame, delay, or avoidance may be preventing positive change.\n\nWhat is one action you know you need to take?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about one area where you are ready to take greater responsibility.\n\nDescribe:\n\nWhat needs to change.\n\nWhat has been preventing change.\n\nOne practical action you will take this week.\n\nWho can support you in remaining accountable?"}}, {"type": "mood_checkin", "content": {"question": "How willing are you to take ownership of your recovery today?"}}, {"type": "daily_action", "content": {"title": "Take One Responsible Step", "action": "Choose one action today that reflects the person you want to become.\n\nSpend a few quiet moments in prayer or personal reflection according to your faith.\n\nAsk for wisdom, courage, perseverance, and humility as you continue building a healthier future one positive decision at a time."}}, {"type": "mentor_note", "content": {"note": "Healing grows when excuses are minimized.\n\nGrowth begins when avoidance becomes humble action.\n\nEvery responsible choice moves you one step closer to the life your faith calls you to live."}}, {"type": "quiz", "content": {"question": "According to this lesson, responsibility:", "options": [{"text": "Opens the door to lasting change.", "is_correct": true}, {"text": "Removes every struggle immediately.", "is_correct": false}, {"text": "Creates shame.", "is_correct": false}, {"text": "Excuses destructive behavior.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Taking responsibility means facing recovery completely alone.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What most often prevents lasting change?", "options": [{"text": "Honest self-reflection.", "is_correct": false}, {"text": "Excuses, blaming others, and avoidance.", "is_correct": true}, {"text": "Healthy boundaries.", "is_correct": false}, {"text": "Seeking support.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 8.", "encouragement": "Today you learned that lasting recovery is strengthened by personal responsibility. While your past may explain some of your struggles, your future is shaped by the choices you make today. Every honest decision, every healthy action, and every step taken with the guidance of your faith helps build a stronger foundation for healing and lasting freedom.\n\nYou have now completed Chapter 3: The Concept of Abuse. You understand how harmful patterns and strongholds develop, how they influence the heart and mind, and how taking responsibility allows lasting change to begin. As you continue into Chapter 4, you will explore the deeper needs people often try to satisfy through addiction and discover healthier ways to meet those needs through faith, purpose, and personal growth."}}]}]}, {"number": 4, "title": "The Real Reason People Do Drugs", "description": "Chapter 4 explores the deeper reasons people turn to drugs by looking beyond the substance itself. It examines the search for escape from so-called reality, dealing with emotional pain, trauma, spiritual emptiness, the need to belong, false sources of comfort, unhealthy beliefs, and the deeper needs of the heart that often drive repeated substance abuse.\n\nThe goal of this chapter is to help you understand that drug abuse and addiction doesn''t mean it''s the source of life''s problems. Lasting recovery begins when you honestly identify the deeper wounds, unmet needs, unhealthy thinking, and spiritual struggles that have been seeking relief. Healing becomes possible when those needs are addressed through truth, building healthy relationships, personal growth, and the guidance of your faith.", "lessons": [{"number": 1, "title": "Looking Beyond the Substance", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "The Substance Is Often the Surface—The Deeper Issue Is What the Heart Is Seeking", "message": "People often ask why someone uses drugs as though the answer is simply the drug itself.\n\nThis chapter begins by looking deeper.\n\nThe substance is real, but it often becomes attractive because it appears to meet a deeper emotional, mental, or spiritual need.\n\nBelief systems teach that lasting healing begins when we look beyond outward behavior and honestly examine what the heart has been searching for.\n\nRecovery becomes stronger when we understand not only what was used, but why it seemed necessary in the first place."}}, {"type": "reading", "content": {"title": "The Real Question Is Not Only What Was Used, but What Was Being Sought", "body": "Addiction is often misunderstood when all the attention is placed on the substance.\n\nThe drug may be the visible problem, but behind it there is often a deeper pursuit.\n\nA person may be searching for:\n\nRelief from emotional pain.\n\nComfort.\n\nPeace.\n\nAcceptance.\n\nConfidence.\n\nBelonging.\n\nEscape.\n\nControl.\n\nFreedom from difficult thoughts or feelings.\n\nThe substance may seem to provide these things for a short time, but it cannot truly satisfy the deeper needs of the human heart if it seeks to do it through drug taking.\n\nThere are teachings that lasting healing comes when these deeper needs are recognized and addressed through truth, spiritual growth, healthy relationships, and a life guided by faith.\n\nIf recovery focuses only on removing the substance while ignoring the deeper need, the same longing may simply attach itself to something else, or the person may become very frustrated.\n\nReal recovery asks deeper questions.\n\nNot only:\n\n\"What was I using?\"\n\nBut also:\n\n\"What was I truly searching for?\"\n\nUnderstanding this helps us stop treating addiction as only a physical problem and see it as a holistic healing process for the inner parts of our lives.\n\nReflection Question:\n\nWhat do you believe you were truly searching for through your drug abuse?"}}, {"type": "mentor_note", "content": {"note": "The substance may be visible, but the inner dynamics often tells the real story."}}, {"type": "video", "content": {"title": "Looking Beyond the Substance", "description": "A mentor-led explanation of why addiction cannot be understood by examining only the substance, and how identifying the deeper emotional, mental, and spiritual needs strengthens lasting recovery."}}, {"type": "pause_reflect", "content": {"question": "What were you hoping the substance would give you?", "context": "Think beyond the drug itself.\n\nWere you searching for:\n\nPeace?\n\nSpirituality?\n\nKnowledge?\n\nWisdom?\n\nComfort?\n\nRelief?\n\nConfidence?\n\nBelonging?\n\nEscape?\n\nLove?\n\nHope?\n\nWhich of these feels most true for you?"}}, {"type": "journal_prompt", "content": {"prompt": "Complete the following sentence:\n\n\"When I reached for the substance, I believe I was really searching for...\"\n\nThen describe healthier ways your faith, supportive relationships, or personal growth could begin meeting that deeper need."}}, {"type": "mood_checkin", "content": {"question": "How open do you feel to looking beneath the surface of your addiction today?"}}, {"type": "daily_action", "content": {"title": "Identify the Deeper Need", "action": "Spend a few quiet moments in prayer or personal reflection according to your faith.\n\nWrite down one deeper need that has been hiding beneath your addiction.\n\nDo not focus on the substance.\n\nFocus on what your heart has truly been seeking."}}, {"type": "mentor_note", "content": {"note": "Recovery becomes clearer when we understand the inner need rather than focusing only on the habit.\n\nHealing begins where honesty begins."}}, {"type": "quiz", "content": {"question": "According to this lesson, what should recovery look beyond?", "options": [{"text": "Only the physical effects.", "is_correct": false}, {"text": "The substance to the deeper need.", "is_correct": true}, {"text": "Other people''s opinions.", "is_correct": false}, {"text": "The past alone.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: The substance is usually the complete explanation for addiction.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "Why is understanding the deeper need important?", "options": [{"text": "It helps identify what the heart has truly been seeking.", "is_correct": true}, {"text": "It removes personal responsibility.", "is_correct": false}, {"text": "It makes the substance unimportant.", "is_correct": false}, {"text": "It avoids dealing with addiction.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 1.", "encouragement": "Today you learned that addiction is often about far more than the substance itself. By looking beneath the surface, you begin identifying the deeper needs, emotional struggles, and spiritual longings that have been driving destructive behavior. This understanding creates a stronger foundation for lasting recovery.\n\nIn the next lesson, we will explore the search for escape and discover why temporary relief can never replace true healing."}}]}, {"number": 2, "title": "The Search for Escape", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Many People Do Not Begin with a Desire to Be Destroyed—They Begin with a Desire to Escape", "message": "Most people do not begin using and abusing drugs because they want to harm their lives and future.\n\nThey begin because they are trying to escape whats realistic or perhaps seek a deeper meaning to life.\n\nPainlessness.\n\nStressless.\n\nFearlessness.\n\nUnashamed.\n\nBelonging.\n\nFulfilling.\n\nHappiness.\n\nMany faith traditions recognize that people naturally long for answers and relief during difficult times. The challenge is not the desire for relief itself, but where we choose to seek it.\n\nThis lesson explores how the search for escape can quietly become the doorway to addiction, and how lasting healing requires something deeper than temporary relief."}}, {"type": "reading", "content": {"title": "Escape Offers Distance from Pain, but Healing Requires Facing It", "body": "The desire to escape difficult emotions is part of the human experience.\n\nWhen emotional pain, trauma, guilt, failure, anxiety, or hopelessness become overwhelming, the promise of quick relief can seem incredibly attractive.\n\nDrugs may temporarily quiet the mind.\n\nThey may numb painful emotions.\n\nThey may create the illusion that everything is under control.\n\nBut escape is not the same as healing.\n\nEscape avoids the painful issue without resolving it.\n\nWhen the temporary relief fades, the original pain often returns—along with additional burdens such as dependence, shame, broken relationships, health problems, and regret.\n\nLasting healing comes through the truth, courage, wisdom, and perseverance rather than avoidance.\n\nRecovery becomes stronger when we stop asking,\n\n\"How can I escape this feeling?\"\n\nand begin asking,\n\n\"Where are these drug abusive desires coming from, and how can I face it in a healthy way?\"\n\nHealing is not found by running from the deeper root cause which might be inner wounds.\n\nHealing begins when we are willing to face it with honesty and support.\n\nReflection Question:\n\nWhat have you been trying to escape through addiction?"}}, {"type": "mentor_note", "content": {"note": "Temporary escape may quiet pain for a moment, but only healing can bring lasting peace."}}, {"type": "video", "content": {"title": "The Search for Escape", "description": "A mentor-led explanation of why escape feels powerful in the short term, why it cannot replace healing, and how facing pain honestly becomes an important part of lasting recovery."}}, {"type": "pause_reflect", "content": {"question": "What have you most wanted to escape from?", "context": "Reflect honestly on areas such as:\n\nEmotional pain.\n\nFear.\n\nShame.\n\nLoneliness.\n\nTrauma.\n\nGrief.\n\nFailure.\n\nAnxiety.\n\nInner unrest.\n\nWhich of these has influenced your choices most?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about one burden you have been trying to escape.\n\nThen answer:\n\nWhat happens after the temporary relief wears off?\n\nWhat healthy support or spiritual practice could help you begin facing that burden instead of avoiding it?"}}, {"type": "mood_checkin", "content": {"question": "How strong is your desire to escape difficult emotions today?"}}, {"type": "daily_action", "content": {"title": "Name the Real Pressure", "action": "The next time you feel the urge to escape today, pause before reacting.\n\nSpend a few quiet moments in prayer or personal reflection according to your faith.\n\nAsk yourself:\n\n\"What pain, pressure, or emotion am I trying to escape right now?\"\n\nWrite your answer honestly."}}, {"type": "mentor_note", "content": {"note": "Escape postpones pain.\n\nHealing transforms it.\n\nEvery time you choose truth instead of avoidance, you strengthen your recovery."}}, {"type": "quiz", "content": {"question": "According to this lesson, what does escape usually provide?", "options": [{"text": "Lasting healing.", "is_correct": false}, {"text": "Short-term relief.", "is_correct": true}, {"text": "Permanent peace.", "is_correct": false}, {"text": "Freedom from responsibility.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Escape and healing are the same thing.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What strengthens recovery?", "options": [{"text": "Avoiding painful emotions.", "is_correct": false}, {"text": "Identifying the real pain beneath the desire to escape.", "is_correct": true}, {"text": "Ignoring emotional wounds.", "is_correct": false}, {"text": "Seeking quick relief whenever possible.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 2.", "encouragement": "Today you learned that the desire to escape is deeply human, but temporary relief cannot replace genuine healing. By learning to identify the pain beneath the urge to escape and responding with honesty, healthy support, and the guidance of your faith, you build a stronger foundation for lasting recovery.\n\nIn the next lesson, we will explore pain, trauma, and brokenness, and discover how unhealed wounds can quietly influence addiction until they are faced with truth, compassion, and healing."}}]}, {"number": 3, "title": "Pain, Trauma, and Brokenness", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Unhealed Pain Often Keeps Searching for Relief", "message": "Not everyone who experiences drastic inner pain develops an addiction or abuse drugs.\n\nHowever, many addictive patterns are connected to emotional wounds, trauma, grief, or painful experiences that were never fully understood or healed.\n\nMany belief systems recognize that suffering is part of the human experience. While inner pain depends on what occurred, how we respond to it can shape the direction of our lives.\n\nThis lesson explores the connection between pain, trauma, and drug addiction while reminding us that our wounds explain our struggles—they do not have to define our future."}}, {"type": "reading", "content": {"title": "Pain That Remains Hidden Often Continues Influencing Our Lives", "body": "Pain does not disappear simply because we ignore it or numb it with something else.\n\nWhen emotional wounds remain buried, they often continue influencing the way we think, feel, and respond to life.\n\nUnhealed pain may appear as:\n\nFear.\n\nAnxiety.\n\nShame.\n\nAnger.\n\nEmotional numbness.\n\nConstant stress.\n\nDifficulty trusting others.\n\nFeeling disconnected or overwhelmed.\n\nMany people also turn to drug abuse because they want to experience something different or more in life.\n\nBut what makes things difficult is that people might have unresolved inner difficulties, and then abuse drugs which can have a bad combination effect.\n\nMany faith traditions teach that lasting healing requires truth, compassion, courage, and a willingness to face what has been hidden.\n\nRecovery does not ask you to pretend your pain never existed.\n\nIt invites you to face it truthfully without allowing it to control the rest of your life.\n\nYour pain deserves compassion.\n\nBut it does not have to continue harming yourself or affect relationships in a bad way.\n\nHealing begins when we face our wounds with honesty, seek support, and allow our faith to guide us toward restoration.\n\nReflection Question:\n\nWhat painful experience has most influenced your recovery journey?"}}, {"type": "mentor_note", "content": {"note": "Hidden wounds may continue influencing our choices in a negative way until they are brought into the light, so the person can find wisdom to deal with it."}}, {"type": "video", "content": {"title": "Pain, Trauma, and Brokenness", "description": "A mentor-led explanation of how emotional pain and trauma can influence addiction, why acknowledging wounds is an important part of recovery, and how healing becomes possible through truth, compassion, personal responsibility, and the guidance of one''s faith."}}, {"type": "pause_reflect", "content": {"question": "What pain or wound continues to affect your life today?", "context": "Think about experiences that still influence your emotions, relationships, or choices.\n\nHow have these experiences shaped the way you cope with stress or difficult situations?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about one painful experience that still affects you.\n\nThen answer:\n\nHow has it influenced your thoughts or behavior?\n\nWhat support or healthy practice could help you continue healing?\n\nWhat would it look like to acknowledge this wound without allowing it to control your future?"}}, {"type": "mood_checkin", "content": {"question": "How aware are you of deeper emotional pain affecting your life today?"}}, {"type": "daily_action", "content": {"title": "Acknowledge the Wound Honestly", "action": "Spend a few quiet moments in prayer or personal reflection according to your faith.\n\nIdentify one emotional wound you have been avoiding.\n\nName it honestly.\n\nThen ask for wisdom, healing, strength, and courage to continue moving forward without allowing that wound to define your identity."}}, {"type": "mentor_note", "content": {"note": "Compassion acknowledges pain.\n\nTruth prevents pain from becoming your identity.\n\nHealing begins when both work together."}}, {"type": "quiz", "content": {"question": "According to this lesson, hidden emotional pain can:", "options": [{"text": "Disappear on its own.", "is_correct": false}, {"text": "Continue influencing thoughts and behavior.", "is_correct": true}, {"text": "Guarantee addiction.", "is_correct": false}, {"text": "Remove personal responsibility.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Recovery requires pretending painful experiences never happened.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What supports lasting healing?", "options": [{"text": "Ignoring emotional wounds.", "is_correct": false}, {"text": "Facing pain with honesty, compassion, and personal responsibility.", "is_correct": true}, {"text": "Using pain as an excuse for destructive choices.", "is_correct": false}, {"text": "Keeping painful experiences hidden forever.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 3.", "encouragement": "Today you learned that unhealed pain can quietly influence thoughts, emotions, and behavior, but it does not have to determine your future. Recovery becomes stronger when you acknowledge your wounds with honesty, seek healthy support, and allow your faith to guide you toward healing and restoration.\n\nIn the next lesson, we will explore spiritual emptiness and discover why no temporary solution can satisfy the deeper longings of the human spirit."}}]}, {"number": 4, "title": "Spiritual Emptiness", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Sometimes the Deepest Longing Is Spiritual", "message": "There are forms of emptiness that no pleasure, success, relationship, achievement, or substance can truly satisfy.\n\nIt is common teaching that every person has a spiritual dimension of life that longs for meaning, purpose, peace, and connection with you God.\n\nWhen that deeper need goes unmet, people often search for something to fill the emptiness.\n\nThis lesson explores how spiritual emptiness can contribute to drug abuse and why lasting healing comes from nourishing the spirit rather than chasing temporary relief."}}, {"type": "reading", "content": {"title": "What Is Empty Within Cannot Be Filled by Temporary Substitutes", "body": "Spiritual emptiness can appear in many different ways.\n\nA person may experience:\n\nRestlessness.\n\nA lack of purpose.\n\nFeeling disconnected.\n\nLoneliness.\n\nInner emptiness.\n\nA constant sense that something is missing.\n\nDifficulty finding lasting peace.\n\nMany people may not describe these feelings in spiritual language, but they still experience them.\n\nWhen this emptiness remains unaddressed, substance abuse and other unhealthy behaviors can begin to look like answers.\n\nFor a short time they may provide excitement, relief, distraction, or emotional happiness.\n\nYet these experiences are temporary.\n\nThe deeper longing remains.\n\nLasting peace comes through developing a deeper relationship with your God, living according to spiritual values, and finding meaning through faith, service, gratitude, and personal growth.\n\nRecovery becomes meaningful when we stop asking only,\n\n\"How can I feel better?\"\n\nand begin asking,\n\n\"What is my spirit truly longing for?\"\n\nHealing grows as we nourish the deeper parts of ourselves instead of repeatedly trying to silence them.\n\nReflection Question:\n\nWhere do you experience the greatest sense of emptiness or disconnection in your life?"}}, {"type": "mentor_note", "content": {"note": "Temporary relief may quiet the moment, but lasting peace nourishes the spirit."}}, {"type": "video", "content": {"title": "Spiritual Emptiness", "description": "A mentor-led explanation of spiritual emptiness, the deeper needs of the human spirit, and why lasting healing comes through spiritual growth rather than temporary substitutes."}}, {"type": "pause_reflect", "content": {"question": "When do you most notice feelings of emptiness or disconnection?", "context": "Reflect on areas such as:\n\nYour sense of purpose.\n\nInner peace.\n\nYour relationship with the Divine.\n\nYour connection to your faith.\n\nHope for the future.\n\nFeeling emotionally or spiritually fulfilled.\n\nWhich area feels most important today?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about one form of emptiness you have been trying to fill through unhealthy habits.\n\nThen answer:\n\nWhat deeper need might exist beneath that emptiness?\n\nHow could your faith help you begin meeting that need in healthier ways?"}}, {"type": "mood_checkin", "content": {"question": "How spiritually connected do you feel today?"}}, {"type": "daily_action", "content": {"title": "Respond to the Emptiness with Faith", "action": "When you notice feelings of emptiness today, pause before seeking distraction or escape.\n\nSpend a few quiet moments in prayer, meditation, or personal reflection according to your faith.\n\nAsk for wisdom, peace, and guidance as you seek lasting fulfillment rather than temporary relief."}}, {"type": "mentor_note", "content": {"note": "The deepest needs of the spirit cannot be satisfied by temporary substitutes by getting high.\n\nAs your faith grows stronger, your capacity for lasting peace and healing grows with it."}}, {"type": "quiz", "content": {"question": "According to this lesson, spiritual emptiness:", "options": [{"text": "Can be permanently satisfied through temporary pleasures.", "is_correct": false}, {"text": "Cannot be fully satisfied by temporary substitutes.", "is_correct": true}, {"text": "Is not connected to recovery.", "is_correct": false}, {"text": "Is something only a few people experience.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Temporary relief can permanently satisfy the deeper needs of the spirit.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What helps deepen lasting recovery?", "options": [{"text": "Constantly seeking temporary relief.", "is_correct": false}, {"text": "Nourishing your spiritual life through the practices of your faith.", "is_correct": true}, {"text": "Ignoring feelings of emptiness.", "is_correct": false}, {"text": "Keeping yourself constantly distracted.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 4.", "encouragement": "Today you learned that many struggles with drug abuse and addiction are connected to deeper spiritual needs that temporary solutions like getting high can never truly satisfy. As you continue strengthening your faith and nourishing your inner life, you build a stronger foundation for lasting peace, purpose, and recovery.\n\nIn the next lesson, we will explore the desire to belong and discover how the search for acceptance and connection can influence the choices we make."}}]}, {"number": 5, "title": "The Desire to Belong", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "The Need to Belong Can Shape Powerful Choices", "message": "Every person has a deep desire to feel accepted, valued, and connected.\n\nWe are created for healthy relationships, community, and mutual support. When these needs are not met, people may begin searching for belonging in places that ultimately might cause harm.\n\nThis lesson explores how the desire to belong can influence addiction and why finding healthy, life-giving relationships is an important part of complete recovery."}}, {"type": "reading", "content": {"title": "The Need to Belong Is Healthy, but Not Every Place of Belonging Is", "body": "The desire for belonging is not a weakness.\n\nIt is part of being human.\n\nMany people first encounter the abuse of drugs through friendships, social groups, or environments where acceptance feels connected to unhealthy behaviors.\n\nA person may begin using substances because they want:\n\nAcceptance.\n\nFriendship.\n\nIdentity.\n\nProtection.\n\nApproval.\n\nA sense of community.\n\nRelief from feeling alone.\n\nThe problem is not the desire to belong.\n\nThe problem arises when belonging requires compromising your values, harming yourself, hiding the truth, or continuing destructive patterns.\n\nFalse belonging often comes with conditions.\n\nIt may require secrecy.\n\nIt may encourage unhealthy behavior.\n\nIt may make drug abuse feel normal.\n\nHealthy belonging is different.\n\nWe have to encourage relationships built on honesty, compassion, encouragement, accountability, and mutual care.\n\nRecovery often requires letting go of relationships or environments that encourage drug abuse while intentionally building connections that support healing and personal growth.\n\nTrue belonging never requires you to destroy yourself to remain accepted.\n\nReflection Question:\n\nHow has your desire to belong influenced the choices you have made?"}}, {"type": "mentor_note", "content": {"note": "Real belonging strengthens your life of relationships. False belonging slowly destroys relationships."}}, {"type": "video", "content": {"title": "The Desire to Belong", "description": "A mentor-led explanation of how the human need for acceptance influences addiction and why healthy relationships play an essential role in lasting recovery."}}, {"type": "pause_reflect", "content": {"question": "Where have you looked for acceptance or belonging?", "context": "Think about:\n\nFriend groups.\n\nRelationships.\n\nSocial environments.\n\nCommunities.\n\nFamily expectations.\n\nOnline spaces.\n\nWhich of these have encouraged your healing?\n\nWhich have encouraged destructive choices?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about one place or relationship where you sought belonging but found yourself moving further away from the life you wanted.\n\nThen describe what healthy, supportive relationships would look like for you moving forward."}}, {"type": "mood_checkin", "content": {"question": "How connected and supported do you feel today?"}}, {"type": "daily_action", "content": {"title": "Strengthen One Healthy Connection", "action": "Take one small step today toward someone who supports your healing.\n\nSpend a few moments in prayer or personal reflection according to your faith, asking for wisdom to recognize relationships that encourage growth, honesty, and lasting recovery."}}, {"type": "mentor_note", "content": {"note": "True belonging does not require you to hide who you are or compromise your values.\n\nHealthy relationships encourage healing, honesty, and hope."}}, {"type": "quiz", "content": {"question": "According to this lesson, the desire to belong is:", "options": [{"text": "A weakness that should be ignored.", "is_correct": false}, {"text": "A healthy human need that can be found in harmful places.", "is_correct": true}, {"text": "Always dangerous.", "is_correct": false}, {"text": "Only important during childhood.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Every form of acceptance leads to healthy relationships.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What often supports lasting recovery?", "options": [{"text": "Protecting unhealthy relationships.", "is_correct": false}, {"text": "Building healthy, honest, and supportive community.", "is_correct": true}, {"text": "Isolating yourself completely.", "is_correct": false}, {"text": "Pretending you do not need other people.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 5.", "encouragement": "Today you learned that the desire to belong is a healthy part of being human, but not every place of belonging leads to a healthy lifestyle. As you continue your recovery journey, seek relationships that encourage honesty, accountability, compassion, and the values of your faith. A healthy community strengthens recovery and reminds you that you do not have to walk this journey alone."}}]}, {"number": 6, "title": "False Comforts and False Solutions", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Some Comforts Bring Temporary Relief While Quietly Deepening the Problem", "message": "Not every source of comfort leads to proper satisfaction.\n\nSome things provide temporary relief from pain, fear, loneliness, or stress, but leave us carrying even greater burdens afterward.\n\nWisdom helps us distinguish between what simply feels good in the moment and what truly brings lasting peace and progress.\n\nThis lesson explores how false comforts and false solutions can strengthen drug abuse and addiction with no proper insight to advancing in life."}}, {"type": "reading", "content": {"title": "Temporary Relief Is Not Always Lasting Healing", "body": "When people are hurting, they naturally seek relief.\n\nIf something quickly reduces anxiety, numbs emotional pain, boosts confidence, quiets loneliness, or changes how they feel, it can begin to look like the answer.\n\nThe problem is that many false comforts only treat the symptoms.\n\nThey do not satisfy the deeper reasons.\n\nOver time they often strengthen the very struggles they promise to solve.\n\nA false comfort may:\n\nTemporarily reduce emotional pain.\n\nCreate a sense of control.\n\nDistract from difficult emotions.\n\nProvide temporary confidence.\n\nOffer a brief escape from reality.\n\nBut eventually it often produces:\n\nGreater dependence.\n\nMore emotional pain.\n\nBroken relationships.\n\nShame.\n\nLoss of peace.\n\nSpiritual disconnection.\n\nWe have to evaluate our choices not only by how they make us feel today, but by the long-term fruit they produce.\n\nRecovery becomes stronger when we ask:\n\nIs continuous drug abuse helping me heal?\n\nOr is it only helping me avoid the problem?\n\nHealing may require more patience than escape.\n\nHealing builds a future instead of creating deeper wounds.\n\nReflection Question:\n\nWhat have you treated as some sort of solution that has actually made your life more difficult over time?"}}, {"type": "mentor_note", "content": {"note": "The quickest comfort is not always the one that leads to lasting healing."}}, {"type": "video", "content": {"title": "False Comforts and False Solutions", "description": "A mentor-led explanation of how temporary comforts can become destructive substitutes for genuine healing, and why lasting recovery requires evaluating choices by their long-term impact."}}, {"type": "pause_reflect", "content": {"question": "Which false comforts have you depended on most?", "context": "Think about things that seemed helpful at first but gradually caused greater problems. Of which drug abuse is already one thing.\n\nAsk yourself:\n\nWhat did it/they promise?\n\nWhat has it actually produced?\n\nWhat healthier alternative could meet that need?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about one false comfort you have relied on.\n\nThen answer:\n\nWhat need was it trying to meet?\n\nWhat has it cost you over time?\n\nWhat healthier source of comfort could begin replacing it?"}}, {"type": "mood_checkin", "content": {"question": "How strong is your desire for quick relief to get high today?"}}, {"type": "daily_action", "content": {"title": "Test Every Comfort Carefully", "action": "Before choosing a quick source of comfort today, pause for a moment.\n\nSpend a few quiet moments in prayer or personal reflection according to your faith.\n\nAsk yourself:\n\nWill this bring lasting healing?\n\nOr only temporary relief?\n\nChoose the response that supports your long-term recovery."}}, {"type": "mentor_note", "content": {"note": "Healing often requires patience.\n\nFalse comfort seeks immediate relief, by getting high.\n\nTrue healing builds lasting peace, strength, and freedom."}}, {"type": "quiz", "content": {"question": "According to this lesson, what defines a false comfort?", "options": [{"text": "It heals the root of the problem.", "is_correct": false}, {"text": "It provides temporary relief while deepening the underlying issue.", "is_correct": true}, {"text": "It always feels painful.", "is_correct": false}, {"text": "It removes every struggle immediately.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Quick relief is always the healthiest solution.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What should guide healthy recovery choices?", "options": [{"text": "Seeking the fastest relief possible.", "is_correct": false}, {"text": "Evaluating choices by truth, their long-term impact, and the values of your faith.", "is_correct": true}, {"text": "Avoiding every uncomfortable emotion.", "is_correct": false}, {"text": "Doing whatever feels easiest.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 6.", "encouragement": "Today you learned that not every source of comfort leads to healing. Temporary relief may seem attractive, but lasting recovery grows when you choose what builds long-term peace, wisdom, and health rather than what simply removes discomfort for a moment. As you continue your journey, allow the guidance of your faith to help you recognize the difference between false comfort and genuine healing.\n\nIn the next lesson, we will explore how unhealthy beliefs and spiritual deception can strengthen addiction, and how truth helps break those destructive patterns."}}]}, {"number": 7, "title": "Spiritual Deception with Drug Addiction", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Deception Makes Harmful Choices Seem Necessary", "message": "One of the greatest dangers of addiction is not only the substance itself—it is the way addiction changes the way we think.\n\nDeception can cause people to believe harmful things like getting high is helpful, necessary, or even impossible to live without.\n\nAddiction often grows stronger through these false beliefs.\n\nThis lesson explores how unhealthy thinking and spiritual deception reinforce addiction, and how truth becomes one of the most powerful tools for lasting recovery."}}, {"type": "reading", "content": {"title": "Deception Gains Strength When Lies Go Unchallenged", "body": "Many sacred teachings remind us that deception often works through lies, confusion, fear, distorted thinking, and unhealthy beliefs.\n\nDrug addiction becomes stronger when people begin believing thoughts such as:\n\n\"I need this to survive.\"\n\n\"I''ll never change.\"\n\n\"One more time won''t matter.\"\n\n\"No one can help me.\"\n\n\"I''ve already gone too far.\"\n\n\"This is simply who I am.\"\n\nWhen these beliefs go unchallenged, they become powerful barriers to recovery.\n\nTruth brings freedom because it exposes deception for what it really is.\n\nRecovery becomes stronger when we learn to recognize unhealthy beliefs and replace them with truth.\n\nInstead of believing:\n\n\"I will never change.\"\n\nWe begin believing:\n\n\"Healing is possible, even if it takes time.\"\n\nInstead of believing:\n\n\"I am defined by my addiction.\"\n\nWe begin believing:\n\n\"My struggles do not define my worth or my future.\"\n\nThe more often truth replaces deception, the weaker addiction''s influence becomes.\n\nReflection Question:\n\nWhich unhealthy belief has had the greatest influence over your recovery journey?"}}, {"type": "mentor_note", "content": {"note": "A lie loses its power the moment it is recognized and challenged with truth."}}, {"type": "video", "content": {"title": "Spiritual Deception in Addiction", "description": "A mentor-led explanation of how unhealthy beliefs and spiritual deception strengthen addiction, and how truth, faith, and honest self-reflection help break those destructive patterns."}}, {"type": "pause_reflect", "content": {"question": "What belief keeps pulling you back toward unhealthy choices?", "context": "Think about the messages you repeatedly tell yourself.\n\nAsk yourself:\n\nIs this belief completely true?\n\nWhat evidence challenges it?\n\nWhat truth from my faith offers a positive perspective?"}}, {"type": "journal_prompt", "content": {"prompt": "Write down:\n\nOne unhealthy belief you often repeat.\n\nHow it has affected your choices.\n\nOne healthier truth that challenges it.\n\nOne way you will remind yourself of that truth this week."}}, {"type": "mood_checkin", "content": {"question": "How aware are you of unhealthy beliefs influencing your thinking today?"}}, {"type": "daily_action", "content": {"title": "Replace One Lie with One Truth", "action": "Spend a few quiet moments in prayer or personal reflection according to your faith.\n\nIdentify one unhealthy belief that has repeatedly influenced your decisions.\n\nWrite one truthful statement that challenges it, and read that statement several times throughout the day whenever the old belief returns."}}, {"type": "mentor_note", "content": {"note": "Truth does more than expose deception.\n\nIt creates the freedom to choose a completely better life.\n\nEvery truthful belief weakens the influence of drug abuse and strengthens your recovery."}}, {"type": "quiz", "content": {"question": "According to this lesson, deception often:", "options": [{"text": "Makes destructive patterns appear necessary or helpful.", "is_correct": true}, {"text": "Removes every struggle immediately.", "is_correct": false}, {"text": "Guarantees failure.", "is_correct": false}, {"text": "Eliminates personal responsibility.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Unhealthy beliefs can strengthen addictive patterns.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What helps weaken deception?", "options": [{"text": "Ignoring unhealthy thoughts.", "is_correct": false}, {"text": "Replacing unhealthy beliefs with truth.", "is_correct": true}, {"text": "Keeping struggles secret.", "is_correct": false}, {"text": "Avoiding self-reflection.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 7.", "encouragement": "Today you learned that addiction often grows stronger through unhealthy beliefs and spiritual deception. As you continue replacing harmful lies with truth, wisdom, and the guidance of your faith, you strengthen your ability to make healthier choices and continue building lasting recovery.\n\nIn the final lesson of this chapter, we will bring everything together by exploring the real needs of the heart and discovering healthier ways to meet those needs through faith, purpose, and genuine healing."}}]}, {"number": 8, "title": "Discovering the Real Need of the Heart", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Until the Real Need Is Understood, the False Solution Often Returns", "message": "Throughout this chapter, we have looked beyond addiction itself to discover what often lies beneath it.\n\nDrug abuse may have seemed like the answer to many different struggles, but underneath the substance there is often a deeper need that has remained unmet, misunderstood, or misdirected.\n\nLasting healing begins when we stop focusing only on outward behavior and honestly identify what our hearts have truly been longing for."}}, {"type": "reading", "content": {"title": "The Heart Continues Reaching Until Its True Needs Are Addressed", "body": "Many people discover that addiction was never only about the drugs and substances.\n\nIt was about what the substance appeared to provide.\n\nThe deeper needs of the heart may include:\n\nPeace.\n\nComfort.\n\nSafety.\n\nHealing.\n\nAcceptance.\n\nBelonging.\n\nPurpose.\n\nRest.\n\nHope.\n\nForgiveness.\n\nA deeper connection with God.\n\nDrug abuse may temporarily imitate these experiences.\n\nIt may create a feeling of relief, confidence, or peace.\n\nBut they cannot truly provide them.\n\nLasting fulfillment comes when these deeper needs are met through spiritual growth, healthy relationships, truth, service, compassion, and living according to the values of one''s faith.\n\nRecovery becomes stronger when we stop asking only,\n\n\"How do I stop using?\"\n\nand begin asking,\n\n\"What has my heart truly been searching for?\"\n\nOnce the deeper need is identified, healing can begin moving in a more honest and lasting direction.\n\nRecovery becomes less about fighting symptoms and more about rebuilding the whole person.\n\nReflection Question:\n\nWhat deeper need has your heart been reaching for beneath your addiction?"}}, {"type": "mentor_note", "content": {"note": "The false solution starts to lose its power when the true need is finally understood."}}, {"type": "video", "content": {"title": "Discovering the Real Need of the Heart", "description": "A mentor-led explanation of the deeper emotional, mental, and spiritual needs beneath addiction, and how lasting recovery begins by meeting those needs through faith, healthy relationships, and genuine healing."}}, {"type": "pause_reflect", "content": {"question": "What do you believe your heart has been needing most?", "context": "Reflect on whether you have been searching for:\n\nPeace.\n\nSafety.\n\nComfort.\n\nRest.\n\nBelonging.\n\nHope.\n\nForgiveness.\n\nPurpose.\n\nRelief from emotional pain.\n\nA deeper connection with the Divine.\n\nWhich need feels most important for you today?"}}, {"type": "journal_prompt", "content": {"prompt": "Complete this sentence:\n\n\"The deeper need beneath my struggle may be...\"\n\nThen describe:\n\nWhy has this need become so important.\n\nWhere have you been looking to satisfy it.\n\nHow your faith, healthy relationships, and personal growth can help you meet that need in healthier ways."}}, {"type": "mood_checkin", "content": {"question": "How connected do you feel to your deeper emotional and spiritual needs today?"}}, {"type": "daily_action", "content": {"title": "Name the True Need", "action": "Spend a few quiet moments in prayer or personal reflection according to your faith.\n\nIdentify one deeper need your heart has been searching for.\n\nRather than turning toward temporary relief, ask for wisdom, guidance, strength, and peace as you begin meeting that need through healthier choices and spiritual growth."}}, {"type": "mentor_note", "content": {"note": "When the true purpose is understood, recovery becomes more than avoiding drug abuse.\n\nIt becomes the journey of rebuilding a healthier, more meaningful life.\n\nEvery honest step toward your deepest purpose becomes another step toward lasting healing."}}, {"type": "quiz", "content": {"question": "According to this lesson, what is one of the most important shifts in recovery?", "options": [{"text": "Focusing only on stopping the behavior.", "is_correct": false}, {"text": "Identifying the deeper need beneath the struggle.", "is_correct": true}, {"text": "Ignoring emotional needs.", "is_correct": false}, {"text": "Treating every craving exactly the same.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Drugs can permanently provide what the heart truly needs.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What question helps deepen lasting recovery?", "options": [{"text": "How do I hide my struggle?", "is_correct": false}, {"text": "What has my heart truly been searching for?", "is_correct": true}, {"text": "How can I avoid every difficult feeling?", "is_correct": false}, {"text": "Why does recovery take so long?", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 8.", "encouragement": "Today you learned that addiction often reflects deeper emotional, mental, and spiritual needs rather than the substance alone. As you continue identifying those needs and responding to them with honesty, healthy relationships, spiritual growth, and the guidance of your faith, you strengthen the foundation for lasting recovery.\n\nYou have now completed Chapter 4: The Real Reason People Do Drugs. You understand that recovery is not only about breaking free from substances—it is about discovering what your heart has truly been seeking and learning to meet those needs in ways that bring lasting healing, peace, purpose, and hope. As you continue into Chapter 5, you will explore how addiction develops over time and learn how recognizing its progression can help prevent relapse and support lifelong recovery."}}]}]}, {"number": 5, "title": "The Three Stages of Drug Abuse", "description": "Chapter 5 explores how drug addiction develops over time rather than appearing all at once. It follows the progression from curiosity and experimentation to repeated use, dependency, strong desire, loss of control, growing personal cost, honest self-recognition, and ultimately the path toward lasting freedom and recovery.\n\nThe goal of this chapter is to help you understand addiction as a gradual process, recognize your current stage with honesty, and respond with wisdom, humility, responsibility, and hope. By understanding how addiction grows, you become better equipped to break destructive patterns before they become even more deeply rooted.", "lessons": [{"number": 1, "title": "Understanding the Addiction Journey", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Addiction Usually Develops Through Stages, Not All at Once", "message": "Many people think and believe that drug addiction appears suddenly, but it usually develops gradually over time through the initial stages of drug abuse.\n\nWhat may begin as curiosity or experimentation can slowly grow into repeated use, dependency, and then intense unrelenting cravings becomes frequent.\n\nHarmful patterns often develop at the stage of dependency. Understanding this progression helps us recognize warning signs early and respond with wisdom before the pattern becomes more deeply rooted.\n\nThis lesson introduces the addiction journey and helps you understand that lasting recovery begins with honestly recognizing how the journey unfolded."}}, {"type": "reading", "content": {"title": "Understanding the Journey Helps You Respond with Greater Clarity", "body": "Drug addiction is not a single event.\n\nIt is usually a process and progressive.\n\nA person may move through stages such as:\n\nCuriosity.\n\nExperimentation.\n\nRepeated use.\n\nDependency.\n\nConsistent increase dosage.\n\nAddiction.\n\nFull blown addiction.\n\nEach stage builds upon the one before.\n\nRepeated choices to get high gradually strengthen patterns of need until it creates dysfunction in daily life.\n\nUnderstanding this progression is important because many people don''t always know at what stage of drug abuse they are, until they are fully addicted.\n\nSome believe they are safe simply because they have not reached the later stages.\n\nOthers lose hope because they focus only on how far they have fallen.\n\nDoing honest self-examination is not always easy, because of ignorance about drug abuse.\n\nWhen we learn more from experts, we become better able to recognize where we are today and take meaningful action toward healing.\n\nWe always seem to wonder,\n\n\"How did this happen so quickly?\"\n\nand begin asking,\n\n\"What steps to take to become wiser at everyday decisions?\"\n\nEvery journey begins with small choices.\n\nRecovery does as well.\n\nReflection Question:\n\nLooking back, how did your addiction gradually develop over time?"}}, {"type": "mentor_note", "content": {"note": "Bad habits are often overlooked until their effects become impossible to ignore."}}, {"type": "video", "content": {"title": "Understanding the Addiction Journey", "description": "A mentor-led explanation of how addiction develops through stages, why harmful patterns deepen over time, and how recognizing the journey creates clarity for lasting recovery."}}, {"type": "pause_reflect", "content": {"question": "Which stage of your journey do you relate to most strongly?", "context": "Reflect on how your struggle developed.\n\nWas it curiosity?\n\nExperimentation?\n\nRepeated habits?\n\nDependency?\n\nLoss of control?\n\nWhat does recognizing that stage teach you about your recovery today?"}}, {"type": "journal_prompt", "content": {"prompt": "Write a brief summary describing how your addiction progressed over time.\n\nIdentify the major turning points that moved it from an occasional behavior into a recurring pattern."}}, {"type": "mood_checkin", "content": {"question": "How clearly do you understand your own addiction journey today?"}}, {"type": "daily_action", "content": {"title": "Map Your Journey Honestly", "action": "Create a simple timeline of your drug abusive journey.\n\nMark the major stages that stand out to you.\n\nSpend a few moments in prayer or personal reflection according to your faith, asking for wisdom to understand your past honestly and courage to continue moving toward healing."}}, {"type": "mentor_note", "content": {"note": "Clarity about the journey is one of the greatest insights against repeating it.\n\nProper understanding creates the foundation for lasting change."}}, {"type": "quiz", "content": {"question": "According to this lesson, addiction usually:", "options": [{"text": "Appears instantly.", "is_correct": false}, {"text": "Develops gradually through stages.", "is_correct": true}, {"text": "Only affects certain people.", "is_correct": false}, {"text": "Cannot be understood.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Understanding how addiction develops helps strengthen recovery.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "Why is understanding the addiction journey important?", "options": [{"text": "It excuses harmful behavior.", "is_correct": false}, {"text": "It helps us recognize how destructive patterns develop and where change can begin.", "is_correct": true}, {"text": "It removes responsibility.", "is_correct": false}, {"text": "It guarantees immediate recovery.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 1.", "encouragement": "Today you learned that drug abuse and addiction is usually a gradual journey rather than a sudden event. By understanding how destructive patterns develop over time, you gain greater clarity about your own recovery and become better prepared to breaking those patterns before they grow stronger.\n\nIn the next lesson, we will explore curiosity and experimentation and discover why many addictions begin with what appears to be a small and harmless first step."}}]}, {"number": 2, "title": "Curiosity and Experimentation", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Many Addictions Begin with a Small Step That Seems Harmless", "message": "Very few people begin using drugs expecting to become addicted, not realizing.\n\nFor many, drug abuse begins with curiosity, experimentation, or the belief that trying something \"just once\" will have no lasting consequences.\n\nWe have to be wise to recognize when curiosity leads us toward growth and when it begins leading us toward harm.\n\nThis lesson explores why the earliest decisions matter and how healthy boundaries can prevent destructive behavior before they begin."}}, {"type": "reading", "content": {"title": "Small Decisions Often Shape Bigger Outcomes", "body": "Curiosity is a natural part of being human.\n\nIt helps us learn, grow, and discover new things.\n\nHowever, curiosity becomes dangerous when it draws us toward harmful substances, destructive behaviors, or unhealthy environments.\n\nMany people begin experimenting because they want:\n\nTo fit in.\n\nTo satisfy curiosity.\n\nTo escape daily stresses.\n\nTo experience excitement.\n\nTo cope with emotional pain.\n\nTo feel accepted.\n\nTo prove something to themselves or others.\n\nAt first, the consequences may seem small.\n\nNothing dramatic happens except for the experience and power of getting high.\n\nBecause of this, the first step is often minimized.\n\nYet every repeated decision begins shaping future habits.\n\nWe have to guard our hearts, minds, and choices by being wise these days.\n\nRecovery reminds us that harmful patterns rarely begin with major decisions.\n\nThey often begin with small compromises that slowly become easier to repeat.\n\nLearning to recognize these early moments helps protect us from much greater struggles later.\n\nHealthy boundaries are strongest before the pattern begins.\n\nReflection Question:\n\nLooking back, what made experimentation seem acceptable at the time?"}}, {"type": "mentor_note", "content": {"note": "The smallest decision can become the beginning of the biggest changes."}}, {"type": "video", "content": {"title": "Curiosity and Experimentation", "description": "A mentor-led explanation of how curiosity can lead to experimentation, why early choices matter, and how healthy boundaries protect us from destructive patterns."}}, {"type": "pause_reflect", "content": {"question": "What influenced your first decision to experiment with drugs?", "context": "Think about:\n\nFriends.\n\nCuriosity.\n\nEmotional pain.\n\nStress.\n\nThe desire to belong.\n\nSocial pressure.\n\nThe belief that nothing serious would happen.\n\nWhich of these had the greatest influence?"}}, {"type": "journal_prompt", "content": {"prompt": "Write honestly about your first experience with experimentation.\n\nThen answer:\n\nWhat were you hoping to gain?\n\nWhat did you believe would happen?\n\nWhat do you understand differently today?"}}, {"type": "mood_checkin", "content": {"question": "How aware are you of situations where curiosity could still lead you toward unhealthy choices?"}}, {"type": "daily_action", "content": {"title": "Protect the First Step", "action": "Identify one area of your life where casual curiosity could still lead you toward getting drugs.\n\nSpend a few moments in prayer or personal reflection according to your faith.\n\nThen establish one clear boundary that will help protect your recovery before temptation becomes action."}}, {"type": "mentor_note", "content": {"note": "Recovery often begins by respecting the small decisions that shape the larger journey.\n\nWisdom protects long before regret appears."}}, {"type": "quiz", "content": {"question": "According to this lesson, why is experimentation significant?", "options": [{"text": "It is always harmless.", "is_correct": false}, {"text": "It can become the beginning of a journey to full blown addiction.", "is_correct": true}, {"text": "It immediately causes addiction.", "is_correct": false}, {"text": "It has no long-term influence.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Most people begin experimenting while expecting to become addicted.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What helps prevent harmful experimentation?", "options": [{"text": "Acting on every curiosity.", "is_correct": false}, {"text": "Wisdom, healthy boundaries, and thoughtful choices.", "is_correct": true}, {"text": "Ignoring consequences.", "is_correct": false}, {"text": "Following the crowd.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 2.", "encouragement": "Today you learned that addiction often begins with what appears to be a small and harmless first step. By recognizing how curiosity, social influence, and emotional needs can shape early decisions, you strengthen your ability to make wise choices that protect your future. Every healthy boundary you establish today helps prevent destructive patterns from taking root tomorrow."}}]}, {"number": 3, "title": "Repeated Use and Habit Formation", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "What We Repeat Often Begins to Shape Who We Become", "message": "The difference between experimentation and drug addiction is consistent use.\n\nWhat begins as an occasional choice can slowly become a routine that feels normal.\n\nRepeated inducing drugs, especially with high addiction probability shapes the character, the habits, and the path the individual takes in life.\n\nThis lesson explores how repeated use becomes habit, why habits become increasingly difficult to break, and how recognizing these patterns is essential for lasting and full recovery."}}, {"type": "reading", "content": {"title": "Repeated Choices Gradually Become Automatic Patterns", "body": "Habits develop through repetition.\n\nEach time a behavior is repeated, the mind and body become more familiar with it.\n\nOver time, what once required a conscious decision may begin happening autonomously.\n\nMany people notice that certain triggers become connected to their substance use, such as:\n\nStress.\n\nLoneliness.\n\nAnger.\n\nCertain places.\n\nCertain people.\n\nSpecific times of day.\n\nCelebrations or difficult events.\n\nEventually these situations begin creating powerful urges.\n\nThe behavior starts feeling less like a choice and more like a familiar response.\n\nMany faith traditions teach that repeated choices strengthen patterns—whether healthy or unhealthy.\n\nThe encouraging truth is that habits can also be changed.\n\nRecovery involves identifying the routines, triggers, and beliefs that support addiction and intentionally and gradually replacing them with positive responses.\n\nBreaking a habit is not simply about resisting temptation.\n\nIt is about creating new patterns that strengthen healing and a better life instead of a life of addiction.\n\nReflection Question:\n\nWhat situations, emotions, or routines most often trigger your unhealthy habits?"}}, {"type": "mentor_note", "content": {"note": "What is repeated long enough begins to feel normal, even when it causes harm."}}, {"type": "video", "content": {"title": "Repeated Use and Habit Formation", "description": "A mentor-led explanation of how repeated choices create habits, how triggers strengthen addictive patterns, and how new healthy routines support lasting recovery."}}, {"type": "pause_reflect", "content": {"question": "Think about your own habit patterns.", "context": "Which situations most often lead you toward substance use?\n\nReflect on:\n\nPlaces.\n\nPeople.\n\nEmotions.\n\nTimes of day.\n\nStressful situations.\n\nCelebrations.\n\nBoredom.\n\nWhat patterns do you notice?"}}, {"type": "journal_prompt", "content": {"prompt": "List the three strongest triggers that have supported your addiction.\n\nThen describe one healthier response you could practice when each trigger appears."}}, {"type": "mood_checkin", "content": {"question": "How aware are you of your habit patterns today?"}}, {"type": "daily_action", "content": {"title": "Interrupt One Habit Loop", "action": "Choose one recurring trigger you often experience.\n\nSpend a few quiet moments in prayer or personal reflection according to your faith.\n\nCreate a simple plan for what you will do differently the next time that trigger appears.\n\nReplace the old response with one healthy action that supports your recovery."}}, {"type": "mentor_note", "content": {"note": "Habits and strongholds are strengthened through repetition.\n\nThey are changed through intentional repetition of better choices.\n\nEvery new and wise response weakens the old pattern."}}, {"type": "quiz", "content": {"question": "According to this lesson, habit formation happens primarily through:", "options": [{"text": "One-time experiences.", "is_correct": false}, {"text": "Repeated choices and repeated use.", "is_correct": true}, {"text": "Luck.", "is_correct": false}, {"text": "Sudden personality changes.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Triggers and routines often become connected to addictive behaviors.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What often strengthens lasting recovery?", "options": [{"text": "Ignoring habit patterns.", "is_correct": false}, {"text": "Identifying triggers and replacing unhealthy routines with healthier responses.", "is_correct": true}, {"text": "Hoping habits disappear on their own.", "is_correct": false}, {"text": "Avoiding self-reflection.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 3.", "encouragement": "Today you learned how repeated use could gradually become a habit and how familiar routines can quietly strengthen addiction over time. By identifying your triggers and intentionally replacing unhealthy patterns with healthier responses, you begin creating new habits that support healing, freedom, and lasting recovery through the guidance of your faith."}}]}, {"number": 4, "title": "Dependency and Bondage", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Dependency Grows When Saying \"No\" No Longer Feels Easy", "message": "As drug addiction progresses, there comes a point where the substance or behavior no longer feels optional.\n\nWhat once seemed like a personal choice begins feeling like a necessity.\n\nTraditional teachings identify that anything which begins controlling our thoughts, choices, or actions can gradually take the place of the freedom we were created to live in.\n\nThis lesson explores how dependency develops, why it becomes so powerful, and how recognizing it honestly becomes an important step toward recovery."}}, {"type": "reading", "content": {"title": "Dependency Slowly Replaces Freedom with Control", "body": "Dependency develops gradually from casual drug taking.\n\nAt first, a person may choose to use a substance occasionally.\n\nOver time, however, the relationship with drug abuse begins to change.\n\nInstead of using because the person wants to, they begin using because they feel they need to.\n\nDependency may appear through:\n\nStrong cravings.\n\nFeeling unable to cope without the substance.\n\nEmotional distress when trying to stop.\n\nOrganizing daily life around using.\n\nConstantly thinking about the next opportunity to use.\n\nFeeling unable to relax or function without it.\n\nComplete freedom cannot exist where another character behavior or action has become our master.\n\nDependency affects more than what the body feels.\n\nIt also influence the thoughts, emotions, relationships, decision-making, and spiritual well-being.\n\nThe encouraging truth is that dependency does not have to be permanent.\n\nRecovery begins with honesty.\n\nWhen we stop pretending we are fully in control, we become more willing to seek support, establish healthy boundaries, strengthen our faith, and begin rebuilding our freedom one choice at a time.\n\nRecognizing dependency is not admitting defeat.\n\nIt is taking the first courageous step toward healing.\n\nReflection Question:\n\nWhen did you first realize your addiction had become more than an occasional habit?"}}, {"type": "mentor_note", "content": {"note": "What begins as a choice can gradually become something that feels like it is making the choices for us."}}, {"type": "video", "content": {"title": "Dependency and Bondage", "description": "A mentor-led explanation of how dependency develops, why it creates a growing loss of freedom, and how honest recognition becomes an important turning point in lasting recovery."}}, {"type": "pause_reflect", "content": {"question": "Where have you noticed dependency on drugs affecting your life?", "context": "Think about:\n\nYour thoughts.\n\nYour emotions.\n\nYour daily routines.\n\nYour relationships.\n\nYour ability to say no.\n\nYour sense of freedom.\n\nWhich area has been affected most?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about the moment you realized your drug abusive lifestyle was no longer simply a habit.\n\nThen answer:\n\nWhat signs showed that dependency had developed?\n\nHow has it affected your daily life?\n\nWhat support do you believe you need to continue moving toward freedom?"}}, {"type": "mood_checkin", "content": {"question": "How free or trapped do you feel by your current patterns today?"}}, {"type": "daily_action", "content": {"title": "Tell the Truth About the Hold It Has Had", "action": "Spend a few quiet moments in prayer or personal reflection according to your faith.\n\nWrite one honest sentence describing how dependency has affected your life.\n\nThen write one practical step you can take today that moves you toward greater freedom and healing."}}, {"type": "mentor_note", "content": {"note": "Freedom begins growing the moment we stop pretending we are fully in control.\n\nHonesty opens the door to healing."}}, {"type": "quiz", "content": {"question": "According to this lesson, dependency develops when:", "options": [{"text": "The behavior remains completely optional.", "is_correct": false}, {"text": "The substance or behavior begins feeling necessary rather than optional.", "is_correct": true}, {"text": "Recovery has already failed.", "is_correct": false}, {"text": "A person loses every emotion.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Dependency can affect emotional, mental, spiritual, and physical well-being.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What is one of the most important first steps toward overcoming dependency?", "options": [{"text": "Pretending the problem does not exist.", "is_correct": false}, {"text": "Honestly recognizing the loss of freedom and seeking support.", "is_correct": true}, {"text": "Waiting until things become worse.", "is_correct": false}, {"text": "Relying only on willpower.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 4.", "encouragement": "Today you learned that dependency develops gradually as drug abuse begins replacing freedom with control. Although this stage can feel overwhelming, it does not have to define your future. Honest recognition, healthy support, wise boundaries, and the guidance of your faith can help you begin rebuilding the freedom that addiction has tried to take away.\n\nIn the next lesson, we will explore the progression of addiction and discover why addiction rarely remains the same, but instead continues demanding more while giving less in return."}}]}, {"number": 5, "title": "The Progression of Addiction", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Addiction Rarely Stands Still", "message": "Addiction is not a fixed condition.\n\nIf left unchallenged, it often continues to grow, demanding more while offering less in return.\n\nUnhealthy patterns and life choices become stronger when they are continually fed. Without honest intervention, destructive behaviors rarely remain the same—they gradually become more deeply rooted.\n\nThis lesson explores how addiction progresses over time and why recognizing this progression is essential for lasting recovery."}}, {"type": "reading", "content": {"title": "Addiction Gradually Demands More While Giving Less", "body": "As addiction develops, the same behavior often stops producing the same effect.\n\nA person may begin needing:\n\nLarger amounts of the substance.\n\nMore frequent use.\n\nGreater risks.\n\nStronger stimulation.\n\nMore secrecy.\n\nMore time spent thinking about or obtaining the substance.\n\nAt the same time, the satisfaction becomes weaker.\n\nWhat once brought temporary relief may now bring only brief escape before cravings return.\n\nThe cost continues increasing while the rewards continue decreasing.\n\nThere is no substantial satisfaction in a life of drug abuse.\n\nThey continually ask for more attention, more compromise, and more sacrifice.\n\nRecovery becomes stronger when we honestly recognize this progression.\n\nInstead of believing the addiction will eventually stabilize on its own, we begin understanding that without change, it usually continues growing.\n\nRecognizing this truth helps us respond with greater urgency, wisdom, and hope.\n\nEvery interruption of the pattern weakens its future influence.\n\nReflection Question:\n\nHow has your addiction demanded more from you over time?"}}, {"type": "mentor_note", "content": {"note": "Addiction grows by asking for more while giving less."}}, {"type": "video", "content": {"title": "The Progression of Addiction", "description": "A mentor-led explanation of how addiction gradually escalates through increased tolerance, greater demands, and growing consequences, and why recognizing this progression strengthens recovery."}}, {"type": "pause_reflect", "content": {"question": "In what ways has your addiction changed since it first began?", "context": "Think about:\n\nTime.\n\nMoney.\n\nEmotional energy.\n\nRelationships.\n\nSecrecy.\n\nHealth.\n\nRisk.\n\nThe amount needed to feel the same effect.\n\nWhat changes stand out most?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about three ways your addiction became more demanding over time.\n\nThen describe one area where you want that progression to stop today."}}, {"type": "mood_checkin", "content": {"question": "How clearly do you recognize the progression of your addiction today?"}}, {"type": "daily_action", "content": {"title": "Name the Escalation Honestly", "action": "Spend a few quiet moments in prayer or personal reflection according to your faith.\n\nIdentify one area where your addiction now costs significantly more than it did when it first began.\n\nWrite it down honestly.\n\nThen identify one practical step you can take today to interrupt that progression."}}, {"type": "mentor_note", "content": {"note": "Every destructive pattern keeps asking for more until it is interrupted by truth, courage, and intentional action.\n\nRecovery begins when the progression finally stops."}}, {"type": "quiz", "content": {"question": "According to this lesson, addiction usually:", "options": [{"text": "Remains the same over time.", "is_correct": false}, {"text": "Gradually demands more while giving less.", "is_correct": true}, {"text": "Becomes easier to manage without change.", "is_correct": false}, {"text": "Eventually solves itself.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Addiction often progresses through increasing tolerance, greater demands, and growing consequences.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "Why is recognizing the progression of addiction important?", "options": [{"text": "It helps us understand that destructive patterns deepen unless they are interrupted.", "is_correct": true}, {"text": "It removes responsibility.", "is_correct": false}, {"text": "It guarantees recovery.", "is_correct": false}, {"text": "It makes change unnecessary.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 5.", "encouragement": "Today you learned that addiction rarely remains unchanged. Left unchallenged, it gradually demands more while giving less, increasing its impact on every area of life. By recognizing this progression honestly, you strengthen your ability to interrupt destructive patterns before they deepen further. Every healthy choice you make today helps redirect your future toward lasting healing, freedom, and the guidance of your faith."}}]}, {"number": 6, "title": "Losing Control", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Losing Control Happens When Intentions and Actions No Longer Match", "message": "Many people struggling with addiction sincerely want to stop.\n\nThey make promises to themselves.\n\nThey set limits.\n\nThey decide that \"this will be the last time.\"\n\nYet as addiction deepens, those intentions are often followed by the same behavior.\n\nTrue freedom does not simply happen by having good intentions, but having the ability to develop a strong mind, heart and will to be free, that is wisdom.\n\nThis lesson explores what losing control really looks like and why honestly recognizing it becomes a turning point in recovery."}}, {"type": "reading", "content": {"title": "Honest Recognition Creates the Opportunity for Real Change", "body": "Loss of control rarely happens all at once.\n\nIt often appears gradually through repeated experiences such as:\n\nBreaking promises to yourself.\n\nRepeated relapse.\n\nFailing to keep personal boundaries.\n\nFeeling unable to stop despite wanting to.\n\nHiding your behavior from others.\n\nContinuing even after serious consequences.\n\nMany people continue believing they are fully in control because they occasionally manage to stop for short periods.\n\nHowever, lasting control is measured not by isolated successes, but by consistent developing principles that lays the road to freedom.\n\nHumility is the beginning of wisdom.\n\nRecovery becomes stronger when we stop arguing with the evidence and honestly admit where control has been lost.\n\nThis honesty is not a sign of weakness.\n\nIt is a sign of courage.\n\nOnce we acknowledge the reality of our situation, we become more willing to seek support, strengthen our faith, establish healthy boundaries, and accept the help needed to rebuild lasting freedom.\n\nReflection Question:\n\nWhen did you first realize your intentions were no longer matching your actions?"}}, {"type": "mentor_note", "content": {"note": "Real change often begins the moment we stop pretending we are fully in control."}}, {"type": "video", "content": {"title": "Losing Control", "description": "A mentor-led explanation of how addiction gradually creates a gap between intention and behavior, and why honest humility becomes an essential step toward lasting recovery."}}, {"type": "pause_reflect", "content": {"question": "Where have your intentions and actions been most different?", "context": "Think about:\n\nPromises you made.\n\nLimits you tried to set.\n\nTimes you believed you could stop.\n\nSituations where the addiction became stronger than your plans.\n\nWhat do these experiences reveal?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about one moment when you clearly recognized that your addiction had become stronger than your personal determination.\n\nThen answer:\n\nWhat did you learn from that experience?\n\nWhat support do you now recognize you need?\n\nWhat healthier step can you begin taking today?"}}, {"type": "mood_checkin", "content": {"question": "How honest are you willing to be about your current level of control today?"}}, {"type": "daily_action", "content": {"title": "Stop Negotiating with the Evidence", "action": "Spend a few quiet moments in prayer or personal reflection according to your faith.\n\nWrite one honest example where your behavior did not match your intentions.\n\nRather than judging yourself, use this moment to strengthen your commitment to seeking healing, support, and lasting change."}}, {"type": "mentor_note", "content": {"note": "Honest humility is not defeat.\n\nIt is often the doorway to wisdom, healing, and lasting freedom."}}, {"type": "quiz", "content": {"question": "According to this lesson, losing control is often revealed when:", "options": [{"text": "Everything goes according to plan.", "is_correct": false}, {"text": "Intentions repeatedly fail to match behavior.", "is_correct": true}, {"text": "A person never tries to stop.", "is_correct": false}, {"text": "Someone else notices the addiction first.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Honestly recognizing a loss of control can become an important turning point in recovery.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "Why is honest recognition of lost control important?", "options": [{"text": "It encourages shame.", "is_correct": false}, {"text": "It creates the humility needed to seek real help and lasting change.", "is_correct": true}, {"text": "It removes responsibility.", "is_correct": false}, {"text": "It proves recovery is impossible.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 6.", "encouragement": "Today you learned that losing control is often revealed when your actions no longer reflect your intentions. While this realization can be difficult, it also marks the beginning of meaningful change. Honest self-awareness, healthy support, and the guidance of your faith can help you rebuild the freedom that addiction has slowly taken away.\n\nIn the next lesson, we will explore the true cost of addiction and discover why honestly counting what addiction has taken from your life can strengthen your determination to pursue lasting recovery."}}]}, {"number": 7, "title": "The Cost of Addiction", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Every Addictive Pattern Has a Cost, Even If It Is Not Immediately Visible", "message": "Drug abuse often promises relief, excitement, comfort, or escape.\n\nWhat it rarely reveals at the beginning is the price that will eventually be paid.\n\nOur choices always produce consequences. Some are immediate, while others reveal itself slowly over time.\n\nThis lesson explores the true cost of drug abuse and addiction and why recognizing those losses strengthens our commitment to complete recovery."}}, {"type": "reading", "content": {"title": "Addiction Takes More Than It Ever Promised to Give", "body": "The cost of addiction is not measured only by money.\n\nOver time, addiction can gradually take away many important parts of life, including:\n\nPhysical health.\n\nEmotional well-being.\n\nPeace of mind.\n\nTrust.\n\nHealthy relationships.\n\nTime.\n\nFinancial stability.\n\nPersonal integrity.\n\nHope.\n\nSpiritual growth.\n\nSome losses happen suddenly.\n\nOthers develop so gradually that they are easy to ignore until they become overwhelming.\n\nMany people remain trapped because they continue remembering what addiction once seemed to offer while overlooking everything it has quietly taken.\n\nHonest self-examination is an important trait to have not only when struggling with drug abuse..\n\nRecovery becomes stronger when we stop minimizing the consequences and begin counting the true cost.\n\nThis is not meant to create shame.\n\nIt is meant to create clarity.\n\nWhen we clearly understand what addiction has been taking from us, our desire for lasting healing often becomes stronger than our desire for temporary relief.\n\nReflection Question:\n\nWhat has addiction cost you that matters most?"}}, {"type": "mentor_note", "content": {"note": "Anything that repeatedly takes your peace, your hope, or your freedom is costing more than it first appeared."}}, {"type": "video", "content": {"title": "The Cost of Addiction", "description": "A mentor-led explanation of the emotional, physical, relational, financial, and spiritual costs of addiction, and why honestly recognizing those losses strengthens lasting recovery."}}, {"type": "pause_reflect", "content": {"question": "What has your addiction cost you?", "context": "Think honestly about:\n\nYour health.\n\nYour relationships.\n\nYour peace.\n\nYour finances.\n\nYour opportunities.\n\nYour self-respect.\n\nYour spiritual life.\n\nYour hopes for the future.\n\nWhich loss feels most significant today?"}}, {"type": "journal_prompt", "content": {"prompt": "Write a list of the most important things addiction has taken from your life.\n\nThen answer:\n\nWhich loss hurts the most?\n\nWhich loss motivates you most to continue your recovery?\n\nWhat healthy choice today could begin rebuilding one of these areas?"}}, {"type": "mood_checkin", "content": {"question": "How aware are you of the true cost of addiction today?"}}, {"type": "daily_action", "content": {"title": "Count the Cost Honestly", "action": "Spend a few quiet moments in prayer or personal reflection according to your faith.\n\nWrite down the three greatest losses your addiction has caused.\n\nThen write one practical action you can take today to begin rebuilding one of those areas of your life."}}, {"type": "mentor_note", "content": {"note": "Healing becomes more meaningful when we stop focusing on what addiction promised and begin thinking about what it has actually taken from us.\n\nHonesty gives purpose to recovery."}}, {"type": "quiz", "content": {"question": "According to this lesson, the cost of addiction includes:", "options": [{"text": "Only financial loss.", "is_correct": false}, {"text": "Many forms of loss affect every area of life.", "is_correct": true}, {"text": "Only physical health.", "is_correct": false}, {"text": "Temporary discomfort only.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Honestly recognizing the full cost of addiction can strengthen recovery.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "Why is it important to count the cost honestly?", "options": [{"text": "To create shame.", "is_correct": false}, {"text": "To clearly understand what addiction has been taking from your life.", "is_correct": true}, {"text": "To compare yourself with others.", "is_correct": false}, {"text": "To avoid responsibility.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 7.", "encouragement": "Today you learned that addiction always carries a cost, even when those consequences are delayed or difficult to see at first. By honestly recognizing what addiction has taken from your life, you strengthen your motivation to pursue lasting healing. Every healthy decision you make is an investment in rebuilding what has been damaged and moving toward a future marked by hope, freedom, and the guidance of your faith.\n\nIn the next lesson, we will focus on recognizing where you are in your recovery journey and how honest self-awareness helps you take the right next step toward lasting change."}}]}, {"number": 8, "title": "Recognizing Where You Are", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Honest Self-Awareness Is the Beginning of Lasting Change", "message": "Recovery becomes much clearer when we in honesty recognize where we are.\n\nMany people speak about addiction in general terms while avoiding an honest assessment of their own situation.\n\nWisdom begins with the humility to accept the truth. We cannot move forward effectively until we are willing to see our current reality without denial, exaggeration, or less shame.\n\nThis lesson will help you honestly identify where you are in your recovery journey so you can take the next step with clarity and purpose."}}, {"type": "reading", "content": {"title": "You Can Only Respond to What You Are Willing to Recognize", "body": "Every person experiences recovery differently.\n\nSome people are still struggling with experimentation.\n\nOthers have developed strong habits.\n\nSome are facing dependency, loss of control, or the growing consequences of addiction.\n\nRecognizing your current stage is not about labeling yourself.\n\nIt is about understanding your reality.\n\nMany faith traditions teach that truth leads to wisdom and growth.\n\nRecovery becomes stronger when we stop speaking vaguely about our struggles and begin saying:\n\nThis is where I am.\n\nThis is what I am facing.\n\nThis is what needs to change.\n\nThis is the next healthy step I need to take.\n\nClear self-awareness removes confusion.\n\nIt also helps you recognize what kind of support, accountability, boundaries, and daily practices you need right now and what to put in place.\n\nYou do not need to compare your journey with anyone else''s.\n\nYou only need to honestly recognize your own.\n\nHonesty is not failure.\n\nIt is the foundation of meaningful progress.\n\nReflection Question:\n\nWhere do you believe you are in your recovery journey today?"}}, {"type": "mentor_note", "content": {"note": "Honesty about where you are today creates direction for where you can go tomorrow."}}, {"type": "video", "content": {"title": "Recognizing Where You Are", "description": "A mentor-led explanation of how honest self-awareness helps identify your current stage of recovery and why clarity is essential for lasting healing."}}, {"type": "pause_reflect", "content": {"question": "Looking back through this chapter, which stage best describes your current situation?", "context": "Think honestly about:\n\nCuriosity.\n\nHabit formation.\n\nDependency.\n\nEscalation.\n\nLoss of control.\n\nRebuilding recovery.\n\nDo not minimize your situation.\n\nDo not exaggerate it.\n\nSimply tell yourself the truth."}}, {"type": "journal_prompt", "content": {"prompt": "Complete the following sentence:\n\n\"The stage that best describes my recovery today is...\"\n\nThen describe:\n\nWhy did you recognize that stage.\n\nWhat changes you know are necessary.\n\nOne healthy step you are ready to begin taking today."}}, {"type": "mood_checkin", "content": {"question": "How clear do you feel about your current stage of recovery today?"}}, {"type": "daily_action", "content": {"title": "Locate Yourself Honestly", "action": "Spend a few quiet moments in prayer or personal reflection according to your faith.\n\nDescribe your current stage in simple, honest language.\n\nThen identify one practical action that matches where you are today and supports your continued healing."}}, {"type": "mentor_note", "content": {"note": "New beginnings develop when confusion ends.\n\nThe more honestly you understand your present reality, the more confidently you can move toward a satisfying life and future."}}, {"type": "quiz", "content": {"question": "According to this lesson, what is the purpose of recognizing your current stage?", "options": [{"text": "To shame yourself.", "is_correct": false}, {"text": "To honestly identify where you are so you can respond wisely.", "is_correct": true}, {"text": "To compare yourself with others.", "is_correct": false}, {"text": "To avoid thinking about recovery.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Honest self-awareness helps identify the support and actions needed for recovery.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What does honest self-awareness help overcome?", "options": [{"text": "Confusion and uncertainty.", "is_correct": true}, {"text": "Personal responsibility.", "is_correct": false}, {"text": "The need for support.", "is_correct": false}, {"text": "The recovery process itself.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 8.", "encouragement": "Today you learned that lasting recovery begins with honest self-awareness. By recognizing your current stage without shame or denial, you create a clear starting point for meaningful growth. Every truthful assessment strengthens your ability to make wise decisions, seek the right support, and continue building a healthier future through the guidance of your faith.\n\nIn the final lesson of this chapter, we will explore The Path Toward Freedom and discover how hope, truth, supportive relationships, and consistent daily choices work together to help build lasting recovery."}}]}, {"number": 9, "title": "The Path Toward Freedom", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "No Stage of Addiction Is Beyond Hope", "message": "This chapter has shown that addiction develops gradually through curiosity, habit, dependency, loss of control, and increasing consequences.\n\nBut the journey does not have to end there.\n\nFaith teaches that no matter how deeply a person has struggled, there is always a path toward healing, restoration, and freedom.\n\nRecovery is possible when truth is embraced, support is accepted, and healthier patterns begin replacing destructive ones.\n\nThis lesson brings the chapter to a close by focusing on hope and the practical steps that lead toward lasting freedom."}}, {"type": "reading", "content": {"title": "The Path Toward Freedom Begins with Truth and Continues Through Daily Choices", "body": "Freedom is rarely achieved through one single moment.\n\nIt is built through consistent, intentional choices made day after day.\n\nLasting transformation grows through honesty, humility, perseverance, and a willingness to follow a deserving path in life.\n\nThe journey toward freedom often includes:\n\nHonestly acknowledging the addiction.\n\nAccepting personal responsibility.\n\nSeeking support from trusted people.\n\nEstablishing healthy boundaries.\n\nRenewing unhealthy patterns of thinking.\n\nGrowing through the practices of your faith.\n\nBuilding daily habits that strengthen healing instead of addiction.\n\nRecovery does not require perfection.\n\nIt requires persistence.\n\nThere may still be difficult days.\n\nThere may still be moments of temptation.\n\nBut each healthy choice weakens the old pattern and strengthens the new one.\n\nFreedom grows as truth becomes a daily practice rather than a single decision.\n\nHealing is not about pretending the struggle never existed.\n\nIt is about choosing, each day, to move toward the life your faith calls you to live.\n\nReflection Question:\n\nWhat is the next truthful step you need to take on your journey toward freedom?"}}, {"type": "mentor_note", "content": {"note": "Hope becomes real when it is joined with honest and positive action."}}, {"type": "video", "content": {"title": "The Path Toward Freedom", "description": "A mentor-led explanation of how truth, personal responsibility, healthy support, spiritual growth, and consistent daily choices work together to build lasting freedom from addiction."}}, {"type": "pause_reflect", "content": {"question": "What part of your recovery needs the most attention right now?", "context": "Reflect on whether you need:\n\nGreater honesty.\n\nStronger boundaries.\n\nHealthy support.\n\nDaily structure.\n\nSpiritual growth.\n\nAccountability.\n\nCourage.\n\nPerseverance.\n\nWhich one stands out most today?"}}, {"type": "journal_prompt", "content": {"prompt": "Write one paragraph describing what your path toward freedom looks like from today onward.\n\nInclude:\n\nThe next healthy step you will take.\n\nThe support you will rely on.\n\nThe habits you want to strengthen.\n\nHow your faith will guide your recovery moving forward."}}, {"type": "mood_checkin", "content": {"question": "How hopeful do you feel about continuing your recovery journey today?"}}, {"type": "daily_action", "content": {"title": "Take One Step Toward Freedom", "action": "Spend a few quiet moments in prayer or personal reflection according to your faith.\n\nChoose one practical action you can take today that moves you away from addiction and toward healing.\n\nCommit to completing that action before the day ends."}}, {"type": "mentor_note", "content": {"note": "Freedom is built one truthful decision at a time.\n\nEvery healthy choice strengthens your future and weakens the influence of addiction."}}, {"type": "quiz", "content": {"question": "According to this lesson, lasting freedom is built through:", "options": [{"text": "Waiting for motivation.", "is_correct": false}, {"text": "Truth, healthy support, spiritual growth, and consistent daily choices.", "is_correct": true}, {"text": "Ignoring the past.", "is_correct": false}, {"text": "Hoping the addiction disappears on its own.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Recovery requires perfection before lasting freedom is possible.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What helps make hope a reality?", "options": [{"text": "Passive wishing.", "is_correct": false}, {"text": "Honest action combined with faith and perseverance.", "is_correct": true}, {"text": "Keeping struggles hidden.", "is_correct": false}, {"text": "Avoiding responsibility.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 9.", "encouragement": "You have now completed Chapter 5: The Three Stages of Drug Abuse. Throughout this chapter, you learned how addiction develops gradually, how it progresses over time, and how honest self-awareness can help you recognize where you are today.\n\nMost importantly, you have discovered that no stage of addiction has to be the end of your story. Lasting recovery is built through truth, responsibility, healthy relationships, spiritual growth, and consistent daily choices. Every step you take toward healing strengthens your freedom and brings you closer to the life your faith calls you to live.\n\nIn Chapter 6, we will explore Perception, Deception, Shame, and Spiritual Blindness, helping you understand how unhealthy beliefs and distorted thinking can keep addiction hidden, and how truth brings clarity, healing, and lasting transformation."}}]}]}, {"number": 6, "title": "Perception, Deception, Shame, and Spiritual Blindness", "description": "Chapter 6 explores how addiction affects the way people think, interpret reality, and respond to life. It examines spiritual awareness, distorted perception, deception, shame, fear, guilt, condemnation, spiritual blindness, and the restoration of clear thinking through the wisdom and truth found within one''s faith.\n\nThe goal of this chapter is to help you recognize how drug abuse and addiction can distort your perspective, identify unhealthy beliefs that keep destructive addiction alive, and develop greater spiritual awareness. As you learn to replace distorted thinking with truth, honesty, and the guidance of your faith, you build a stronger foundation for complete healing and recovery.", "lessons": [{"number": 1, "title": "Spiritual Awareness and Influence", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Not Every Struggle Is Only Physical or Emotional", "message": "Recovery involves more than changing behaviors.\n\nMany faith traditions teach that our thoughts, choices, and actions are influenced not only by physical and emotional factors, but also by our spiritual lives.\n\nDeveloping spiritual awareness helps us recognize the deeper influences affecting our decisions, relationships, temptations, and recovery journey.\n\nThis lesson introduces the importance of spiritual awareness and how it can strengthen complete healing."}}, {"type": "reading", "content": {"title": "Spiritual Awareness Helps You Recognize the Deeper Battle", "body": "Spiritual awareness is not about becoming fearful or imagining problems that are not there.\n\nIt is about becoming more attentive to the deeper influences shaping your life.\n\nIt is a reality that people experience ongoing inner struggles involving truth and deception, hope and despair, wisdom and temptation.\n\nWith drug abuse and addiction, these influences often appear through:\n\nRepeated unhealthy thoughts.\n\nPersistent temptation.\n\nShame.\n\nConfusion.\n\nDiscouragement.\n\nFear.\n\nSelf-condemnation.\n\nDistorted beliefs.\n\nWithout spiritual awareness, people may be much more susceptible to just believe any thought coming into their minds and believe anything people tell them without discernment.\n\nRecovery becomes well defined and clearer when we learn to pause and ask:\n\nIs this thought leading me toward healing and freeom?\n\nDoes this choice align with the values of my faith?\n\nIs this drawing me closer to truth, peace, and wisdom, or further away?\n\nSpiritual awareness helps us move beyond reacting automatically.\n\nIt teaches us to respond thoughtfully, honestly, and intentionally.\n\nThe more spiritually aware we become, the better prepared we are to recognize unhealthy influences before they become unhealthy choices.\n\nReflection Question:\n\nWhere do you notice the greatest inner struggle in your recovery today?"}}, {"type": "mentor_note", "content": {"note": "You cannot respond wisely to influences you have never learned to recognize spiritually."}}, {"type": "video", "content": {"title": "Spiritual Awareness and Influence", "description": "A mentor-led introduction to spiritual awareness, exploring how deeper influences shape thoughts, temptations, and choices, and how greater awareness strengthens lasting recovery."}}, {"type": "pause_reflect", "content": {"question": "Think about your recent struggles.", "context": "Have you noticed repeated:\n\nNegative thoughts?\n\nTemptations?\n\nFeelings of shame?\n\nConfusion?\n\nFear?\n\nDiscouragement?\n\nInner conflict?\n\nWhich of these has influenced you most?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about one area where you now believe your struggle involves more than habit alone, and actually needs an advantage of spiritual perception .\n\nDescribe how becoming more spiritually aware may help you respond differently in the future."}}, {"type": "mood_checkin", "content": {"question": "How spiritually aware do you feel today?"}}, {"type": "daily_action", "content": {"title": "Pause Before Reacting", "action": "At least once today, pause before responding to a difficult situation.\n\nSpend a few quiet moments in prayer or personal reflection according to your faith.\n\nAsk yourself what deeper influence may be shaping your thoughts or reactions before deciding how to respond."}}, {"type": "mentor_note", "content": {"note": "Spiritual awareness is not about fear.\n\nIt is about learning to see more clearly so you can choose more wisely."}}, {"type": "quiz", "content": {"question": "According to this lesson, spiritual awareness helps us:", "options": [{"text": "Ignore deeper influences.", "is_correct": false}, {"text": "Recognize the deeper influences shaping our choices.", "is_correct": true}, {"text": "Avoid personal responsibility.", "is_correct": false}, {"text": "Focus only on physical recovery.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Recovery may involve emotional, physical, and spiritual challenges.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What strengthens spiritual awareness?", "options": [{"text": "Automatically believing every thought.", "is_correct": false}, {"text": "Thoughtful reflection guided by the values of your faith.", "is_correct": true}, {"text": "Ignoring inner struggles.", "is_correct": false}, {"text": "Acting on every impulse.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 1.", "encouragement": "Today you learned that recovery involves more than changing outward behavior. Developing spiritual awareness helps you recognize the deeper influences affecting your thoughts, emotions, and choices. As you continue growing in wisdom and allowing your faith to guide your perspective, you strengthen your ability to respond with truth, clarity, and lasting hope.\n\nIn the next lesson, we will explore how addiction can gradually distort perception and discover why learning to see reality clearly is an essential part of lasting recovery."}}]}, {"number": 2, "title": "How Addiction Distorts Perception", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Addiction Changes Not Only Behavior, but Also the Way We See", "message": "One reason drug addiction is so difficult to overcome is that it gradually changes the way we interpret reality.\n\nOver time, people may begin viewing life through cravings, fear, shame, emotional pain, or unhealthy beliefs instead of through truth and wisdom.\n\nA clear perception is essential for making healthy choices. When our perspective becomes distorted, harmful decisions can begin to seem reasonable or even necessary.\n\nThis lesson explores how addiction affects perception and why restoring clear thinking is an important part of lasting recovery."}}, {"type": "reading", "content": {"title": "Distorted Perception Makes Harmful Choices Seem Reasonable", "body": "Addiction does not only affect behavior.\n\nIt also changes how people interpret situations, relationships, and consequences.\n\nAs addiction progresses, a person may begin to:\n\nUnderestimate danger.\n\nOverestimate their ability to stay in control.\n\nMinimize the consequences of their actions.\n\nDistrust people who genuinely want to help.\n\nBelieve temporary relief is more valuable than long-term healing.\n\nJustify choices they once knew were harmful.\n\nOver time, destructive behavior can begin to feel normal.\n\nHealthy boundaries may seem restrictive.\n\nLoving corrections may feel like criticism.\n\nWise advice may be ignored because addiction has reshaped the person''s perspective and perception.\n\nPerception of the truth restores clarity.\n\nRecovery becomes stronger when we learn to question distorted thinking instead of automatically accepting it.\n\nRather than asking,\n\n\"How do I justify this choice?\"\n\nwe begin asking,\n\n\"Am I seeing this situation clearly, or has addiction distorted my perspective?\"\n\nA good perception of the truth replaces distortion, healthier choices become easier to recognize.\n\nReflection Question:\n\nLooking back, where has addiction most changed the way you viewed yourself, other people, or your situation?"}}, {"type": "mentor_note", "content": {"note": "What we repeatedly feed will eventually begin shaping the way we see the world."}}, {"type": "video", "content": {"title": "How Addiction Distorts Perception", "description": "A mentor-led explanation of how addiction gradually changes perception, why harmful choices begin to seem reasonable, and how truth restores clear thinking during recovery."}}, {"type": "pause_reflect", "content": {"question": "Where do you believe your thinking has been most distorted?", "context": "Reflect on how you viewed:\n\nYour addiction.\n\nYourself.\n\nOther people.\n\nConsequences.\n\nSupport.\n\nYour future.\n\nWhich area has changed the most?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about one time you now recognize that addiction distorted the way you interpreted a situation.\n\nDescribe:\n\nWhat you believed at the time.\n\nWhat you understand differently now.\n\nHow clearer thinking could have changed your decision."}}, {"type": "mood_checkin", "content": {"question": "How clear or clouded does your thinking feel today?"}}, {"type": "daily_action", "content": {"title": "Challenge One Distorted Thought", "action": "Today, notice one conclusion you are tempted to accept automatically.\n\nPause before believing it.\n\nSpend a few quiet moments in prayer or personal reflection according to your faith.\n\nAsk yourself whether that thought is based on truth, or whether it has been shaped by fear, shame, craving, or unhealthy thinking."}}, {"type": "mentor_note", "content": {"note": "Recovery often begins when we admit we have not always been seeing things clearly.\n\nTruth restores the vision that addiction gradually distorted."}}, {"type": "quiz", "content": {"question": "According to this lesson, distorted perception often:", "options": [{"text": "Makes harmful choices seem reasonable.", "is_correct": true}, {"text": "Makes danger easier to recognize.", "is_correct": false}, {"text": "Removes temptation.", "is_correct": false}, {"text": "Guarantees recovery.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Clear perception is important for lasting recovery.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What helps restore healthy perception?", "options": [{"text": "Ignoring unhealthy thinking.", "is_correct": false}, {"text": "Truth, honest self-reflection, and the guidance of your faith.", "is_correct": true}, {"text": "More denial.", "is_correct": false}, {"text": "Acting on every craving.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 2.", "encouragement": "Today you learned that addiction affects more than behavior—it can also distort the way you see yourself, others, and the choices before you. As you continue replacing distorted thinking with truth, honest self-reflection, and the guidance of your faith, you strengthen your ability to make wise decisions and continue building lasting recovery.\n\nIn the next lesson, we will explore the nature of deception and discover how false beliefs quietly protect addiction until they are exposed by truth."}}]}, {"number": 3, "title": "The Nature of Deception", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Deception Is Most Powerful When It Feels Like the Truth", "message": "People rarely choose harmful paths because they clearly see them as harmful.\n\nInstead, destructive choices are often disguised, justified, minimized, or made to appear reasonable.\n\nDeception quietly influences the hea,rt and mind by making falsehood seem believable and harmful choices seem acceptable.\n\nThis lesson explores how deception operates in addiction and why recognizing it is essential for lasting recovery."}}, {"type": "reading", "content": {"title": "Deception Changes the Story Before It Changes the Behavior", "body": "Deception rarely begins with obvious lies.\n\nInstead, it often starts with small thoughts that gradually reshape the way we interpret reality.\n\nCommon deceptive thoughts include:\n\n\"I can stop whenever I want.\"\n\n\"One more time won''t matter.\"\n\n\"No one will ever know.\"\n\n\"I''ve already gone too far to change.\"\n\n\"I deserve this.\"\n\n\"Recovery can wait until tomorrow.\"\n\nWhen these thoughts go unchallenged, they slowly become beliefs.\n\nThose beliefs influence decisions, and those decisions strengthen addiction.\n\nA good understanding of the truth exposes deception and restores wisdom.\n\nRecovery becomes stronger when we learn to pause and ask:\n\nIs this thought based on truth?\n\nIs it helping me move toward healing?\n\nOr is it quietly protecting a harmful pattern?\n\nLasting change requires more than good intentions.\n\nIt requires the courage to examine our thoughts honestly and replace false beliefs with truth.\n\nThe more clearly deception is recognized, the less power it has to influence our lives.\n\nReflection Question:\n\nWhat belief or excuse has most often kept you trapped in unhealthy patterns?"}}, {"type": "mentor_note", "content": {"note": "A lie remains powerful only while it is accepted as truth."}}, {"type": "video", "content": {"title": "The Nature of Deception", "description": "A mentor-led explanation of how deception disguises harmful choices, strengthens addiction, and why applying truth is essential for lasting recovery."}}, {"type": "pause_reflect", "content": {"question": "Think about one belief that repeatedly weakened your recovery.", "context": "Ask yourself:\n\nWhere did this belief come from?\n\nHas it led you toward healing or further struggle?\n\nWhat truth from your faith challenges it?"}}, {"type": "journal_prompt", "content": {"prompt": "Write down one unhealthy belief that has influenced your choices.\n\nThen write one truthful statement that directly challenges it.\n\nDescribe how believing that truth could change your future decisions."}}, {"type": "mood_checkin", "content": {"question": "How alert are you to deceptive thoughts today?"}}, {"type": "daily_action", "content": {"title": "Expose One False Belief", "action": "Today, identify one recurring thought that has repeatedly justified bad choices.\n\nSpend a few quiet moments in prayer or personal reflection according to your faith.\n\nReplace that thought with one truthful statement, and repeat it whenever the old belief returns."}}, {"type": "mentor_note", "content": {"note": "Truth becomes powerful when it is practiced, not just theoretical.\n\nEvery false belief you challenge weakens the influence of addiction."}}, {"type": "quiz", "content": {"question": "According to this lesson, deception often:", "options": [{"text": "Makes harmful choices seem reasonable.", "is_correct": true}, {"text": "Makes every decision easier.", "is_correct": false}, {"text": "Removes temptation completely.", "is_correct": false}, {"text": "Guarantees recovery.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Recovery requires actively challenging deceptive thoughts with truth.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What helps weaken deception?", "options": [{"text": "Ignoring unhealthy thoughts.", "is_correct": false}, {"text": "Applying well perceived truth to false beliefs.", "is_correct": true}, {"text": "Keeping struggles hidden.", "is_correct": false}, {"text": "Avoiding self-reflection.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 3.", "encouragement": "Today you learned that deception often begins by changing the way we think before it changes the way we behave. As you continue identifying unhealthy beliefs and replacing them with truth, you strengthen your ability to recognize temptation, make wiser decisions, and continue building lasting recovery through the guidance of your faith.\n\nIn the next lesson, we will explore the difference between shame, fear, and guilt, and discover how understanding these experiences can help break the cycle of addiction and support deeper healing."}}]}, {"number": 4, "title": "Shame, Fear, and Guilt", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Shame, Fear, and Guilt Can Keep Recovery Stuck When They Are Not Understood", "message": "Many people experience shame, fear, and guilt during addiction, but these experiences are not the same.\n\nEach one influences the way we think, feel, and respond to our struggles.\n\nTraining to understand these inner experiences properly helps us respond with greater wisdom, honesty, and hope.\n\nThis lesson explores the differences between shame, fear, and guilt, and how recognizing them clearly supports lasting recovery."}}, {"type": "reading", "content": {"title": "Understanding These Inner Struggles Helps Break Their Influence", "body": "Although shame, fear, and guilt are closely connected, they affect us in different ways.\n\nGuilt reminds us that something we have done needs to be acknowledged, corrected, or made right.\n\nShame goes further.\n\nInstead of focusing on behavior, it attacks our identity by convincing us that we are beyond hope, beyond forgiveness, or beyond change.\n\nFear often tells us that honesty will make things worse, that asking for help is dangerous, or that recovery is impossible.\n\nTogether these three experiences can create a powerful cycle.\n\nGuilt remains unresolved.\n\nShame convinces us we are the problem and create problems.\n\nFear keeps us silent.\n\nSilence allows addiction to continue.\n\nHealing begins when these inner struggles are brought into the light so that we can clearly see what needs to be done and how it has to be done to work on the inner struggles.\n\nRecovery grows stronger when we stop allowing shame, fear, or unresolved guilt to control our decisions.\n\nUnderstanding these experiences clearly helps us respond with wisdom instead of remaining trapped by them.\n\nReflection Question:\n\nWhich has had the greatest influence over your recovery: shame, fear, or guilt?"}}, {"type": "mentor_note", "content": {"note": "What is understood clearly loses much of the power it once held in silence."}}, {"type": "video", "content": {"title": "Shame, Fear, and Guilt", "description": "A mentor-led explanation of the differences between shame, fear, and guilt, and how recognizing each one clearly helps strengthen recovery and lasting healing."}}, {"type": "pause_reflect", "content": {"question": "Which of these has influenced your life most strongly?", "context": "Think about:\n\nShame about who you believe you are.\n\nFear of change or asking for help.\n\nGuilt about past choices.\n\nHow has each one affected your recovery journey?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about one experience where shame, fear, or guilt influenced your choices.\n\nThen answer:\n\nHow did it affect your thinking?\n\nHow did it affect your behavior?\n\nWhat truth from your faith helps you respond differently today?"}}, {"type": "mood_checkin", "content": {"question": "Which of these feels strongest in your life today: shame, fear, or guilt?"}}, {"type": "daily_action", "content": {"title": "Name What Has Been Holding You Back", "action": "Spend a few quiet moments in prayer or personal reflection according to your faith.\n\nIdentify whether shame, fear, or guilt has been influencing you most.\n\nName it honestly.\n\nThen ask for wisdom, healing, courage, and strength to respond with truth instead of remaining trapped in silence."}}, {"type": "mentor_note", "content": {"note": "What is brought into the light can begin to heal.\n\nSilence protects unhealthy patterns.\n\nTruth begins breaking them."}}, {"type": "quiz", "content": {"question": "According to this lesson, shame often says:", "options": [{"text": "Something needs to be corrected.", "is_correct": false}, {"text": "You are beyond hope or beyond change.", "is_correct": true}, {"text": "Ask for help immediately.", "is_correct": false}, {"text": "Everything is already healed.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Fear can prevent people from seeking honest help.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What helps weaken shame, fear, and guilt?", "options": [{"text": "Keeping them hidden.", "is_correct": false}, {"text": "Naming them honestly and responding with truth.", "is_correct": true}, {"text": "Pretending they do not exist.", "is_correct": false}, {"text": "Isolating yourself from others.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 4.", "encouragement": "Today you learned that shame, fear, and guilt are different experiences, each affecting recovery in unique ways. By recognizing them honestly and responding with truth, compassion, and the guidance of your faith, you reduce their influence and create space for deeper healing. As you continue your recovery journey, remember that honest awareness is not a sign of failure—it is one of the foundations of lasting freedom.\n\nIn the next lesson, we will explore The Voice of Condemnation and learn how to distinguish destructive self-condemnation from the kind of conviction that leads to healing and positive change."}}]}, {"number": 5, "title": "The Voice of Condemnation", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Condemnation Attacks Your Identity Instead of Helping You Change", "message": "There is an important difference between recognizing that something needs to change and believing that you are beyond hope.\n\nHealthy conviction can encourage growth, while condemnation attacks a person''s identity and convinces them that change is impossible.\n\nThis lesson will help you recognize the voice of condemnation and learn how to respond with positive living energy, hope, and the guidance of your faith."}}, {"type": "reading", "content": {"title": "Condemnation Does Not Heal. It Keeps People Trapped.", "body": "Condemnation speaks in absolute and hopeless terms.\n\nIt often sounds like:\n\n\"I will never change.\"\n\n\"I have already failed too many times.\"\n\n\"There is no point trying again.\"\n\n\"I am beyond forgiveness.\"\n\n\"This is simply who I am.\"\n\nThese thoughts do not encourage healing.\n\nInstead, they create hopelessness, isolation, shame, and the belief that recovery is no longer possible especially with full blown drug addiction.\n\nThere is a massive difference between condemnation and the concept of healthy conviction.\n\nHealthy conviction identifies behaviors that need to change and encourages humility and honest intentions.\n\nCondemnation attacks your worth and tells you that change is pointless.\n\nRecovery becomes stronger when we learn to recognize this difference.\n\nWhen a thought leads us toward despair, hopelessness, or giving up, it deserves to be questioned.\n\nWhen a thought encourages honesty, responsibility, healing, and positive action, it supports recovery.\n\nLearning to separate condemnation from healthy conviction helps us respond with wisdom rather than remaining trapped by hopelessness.\n\nReflection Question:\n\nWhat condemning message have you believed most often during your recovery?"}}, {"type": "mentor_note", "content": {"note": "A voice that destroys hope is different from one that encourages growth."}}, {"type": "video", "content": {"title": "The Voice of Condemnation", "description": "A mentor-led explanation of the difference between condemnation and healthy conviction, and how recognizing this difference strengthens lasting recovery."}}, {"type": "pause_reflect", "content": {"question": "What harsh message do you repeat to yourself most often?", "context": "Think about thoughts such as:\n\n\"I''ll never change.\"\n\n\"I''m beyond help.\"\n\n\"I''ve already failed.\"\n\n\"There''s no point trying.\"\n\nThen ask yourself:\n\nDoes this thought encourage healing, or does it only lead to despair?"}}, {"type": "journal_prompt", "content": {"prompt": "Write one condemning thought that has influenced your recovery.\n\nThen write:\n\nWhy do you now recognize it as condemnation.\n\nOne healthier truth that challenges it.\n\nHow believing that truth could change your choices moving forward."}}, {"type": "mood_checkin", "content": {"question": "How strong does the voice of condemnation feel in your life today?"}}, {"type": "daily_action", "content": {"title": "Replace Condemnation with Truth", "action": "Spend a few quiet moments in prayer or personal reflection according to your faith.\n\nChoose one condemning message you often believe.\n\nReplace it with one truthful statement that encourages healing, responsibility, hope, and growth.\n\nRead that truth whenever the condemning thought returns."}}, {"type": "mentor_note", "content": {"note": "Truth may challenge you, but it never tells you that healing is impossible.\n\nHope grows stronger each time condemnation loses its influence."}}, {"type": "quiz", "content": {"question": "According to this lesson, condemnation:", "options": [{"text": "Encourages healthy growth.", "is_correct": false}, {"text": "Attacks identity and promotes hopelessness.", "is_correct": true}, {"text": "Solves addiction.", "is_correct": false}, {"text": "Strengthens healthy relationships.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Healthy conviction and condemnation are the same thing.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What helps weaken the voice of condemnation?", "options": [{"text": "Accepting every hopeless thought as true.", "is_correct": false}, {"text": "Replacing condemnation with truth, hope, and healthy conviction.", "is_correct": true}, {"text": "Keeping struggles hidden.", "is_correct": false}, {"text": "Giving up after failure.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 5.", "encouragement": "Today you learned that condemnation and healthy conviction are very different. Condemnation attacks your identity and tells you that change is impossible, while healthy conviction encourages honesty, responsibility, and growth. As you continue replacing hopelessness with truth and allowing your faith to guide your recovery, you build a stronger foundation for lasting healing and freedom.\n\nIn the next lesson, we will explore Recognizing Spiritual Blindness and discover how honest self-awareness helps us see what addiction has been hiding so that lasting change can begin."}}]}, {"number": 6, "title": "Recognizing Spiritual Blindness", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Sometimes We Cannot See Clearly Until We Choose to Face the Truth", "message": "One of the greatest challenges in recovery is not a lack of information or knowledge, but a lack of clear vision.\n\nPeople can know facts, theories and truths while still struggling to recognize what those facts truly mean for their lives or even how to implement it. It is very well known within drug abuse and addiction circles in society that you hear people come up with knowledge, wisdom and understanding about life, yet to many it could be a form of delusion. Not that what they are saying is untrue, but just speaking such things in a dark environment might not grow into something substantial. Because of the type of effect that these specific drugs have on the mind and soul of the person, illusion, confusion, obscure vision and the like influence reason, logic and spiritual truths.\n\nSpiritual blindness can prevent us from seeing the seriousness of addiction, the consequences of our choices, or the hope that healing is possible.\n\nThis lesson explores how spiritual blindness develops and how greater honesty opens the door to clearer understanding."}}, {"type": "reading", "content": {"title": "Clear Vision Begins When We Stop Resisting the Truth", "body": "Spiritual blindness is more than simply not knowing something.\n\nIt often appears when we avoid, minimize, or resist truths that are difficult to accept.\n\nIt may show itself through:\n\nDenial.\n\nMaking excuses.\n\nDefensiveness.\n\nSelective honesty.\n\nBlaming others.\n\nIgnoring consequences.\n\nTalking about change without taking action.\n\nMany people know their addiction is harmful, yet continue living as though a change in life is unnecessary.\n\nWisdom begins with humility.\n\nRecovery becomes stronger when we stop protecting harmful patterns and honestly allow truth to reveal where change is needed.\n\nRecognizing spiritual blindness is not about humiliation.\n\nIt is about gaining clearer vision.\n\nThe more honestly we see ourselves, our choices, and our need for healing, the better prepared we become to make meaningful changes.\n\nClear vision may feel uncomfortable at first.\n\nBut it leads toward freedom.\n\nReflection Question:\n\nWhere do you believe you have been least willing to see the truth about your recovery?"}}, {"type": "mentor_note", "content": {"note": "A person can know many facts and still avoid the truth those facts reveal."}}, {"type": "video", "content": {"title": "Recognizing Spiritual Blindness", "description": "A mentor-led explanation of spiritual blindness, denial, and the importance of gaining clearer vision through honesty, humility, and the guidance of your faith."}}, {"type": "pause_reflect", "content": {"question": "Where have you been avoiding the truth?", "context": "Think honestly about:\n\nDenial.\n\nExcuses.\n\nBlaming others.\n\nMinimizing consequences.\n\nDelaying change.\n\nAvoiding accountability.\n\nWhich area needs the greatest honesty today?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about one area where you now realize you have not been seeing your situation clearly.\n\nThen answer:\n\nWhat truth have you been resisting?\n\nWhy has it been difficult to accept?\n\nHow could accepting that truth strengthen your recovery?"}}, {"type": "mood_checkin", "content": {"question": "How open are you to seeing your recovery more clearly today?"}}, {"type": "daily_action", "content": {"title": "Ask for Clearer Vision", "action": "Spend a few quiet moments in prayer or personal reflection according to your faith.\n\nAsk for greater wisdom and clarity in one area where you have struggled to see the truth.\n\nThen write one honest insight that comes to mind and consider one practical step you can take in response."}}, {"type": "mentor_note", "content": {"note": "Clear vision may challenge your comfort, but it also opens the path toward lasting healing."}}, {"type": "quiz", "content": {"question": "According to this lesson, spiritual blindness is:", "options": [{"text": "Only lacking information.", "is_correct": false}, {"text": "Being unwilling or unable to clearly recognize the truth.", "is_correct": true}, {"text": "A permanent condition.", "is_correct": false}, {"text": "Something that affects only other people.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Spiritual blindness can delay meaningful recovery by keeping people from recognizing the truth.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What is the healthiest response to spiritual blindness?", "options": [{"text": "Continue protecting it.", "is_correct": false}, {"text": "Honestly seek clearer vision through truth, humility, and the guidance of your faith.", "is_correct": true}, {"text": "Pretending knowing facts is enough.", "is_correct": false}, {"text": "Avoid self-reflection.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 6.", "encouragement": "Today you learned that spiritual blindness is not simply a lack of knowledge—it is often a reluctance or inability to fully recognize the truth. As you continue choosing honesty, humility, and the guidance of your faith, your perspective becomes clearer, allowing you to make wiser decisions and continue building lasting recovery.\n\nIn the final lesson of this chapter, we will explore Seeing Through the Truth of Your Faith and discover how a truth-centered perspective helps overcome distortion, strengthens hope, and supports lifelong healing."}}]}, {"number": 7, "title": "Seeing Through the Truth of Your Faith", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Recovery Becomes Clearer When We See Life Through Truth", "message": "Throughout this chapter, you have explored spiritual awareness, distorted perception, deception, shame, condemnation, and spiritual blindness.\n\nThe drug abusive journey now ends with a renewed perspective.\n\nTruth does more than provide information—it transforms the way we understand ourselves, our struggles, and our future.\n\nThis lesson explores how seeing life through the truth of your faith strengthens recovery and helps you respond with wisdom, hope, and lasting purpose."}}, {"type": "reading", "content": {"title": "Truth Restores the Way We See Ourselves and Our Recovery", "body": "Addiction often teaches people to interpret life through fear, shame, cravings, and hopelessness.\n\nOver time, these distorted perspectives begin shaping every decision.\n\nLasting healing comes when truth becomes the foundation for how we interpret our lives.\n\nSeeing through the truth of your faith means choosing to view yourself, your struggles, and your future through wisdom rather than deception.\n\nIt reminds us that:\n\nOur struggles are real, but they do not define our identity.\n\nOur past does not determine our future.\n\nHealing may take time, but it remains possible.\n\nTemptation is powerful, but it does not have to control us.\n\nHonest growth is more valuable than pretending to be perfect.\n\nTruth does not remove every challenge.\n\nInstead, it gives us a healthier way to understand those challenges.\n\nAs truth becomes stronger than fear, shame, or deception, recovery becomes more stable.\n\nMany faith traditions encourage us to return to truth each day so that our decisions are guided by wisdom rather than by emotion or unhealthy impulses.\n\nEvery truthful perspective strengthens the foundation for  complete healing and freedom from drug abuse.\n\nReflection Question:\n\nIn what area of your life do you most need the truth of your faith to replace unhealthy thinking?"}}, {"type": "mentor_note", "content": {"note": "A healthy and well defined life often begins with clear vision and holistic perspective."}}, {"type": "video", "content": {"title": "Seeing Through the Truth of Your Faith", "description": "A mentor-led conclusion to the chapter, explaining how the truth of one''s faith restores perspective, strengthens hope, and supports lasting recovery."}}, {"type": "pause_reflect", "content": {"question": "Where do you most need a healthier perspective today?", "context": "Think about:\n\nYour identity.\n\nYour future.\n\nYour recovery.\n\nYour worth.\n\nYour relationships.\n\nYour ability to change.\n\nWhich area needs the guidance of truth most?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about one area where you want to begin seeing your life differently.\n\nThen answer:\n\nWhat unhealthy belief has influenced this area?\n\nWhat truth from your faith challenges that belief?\n\nHow could living according to that truth change your recovery?"}}, {"type": "mood_checkin", "content": {"question": "How grounded do you feel in the truth of your faith today?"}}, {"type": "daily_action", "content": {"title": "Choose the Perspective of Truth", "action": "Spend a few quiet moments in prayer or personal reflection according to your faith.\n\nIdentify one recurring unhealthy thought that has shaped your perspective.\n\nReplace it with one truth that reflects the values and teachings of your faith.\n\nReturn to that truth whenever the unhealthy thought appears today."}}, {"type": "mentor_note", "content": {"note": "Truth does not erase every struggle.\n\nIt prevents struggle from becoming the only story you believe about your life."}}, {"type": "quiz", "content": {"question": "According to this lesson, the truth of your faith:", "options": [{"text": "Only provides information.", "is_correct": false}, {"text": "Restores perspective and guides healthier choices.", "is_correct": true}, {"text": "Removes every difficulty immediately.", "is_correct": false}, {"text": "Makes recovery effortless.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: A truth-centered perspective can weaken the influence of fear, shame, and deception.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What changes when we begin seeing through the truth of our faith?", "options": [{"text": "Distorted thinking loses influence.", "is_correct": true}, {"text": "Shame becomes more accurate.", "is_correct": false}, {"text": "Hope disappears.", "is_correct": false}, {"text": "Recovery becomes unnecessary.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 7.", "encouragement": "You have now completed Chapter 6: Perception, Deception, Shame, and Spiritual Blindness. Throughout this chapter, you learned how drug abuse and addiction can distort the way you see yourself, others, and the world around you. You also discovered that greater spiritual awareness, honest self-reflection, and the truth of your faith can restore clarity, strengthen hope, and support lasting recovery.\n\nAs you continue into Chapter 7, you will explore the relationship between inner conflict, personal responsibility, and obedience to the healthy values of your faith, learning how daily choices shape character, strengthen self-discipline, and build a life marked by wisdom, healing, and lasting freedom."}}]}]}, {"number": 7, "title": "The Two Ways of Living", "description": "Chapter 7 explores the ongoing inner conflict between destructive patterns and the path that leads to healing, freedom, lasting growth and a fulfilling inner life. It helps you understand why this struggle exists, how your daily choices shape your future, and how living according to the values of your faith strengthens recovery.\n\nThe goal of this chapter is to give you a practical framework for understanding inner conflict, making wise decisions, and building a life guided by truth, responsibility, and spiritual growth. As you learn to recognize unhealthy patterns and intentionally choose healthier ones, you develop greater freedom, resilience, and hope.", "lessons": [{"number": 1, "title": "Destructive Patterns and Their Consequences", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Some Patterns Keep Pulling Us Away from the Life We Truly Want", "message": "Recovery often includes an ongoing struggle between old habits and the healthier progressive life we are trying to build.\n\nDestructive patterns and habits do not simply disappear on their own. Left unchallenged, they continue drawing us toward choices and consequences that damage our well-being, relationships, and spiritual growth.\n\nThis lesson introduces these recurring patterns so you can recognize them more clearly and begin responding with real answers rather than confusion."}}, {"type": "reading", "content": {"title": "Destructive Patterns Continue Until They Are Recognized and Interrupted", "body": "Some behaviors become so familiar that they begin to feel normal.\n\nWith addiction, this often appears as repeating the same cycle:\n\nTemptation.\n\nGiving in.\n\nTemporary relief.\n\nRegret.\n\nShame.\n\nPromising to change.\n\nReturning to the same behavior.\n\nMany people genuinely want to change but feel trapped because they keep repeating the same pattern and cycle.\n\nUnderstanding these recurring patterns is an important step toward freedom.\n\nWhen we recognize the cycle honestly, we stop being surprised by it.\n\nInstead of believing we have failed completely, we begin asking:\n\nWhat triggered this pattern?\n\nWhat keeps it repeating?\n\nWhat healthy choice could interrupt it next time?\n\nRecovery becomes stronger when we stop speaking vaguely about our struggles and begin seeing it and identifying it clearly.\n\nJust naming the pattern does not remove responsibility.\n\nIt is building our understanding that helps us make wiser decisions moving forward.\n\nReflection Question:\n\nWhat destructive pattern has repeated most often in your recovery journey?"}}, {"type": "mentor_note", "content": {"note": "Patterns that remain unnamed often remain unchanged."}}, {"type": "video", "content": {"title": "Destructive Patterns and Their Consequences", "description": "A mentor-led introduction to recurring destructive patterns, explaining why they repeat and how recognizing them honestly becomes an important step toward lasting recovery."}}, {"type": "pause_reflect", "content": {"question": "Think about one unhealthy cycle that keeps repeating in your life.", "context": "Reflect on:\n\nWhat usually triggers it?\n\nHow do you respond?\n\nWhat happens afterward?\n\nWhat keeps the cycle going?\n\nWhat do you notice?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about one destructive pattern that has continued repeating.\n\nDescribe:\n\nThe trigger.\n\nThe behavior.\n\nThe consequence.\n\nOne healthier response you could choose next time."}}, {"type": "mood_checkin", "content": {"question": "How aware are you of recurring destructive patterns in your life today?"}}, {"type": "daily_action", "content": {"title": "Identify the Pattern Clearly", "action": "Spend a few quiet moments in prayer or personal reflection according to your faith.\n\nWrite down one recurring destructive cycle from beginning to end.\n\nThen identify one practical step you can take to interrupt that cycle the next time it begins."}}, {"type": "mentor_note", "content": {"note": "Recovery begins gaining strength when recurring patterns are understood instead of ignored.\n\nClarity creates the opportunity for change."}}, {"type": "quiz", "content": {"question": "According to this lesson, why is it important to recognize destructive patterns?", "options": [{"text": "It removes personal responsibility.", "is_correct": false}, {"text": "It helps us understand and identify unhealthy cycles.", "is_correct": true}, {"text": "It guarantees immediate recovery.", "is_correct": false}, {"text": "It proves change is impossible.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Many destructive patterns repeat because they remain unrecognized or unchallenged.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What strengthens recovery according to this lesson?", "options": [{"text": "Ignoring recurring struggles.", "is_correct": false}, {"text": "Honestly identifying destructive patterns and responding with healthier choices.", "is_correct": true}, {"text": "Pretending the problem no longer exists.", "is_correct": false}, {"text": "Waiting for the cycle to stop on its own.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 1.", "encouragement": "Today you learned that recurring destructive patterns often continue until they are honestly recognized and intentionally interrupted. As you grow in self-awareness and allow the guidance of your faith to shape your choices, you become better equipped to break unhealthy cycles and build new patterns that support lasting healing and freedom.\n\nIn the next lesson, we will explore The Path Toward New Life and discover how faith, hope, and intentional daily choices create a stronger foundation for lasting recovery."}}]}, {"number": 2, "title": "The Path Toward New Life", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "No Matter How Long You Have Struggled, A New Direction Is Possible", "message": "Recovery is not only about leaving unhealthy patterns and habits behind.\n\nIt is also about building a new way of living.\n\nPeople should not be defined by their bad past that condemns them. Through faith, personal growth, and intentional choices, it is possible to begin living with renewed purpose, wisdom, and hope.\n\nThis lesson explores how a new direction begins and why lasting recovery is built on more than simply avoiding addiction."}}, {"type": "reading", "content": {"title": "A New Life Is Built One Choice at a Time", "body": "Leaving addiction behind is only part of recovery.\n\nTrue healing also involves recreating healthier patterns and habits, stronger relationships, renewed thinking, and a life guided by the values of your faith.\n\nMany people focus only on what they must stop doing.\n\nBut lasting recovery also asks:\n\nWhat healthy habits will I build?\n\nWhat kind of person am I becoming?\n\nWhat values will guide my decisions?\n\nHow will my faith shape my future?\n\nTransformation is a journey of progress rather than a single event.\n\nGrowth happens gradually through daily acts of honesty, humility, patience, compassion, and perseverance by adding your part to a better society.\n\nRecovery becomes stronger when we focus not only on resisting unhealthy patterns, but also on actively building a life that supports healing.\n\nEach healthy decision strengthens the direction you are choosing.\n\nOver time, those decisions become a new way of living.\n\nReflection Question:\n\nWhat is one area of your life where you can begin building healthier patterns today?"}}, {"type": "mentor_note", "content": {"note": "A healthier future is built through the choices you make today."}}, {"type": "video", "content": {"title": "The Path Toward New Life", "description": "A mentor-led explanation of how lasting recovery is strengthened by building healthy habits, living according to the values of your faith, and choosing a new direction each day."}}, {"type": "pause_reflect", "content": {"question": "Where have you already seen positive change in your recovery?", "context": "Think about:\n\nYour thinking.\n\nYour relationships.\n\nYour daily habits.\n\nYour response to temptation.\n\nYour faith.\n\nYour hope for the future.\n\nWhich change encourages you most?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about one healthy habit or value you want to strengthen.\n\nThen answer:\n\nWhy is this important to your recovery?\n\nWhat practical steps will help you develop it?\n\nHow can your faith help you stay committed to this new direction?"}}, {"type": "mood_checkin", "content": {"question": "How hopeful do you feel about building a healthier future today?"}}, {"type": "daily_action", "content": {"title": "Choose One Healthy Step", "action": "Spend a few quiet moments in prayer or personal reflection according to your faith.\n\nChoose one healthy action that reflects the person you want to become.\n\nCommit to completing that action today, no matter how small it may seem."}}, {"type": "mentor_note", "content": {"note": "Every positive choice moves you further from old patterns and closer to the life you are building."}}, {"type": "quiz", "content": {"question": "According to this lesson, lasting recovery involves:", "options": [{"text": "Only avoiding addiction.", "is_correct": false}, {"text": "Building a positive way of living through intentional daily choices.", "is_correct": true}, {"text": "Waiting for change to happen naturally.", "is_correct": false}, {"text": "Ignoring personal growth.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Recovery is strengthened by building healthy habits and living according to the values of your faith.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What helps build a new life?", "options": [{"text": "Repeating old habits.", "is_correct": false}, {"text": "Consistent healthy choices, personal growth, and faith-guided living.", "is_correct": true}, {"text": "Waiting for perfect circumstances.", "is_correct": false}, {"text": "Avoiding responsibility.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 2.", "encouragement": "Today you learned that recovery is about more than leaving addiction behind—it is about building a positive, more meaningful way of living. Every choice that reflects your values, strengthens your faith, and supports your well-being helps shape the future you are creating. Lasting freedom grows through consistent daily decisions that move you toward hope, healing, and purpose."}}]}, {"number": 3, "title": "Understanding the Inner Conflict", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Inner Conflict Does Not Mean You Are Failing", "message": "Many people become discouraged when they continue experiencing temptation or inner struggle during recovery.\n\nThey assume that if they were truly changing, the conflict would disappear.\n\nInner conflict and difficult situations that are tested and tried is often a natural part of spiritual growth. The struggle itself does not mean you are moving backward—it often means you are learning to understand life in the very moment, in hindsight and future perspective to choose new directions.\n\nThis lesson explores why inner conflict exists and how understanding it helps strengthen lasting recovery."}}, {"type": "reading", "content": {"title": "Growth Often Happens in the Middle of the Struggle", "body": "Recovery can feel like two different directions pulling at the same time.\n\nPart of you may desire healing, peace, and freedom.\n\nAnother part may still be drawn toward familiar habits, temporary relief, or unhealthy patterns.\n\nThis inner conflict can feel exhausting.\n\nHowever, many faith traditions teach that the presence of conflict does not automatically mean failure.\n\nInstead, it often reflects the ongoing choice between old habits and a renewed way of living.\n\nThe important question is not whether conflict exists.\n\nThe important question is:\n\nWhich thoughts are you strengthening?\n\nWhich values are guiding your decisions?\n\nWhich direction are your daily choices supporting?\n\nRecovery becomes stronger when we stop fearing the struggle and start responding to it with wise intent.\n\nEvery time you choose truth over deception, patience over impulse, or healing over temporary relief, you strengthen the purposeful direction you are building.\n\nConflict may continue for a time.\n\nBut each wise decision makes lasting freedom stronger.\n\nReflection Question:\n\nWhere do you experience the greatest inner conflict in your recovery today?"}}, {"type": "mentor_note", "content": {"note": "The presence of conflict does not define your future.\n\nThe direction you choose does."}}, {"type": "video", "content": {"title": "Understanding the Inner Conflict", "description": "A mentor-led explanation of why inner conflict is a normal part of recovery and how responding with wisdom strengthens lasting healing."}}, {"type": "pause_reflect", "content": {"question": "How have you usually interpreted inner conflict?", "context": "Think about whether you have viewed it as:\n\nFailure.\n\nConfusion.\n\nWeakness.\n\nA normal part of growth.\n\nAn opportunity to make healthier choices.\n\nWhich perspective has influenced you most?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about one area where you currently experience strong inner conflict.\n\nThen answer:\n\nWhat negative pattern is pulling you backward?\n\nWhat positive direction are you trying to follow?\n\nWhat practical choice will strengthen that healthier direction today?"}}, {"type": "mood_checkin", "content": {"question": "How steady do you feel when facing inner conflict today?"}}, {"type": "daily_action", "content": {"title": "Respond with Wisdom", "action": "The next time you experience inner conflict today, pause before reacting.\n\nSpend a few quiet moments in prayer or personal reflection according to your faith.\n\nAsk yourself:\n\nWhich choice supports healing?\n\nWhich choice reflects the values of my faith?\n\nWhich decision will I be thankful for tomorrow?\n\nChoose the response that strengthens your recovery."}}, {"type": "mentor_note", "content": {"note": "Inner conflict becomes less discouraging when you understand that you practice better decisions that work in building your life."}}, {"type": "quiz", "content": {"question": "According to this lesson, inner conflict often shows:", "options": [{"text": "That recovery has failed.", "is_correct": false}, {"text": "That old habits and a renewed way of living are competing.", "is_correct": true}, {"text": "That change is impossible.", "is_correct": false}, {"text": "That temptation will never end.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Experiencing inner conflict automatically means nothing is changing.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What matters most during inner conflict?", "options": [{"text": "Pretending the struggle does not exist.", "is_correct": false}, {"text": "Choosing the direction that supports healing and the values of your faith.", "is_correct": true}, {"text": "Waiting for the conflict to disappear.", "is_correct": false}, {"text": "Following whichever feeling is strongest.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 3.", "encouragement": "Today you learned that inner conflict is not a sign of failure—it is often evidence that you are moving away from old patterns and toward a renewed way of living. Every time you choose truth, wisdom, and the guidance of your faith over familiar destructive habits, you strengthen the foundation for lasting recovery.\n\nIn the next lesson, we will explore Self-Centered Living Versus Spirit-Led Living and learn how recognizing the source of our thoughts and desires helps us make wiser, healthier decisions every day."}}]}, {"number": 4, "title": "Self-Centered Living Versus Spirit-Led Living", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Not Every Strong Desire Leads in the Right Direction", "message": "Recovery often requires making choices that go against immediate impulses.\n\nThere is a difference between living according to self-centered desires and living according to the guidance of the Divine and the values of one''s faith.\n\nLearning to recognize this difference helps us deliberately move in the direction of building a life that''s positive and responsible in society.\n\nThis lesson explores how to distinguish between these two ways of living and why that distinction matters in recovery."}}, {"type": "reading", "content": {"title": "Self-Centered Desires Seek Immediate Relief, While Faith-Guided Living Seeks Lasting Growth", "body": "Not every desire should automatically be followed.\n\nSome impulses encourage immediate satisfaction without considering long-term consequences.\n\nThese often lead toward:\n\nImpatience.\n\nSecrecy.\n\nSelf-justification.\n\nTemporary relief.\n\nAvoiding responsibility.\n\nGiving in to unhealthy habits.\n\nThere are teachings that spiritual maturity develops as we learn to pause before acting and allow our decisions to be guided by truth, wisdom, humility, and self-control.\n\nA faith-guided life often encourages:\n\nHonesty.\n\nPatience.\n\nCompassion.\n\nResponsibility.\n\nSelf-discipline.\n\nTrust.\n\nLasting peace.\n\nStrong emotions or powerful desires do not always point us in the right direction.\n\nRecovery becomes stronger when we learn to ask:\n\nDoes this choice reflect the values of my faith?\n\nWill it lead toward healing or temporary relief?\n\nWhat kind of person will this decision help me become?\n\nLearning to test our impulses instead of automatically obeying them strengthens the ability for lasting freedom.\n\nReflection Question:\n\nWhen do you most notice the difference between immediate desire and what you know is the healthier choice?"}}, {"type": "mentor_note", "content": {"note": "The strongest feeling is not always the wisest guide."}}, {"type": "video", "content": {"title": "Self-Centered Living Versus Spirit-Led Living", "description": "A mentor-led explanation of the difference between self-centered desires and faith-guided living, and how learning to recognize that difference strengthens recovery."}}, {"type": "pause_reflect", "content": {"question": "Think about a recent difficult decision.", "context": "Ask yourself:\n\nWas I seeking immediate relief or lasting healing?\n\nWas I protecting myself or acting with honesty?\n\nDid my choice reflect the values of my faith?\n\nWhat do you notice?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about one situation where you followed a bad impulse.\n\nThen describe:\n\nWhat that impulse promised.\n\nWhat actually happened.\n\nHow a faith-guided response could have changed the outcome."}}, {"type": "mood_checkin", "content": {"question": "How aware are you of the difference between unhealthy impulses and faith-guided choices today?"}}, {"type": "daily_action", "content": {"title": "Test One Strong Impulse", "action": "Before acting on one strong feeling today, pause.\n\nSpend a few quiet moments in prayer or personal reflection according to your faith.\n\nAsk yourself:\n\nIs this leading me toward lasting healing?\n\nDoes it reflect the values of my faith?\n\nWill I be grateful for this decision tomorrow?\n\nChoose the response that supports your recovery."}}, {"type": "mentor_note", "content": {"note": "Wisdom grows when we learn to examine our desires before allowing them to guide our actions."}}, {"type": "quiz", "content": {"question": "According to this lesson, self-centered living often focuses on:", "options": [{"text": "Immediate relief without considering long-term consequences.", "is_correct": true}, {"text": "Patience and self-control.", "is_correct": false}, {"text": "Long-term healing.", "is_correct": false}, {"text": "Honest accountability.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Every strong feeling should automatically be followed.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What strengthens lasting recovery?", "options": [{"text": "Acting on every impulse.", "is_correct": false}, {"text": "Testing your desires against truth and the values of your faith.", "is_correct": true}, {"text": "Ignoring consequences.", "is_correct": false}, {"text": "Seeking only immediate comfort.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 4.", "encouragement": "Today you learned that not every strong desire leads in the right direction. Lasting recovery grows as you learn to pause, examine your impulses, and choose the path that reflects truth, wisdom, and the values of your faith. Each decision that places long-term healing above temporary relief strengthens your character and moves you closer to lasting freedom.\n\nIn the next lesson, we will explore Daily Choices and Their Consequences, discovering how the small decisions you make every day quietly shape the future you are building."}}]}, {"number": 5, "title": "Daily Choices and Their Consequences", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Small Daily Choices Shape the Future You Build", "message": "Recovery is rarely transformed by one dramatic moment alone.\n\nIt is built through the small choices you make every day.\n\nFaith traditions teach that consistent daily decisions gradually shape our character, strengthen our values, and influence the direction of our lives.\n\nThis lesson explores how everyday choices quietly create long-term consequences and why small acts of faithfulness are so important in lasting recovery."}}, {"type": "reading", "content": {"title": "The Direction of Your Daily Choices Matters More Than You May Realize", "body": "Every day presents opportunities to make choices.\n\nSome decisions strengthen healing and a renewed life.\n\nOthers reinforce unhealthy patterns.\n\nThese choices may involve:\n\nYour thoughts.\n\nYour honesty.\n\nYour daily routines.\n\nThe people you spend time with.\n\nThe boundaries you keep.\n\nThe media you consume.\n\nHow you respond to temptation.\n\nThe way you practice your faith.\n\nEach decision may seem small on its own.\n\nHowever, repeated choices gradually become habits, and habits shape the direction of your life.\n\nLasting growth is built through consistent faithfulness to the truth in everyday life.\n\nRecovery becomes stronger when we stop waiting for dramatic change and begin respecting the importance of ordinary decisions.\n\nEvery wise choice becomes another step toward freedom.\n\nEvery bad decision strengthens the pattern you are trying to leave behind.\n\nYour future is often shaped by what you choose repeatedly rather than by what you choose occasionally.\n\nReflection Question:\n\nWhich daily choice has the greatest influence on your recovery right now?"}}, {"type": "mentor_note", "content": {"note": "The future is often built through the choices that seem too small to matter today."}}, {"type": "video", "content": {"title": "Daily Choices and Their Consequences", "description": "A mentor-led explanation of how everyday decisions shape long-term recovery and why consistent healthy choices build lasting freedom."}}, {"type": "pause_reflect", "content": {"question": "Think about your daily routines.", "context": "Which small choices most often influence your recovery?\n\nReflect on:\n\nYour morning routine.\n\nYour thought patterns.\n\nYour relationships.\n\nYour boundaries.\n\nYour use of time.\n\nYour response to temptation.\n\nYour spiritual practices.\n\nWhich one has the greatest long-term impact?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about one daily habit you know needs to change.\n\nThen answer:\n\nWhy is this habit important?\n\nWhat consequence does it create over time?\n\nWhat healthier habit can replace it?"}}, {"type": "mood_checkin", "content": {"question": "How intentional have your daily choices been today?"}}, {"type": "daily_action", "content": {"title": "Build One Healthy Habit", "action": "Choose one small action that supports your recovery.\n\nSpend a few quiet moments in prayer or personal reflection according to your faith.\n\nCommit to repeating that action consistently over the next week as a way of strengthening your recovery."}}, {"type": "mentor_note", "content": {"note": "Lasting freedom is often built through small acts of wisdom repeated day after day."}}, {"type": "quiz", "content": {"question": "According to this lesson, long-term consequences usually grow from:", "options": [{"text": "One dramatic event.", "is_correct": false}, {"text": "Repeated daily choices.", "is_correct": true}, {"text": "Luck.", "is_correct": false}, {"text": "Other people''s decisions.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Small daily habits can have a significant impact on long-term recovery.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What helps strengthen lasting recovery?", "options": [{"text": "Ignoring everyday decisions.", "is_correct": false}, {"text": "Building healthy daily habits that reflect the values of your faith.", "is_correct": true}, {"text": "Waiting for major life changes.", "is_correct": false}, {"text": "Hoping unhealthy habits disappear on their own.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 5.", "encouragement": "Today you learned that lasting recovery is built through consistent daily choices rather than occasional moments of determination. Every healthy habit you practice, every wise decision you make, and every action that reflects the values of your faith helps shape a future marked by healing, strength, and forever freedom.\n\nIn the next lesson, we will explore Walking in Obedience to Your Faith and discover how putting truth into practice strengthens recovery and helps transform good intentions into lasting change."}}]}, {"number": 6, "title": "Walking in Obedience to Your Faith", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Living According to Your Faith Is a Daily Choice", "message": "Many people understand what is right but find it difficult to put that understanding into practice.\n\nRecovery becomes stronger when truth is not only believed but actually put into practice.\n\nObedience is not about earning acceptance or proving worth. It is about choosing to live in a way that reflects truth, wisdom, and the values of one''s faith.\n\nThis lesson explores how putting faith into action strengthens recovery and builds lasting freedom."}}, {"type": "reading", "content": {"title": "Obedience Turns Good Intentions into Meaningful Action", "body": "Knowledge alone does not change a life.\n\nReal change happens when what we know and have learned begins shaping our lives visibly.\n\nWalking in obedience means allowing the values of your faith to influence your everyday decisions.\n\nThis may include:\n\nBeing honest, even when it is difficult.\n\nSetting healthy boundaries.\n\nChoosing supportive relationships.\n\nPracticing forgiveness.\n\nTaking responsibility for your actions.\n\nSeeking help when needed.\n\nRemaining committed to healthy routines.\n\nMany people know these things are important.\n\nThe challenge is consistently living them.\n\nSpiritual growth develops through faithful daily practice and discipline.\n\nRecovery becomes stronger when we stop admiring truth from a distance and begin directly applying it to our lives.\n\nObedience is not about perfection.\n\nIt is about consistently choosing the next right step, even when it is uncomfortable.\n\nEach faithful decision strengthens your recovery and helps transform healthy beliefs into healthy habits.\n\nReflection Question:\n\nWhere is there a gap between what you know is right and what you are currently practicing?"}}, {"type": "mentor_note", "content": {"note": "Truth becomes most powerful when it is lived, not simply understood."}}, {"type": "video", "content": {"title": "Walking in Obedience to Your Faith", "description": "A mentor-led explanation of how putting the values of your faith into daily practice strengthens recovery and helps transform healthy intentions into lasting change."}}, {"type": "pause_reflect", "content": {"question": "Think about one area where you know what the healthier choice is.", "context": "Ask yourself:\n\nWhat has been stopping me from acting on it?\n\nWhat would obedience look like in this situation?\n\nWhat small step can I take today?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about one area where you want your actions to better reflect the values of your faith.\n\nThen describe:\n\nWhat you already know to be true.\n\nWhat practical action you need to take.\n\nHow taking that step could strengthen your recovery."}}, {"type": "mood_checkin", "content": {"question": "How willing do you feel to live out the values of your faith today?"}}, {"type": "daily_action", "content": {"title": "Put One Truth into Practice", "action": "Spend a few quiet moments in prayer or personal reflection according to your faith.\n\nChoose one truth you already believe.\n\nThen identify one practical action that puts that truth into practice today, and commit to completing it before the day ends."}}, {"type": "mentor_note", "content": {"note": "A practical understanding of truth changes the mind.\n\nLiving truth changes your life."}}, {"type": "quiz", "content": {"question": "According to this lesson, obedience is:", "options": [{"text": "Simply knowing what is right.", "is_correct": false}, {"text": "Putting the values of your faith into consistent daily practice.", "is_correct": true}, {"text": "Trying to earn acceptance.", "is_correct": false}, {"text": "Avoiding responsibility.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: A person can understand truth without consistently living it.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What strengthens lasting recovery?", "options": [{"text": "Knowing what is right but never acting on it.", "is_correct": false}, {"text": "Consistently putting truth and the values of your faith into practice.", "is_correct": true}, {"text": "Waiting until life becomes easier.", "is_correct": false}, {"text": "Avoiding difficult decisions.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 6.", "encouragement": "Today you learned that lasting recovery grows when truth becomes action. Every time you choose honesty, responsibility, healthy boundaries, and the values of your faith, you strengthen your recovery and build a life marked by wisdom, integrity, and lasting freedom.\n\nIn the final lesson of this chapter, we will explore Living with Grace and Hope, discovering how compassion, perseverance, and the guidance of your faith help you continue moving forward, even when recovery is challenging."}}]}, {"number": 7, "title": "Living with Grace and Hope", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Lasting Recovery Is Sustained by Grace, Hope, and Perseverance", "message": "Recovery is not about never making another mistake.\n\nIt is about continuing to move forward with honesty, humility, and hope even after you stumble.\n\nGrace is not permission to continue harmful behavior. Instead, grace is the power that  transmits compassion, mercy, and strength that help us continue growing even after failure.\n\nThis lesson concludes the chapter by exploring how grace and hope work together to strengthen lasting recovery."}}, {"type": "reading", "content": {"title": "Grace Encourages Growth While Hope Keeps You Moving Forward", "body": "Recovery can become unbalanced in two different ways.\n\nSome people become overwhelmed by failure and believe they no longer deserve a better life.\n\nOthers begin treating compassion as permission to stop growing or ignore unhealthy choices.\n\nTrue grace does neither.\n\nGrace reminds us that failure does not have to define our future.\n\nAt the same time, it calls us to continue pursuing truth, responsibility, and personal growth.\n\nLiving with grace means:\n\nAccepting compassion without abandoning responsibility.\n\nLearning from mistakes instead of becoming trapped by them.\n\nContinuing to grow after setbacks.\n\nShowing yourself and others patience while remaining committed to change.\n\nTrusting that healing remains possible through faith, perseverance, and wise choices.\n\nHope grows when we remember that recovery is a journey and understanding.\n\nProgress may be gradual.\n\nThere may be setbacks.\n\nBut every decision to return to the path of healing strengthens your future.\n\nGrace encourages you to keep walking.\n\nHope reminds you why the journey is worthwhile.\n\nReflection Question:\n\nHow can you respond with both grace and responsibility when you experience setbacks in recovery?"}}, {"type": "mentor_note", "content": {"note": "Hope grows strongest when compassion and responsibility walk together."}}, {"type": "video", "content": {"title": "Living with Grace and Hope", "description": "A mentor-led conclusion to the chapter, explaining how grace, hope, perseverance, and the values of your faith work together to sustain lasting recovery."}}, {"type": "pause_reflect", "content": {"question": "When you make a mistake, how do you usually respond?", "context": "Reflect on whether you tend to:\n\nBecome discouraged.\n\nJudge yourself harshly.\n\nIgnore the problem.\n\nLearn from the experience.\n\nReturn to your recovery with renewed commitment.\n\nWhich response is most familiar to you?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about a setback you have experienced during your recovery.\n\nThen answer:\n\nWhat did you learn from it?\n\nHow can you respond with greater grace and responsibility next time?\n\nHow does your faith encourage you to continue moving forward?"}}, {"type": "mood_checkin", "content": {"question": "How hopeful do you feel about your recovery journey today?"}}, {"type": "daily_action", "content": {"title": "Accept Grace and Take the Next Step", "action": "Spend a few quiet moments in prayer or personal reflection according to your faith.\n\nIf you are carrying guilt or discouragement, acknowledge it honestly.\n\nThen identify one practical action you can take today that reflects both personal responsibility and hope for the future.\n\nCommit to taking that step before the day ends."}}, {"type": "mentor_note", "content": {"note": "Grace gives you the courage to begin again.\n\nHope gives you the strength to keep going.\n\nTogether they help build lasting recovery and freedom."}}, {"type": "quiz", "content": {"question": "According to this lesson, grace:", "options": [{"text": "Gives permission to continue harmful behavior.", "is_correct": false}, {"text": "Encourages healing while supporting responsibility and growth.", "is_correct": true}, {"text": "Removes the need for personal effort.", "is_correct": false}, {"text": "Guarantees an easy recovery.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Grace and responsibility can work together during recovery.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What helps sustain lasting recovery?", "options": [{"text": "Giving up after setbacks.", "is_correct": false}, {"text": "Living with grace, hope, perseverance, and the guidance of your faith.", "is_correct": true}, {"text": "Ignoring mistakes.", "is_correct": false}, {"text": "Expecting perfection.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 7.", "encouragement": "You have now completed Chapter 7: The Two Ways of Living. Throughout this chapter, you explored the ongoing struggle between destructive patterns and a healthier way of living. You learned how daily choices, personal responsibility, obedience to the values of your faith, and consistent healthy habits shape the direction of your recovery.\n\nMost importantly, you discovered that lasting recovery is not built on perfection but on perseverance. As you continue choosing truth over deception, healing over temporary relief, and hope over discouragement, you strengthen your character and move closer to a life marked by freedom, purpose, and lasting spiritual growth.\n\nIn Chapter 8, you will begin exploring the practical process of renewing your mind, developing healthier thought patterns, and replacing destructive habits with life-giving ones that support lifelong recovery."}}]}]}, {"number": 8, "title": "The Spiritual War", "description": "Chapter 8 helps the learner understand the spiritual battle surrounding addiction recovery. It explores spiritual warfare, the enemy''s strategies, temptation and resistance, strongholds and bondage, the armor of God, victory through Christ, and standing firm throughout the recovery journey.\n\nThe goal of this chapter is to help the learner become spiritually alert, better equipped, and steadfast under pressure while continuing to grow in freedom through Christ. As learners develop discernment, strengthen their dependence on Christ, and stand firmly in biblical truth, they build a stronger foundation for lifelong recovery.", "lessons": [{"number": 1, "title": "Understanding Spiritual Warfare", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Recovery Involves More Than Personal Struggle", "message": "Addiction recovery is not only a battle against habits, emotions, or circumstances.\n\nFaith teaches that there is also a deeper spiritual struggle that affects what we believe, how we think, what we desire, and how we respond to temptation.\n\nUnderstanding this helps us see recovery more clearly.\n\nInstead of viewing every struggle as personal failure, we begin recognizing that some battles involve deeper spiritual pressures that must be faced with wisdom, truth, and faith."}}, {"type": "reading", "content": {"title": "Spiritual Warfare Is the Conflict Around Truth, Temptation, Identity, and Obedience", "body": "Spiritual warfare is not about fear, exaggeration, or becoming preoccupied with darkness.\n\nIt is about recognizing that there is real conflict surrounding the way we live, what we believe, and the direction our lives are taking.\n\nIn recovery, this conflict may appear through:\n\nRepeated lies.\n\nTemptation.\n\nShame.\n\nDiscouragement.\n\nFear.\n\nConfusion.\n\nAttacks against identity.\n\nPressure to compromise.\n\nOur faith teaches that spiritual alertness helps us identify these pressures before they quietly shape our choices.\n\nWithout this awareness, people may assume every struggle is only emotional or physical.\n\nThey may overlook the way unhealthy thoughts, discouragement, or temptation continue influencing their recovery.\n\nUnderstanding spiritual warfare helps us stay alert without becoming afraid.\n\nIt reminds us that recovery requires more than effort alone.\n\nIt requires truth, prayer, humility, self-awareness, and the guidance of our faith.\n\nWhen the deeper battle is understood, we become better prepared to respond wisely with a positive and graceful stance.\n\nReflection Question:\n\nWhere in your recovery do you sense that the struggle has involved more than habit alone?"}}, {"type": "mentor_note", "content": {"note": "Some battles keep repeating because they have not yet been understood clearly."}}, {"type": "video", "content": {"title": "Understanding Spiritual Warfare", "description": "A mentor-led introduction to spiritual warfare, exploring how deeper spiritual conflict can influence temptation, identity, discouragement, and recovery."}}, {"type": "pause_reflect", "content": {"question": "Think about the pressure points in your recovery.", "context": "Have you noticed repeated experiences such as:\n\nShame.\n\nFear.\n\nTemptation.\n\nConfusion.\n\nDiscouragement.\n\nHopeless thinking.\n\nAttacks against your identity.\n\nPressure to compromise.\n\nWhich of these has affected you most?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about one part of your recovery that now seems to involve a deeper spiritual struggle rather than habit alone.\n\nDescribe how greater spiritual awareness could help you respond differently."}}, {"type": "mood_checkin", "content": {"question": "How spiritually alert do you feel today?"}}, {"type": "daily_action", "content": {"title": "Respond with Spiritual Awareness", "action": "Spend a few quiet moments in prayer or personal reflection according to your faith.\n\nChoose one area where you have felt repeated pressure.\n\nAsk yourself whether there may be a deeper spiritual influence affecting your thoughts, emotions, or decisions.\n\nWrite down one healthy response you can choose today."}}, {"type": "mentor_note", "content": {"note": "Spiritual awareness is not fear.\n\nIt is learning to recognize the deeper unseen battle so you can stand more wisely."}}, {"type": "quiz", "content": {"question": "According to this lesson, spiritual warfare includes:", "options": [{"text": "Only emotional struggle.", "is_correct": false}, {"text": "Real conflict involving relying on truth, standing against temptation, building identity, and obedience.", "is_correct": true}, {"text": "A dramatic public display.", "is_correct": false}, {"text": "Something irrelevant to recovery.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Recovery can involve deeper spiritual conflict as well as emotional and behavioral struggle.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "Why is understanding spiritual warfare important?", "options": [{"text": "It helps you respond with greater alertness, wisdom, and preparation.", "is_correct": true}, {"text": "It removes personal responsibility.", "is_correct": false}, {"text": "It makes prayer unnecessary.", "is_correct": false}, {"text": "It replaces practical recovery work.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 1.", "encouragement": "Today you learned that recovery involves more than habits and emotions. There can also be a deeper spiritual struggle influencing temptation, shame, fear, and the way you see yourself. As you grow in spiritual awareness and continue relying on truth, prayer, and the guidance of your faith, you become better prepared to face the real battle with wisdom and strength.\n\nIn the next lesson, we will explore The Enemy''s Strategies and discover how repeated patterns, subtle compromise, and unchallenged lies often prepare the ground for relapse long before visible failure happens."}}]}, {"number": 2, "title": "The Enemy''s Strategies", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Not Every Attack Is Obvious", "message": "Many struggles in recovery do not begin with a dramatic moment.\n\nThey often begin quietly through repeated thoughts, subtle compromises, discouragement, isolation, or emotional exhaustion when starting to abuse drugs.\n\nSpiritual pressure often works through strategy rather than sudden open attack.\n\nThis lesson explores how destructive patterns are often prepared long before visible relapse happens, and why learning to recognize these strategies early strengthens lasting recovery."}}, {"type": "reading", "content": {"title": "Harmful Patterns Often Begin with Small Openings", "body": "One of the most dangerous things about destructive spiritual pressure is that it is often subtle.\n\nIt may appear through:\n\nDeceptive lies.\n\nIsolation from healthy support.\n\nIncreased shame.\n\nEmotional exhaustion.\n\nSecret compromise.\n\nDoubt.\n\nHopelessness.\n\nAttacks against identity.\n\nGradual weakening of boundaries.\n\nMany people focus only on the final moment of failure.\n\nBut relapse is often prepared much earlier.\n\nIt may begin when unhealthy thoughts go unchallenged.\n\nIt may begin when someone stops reaching out for support.\n\nIt may begin when small compromises are excused.\n\nIt may begin when discouragement is allowed to grow in silence.\n\nFaith teaches that spiritual discernment is essential because it helps us recognize the setup of deception before the trap and eventual fall.\n\nRecovery becomes stronger when we stop asking only,\n\n\"Why did I fail?\"\n\nand begin asking,\n\n\"What patterns were preparing me for that fall?\"\n\nRecognizing these patterns early gives you the opportunity to respond before the situation becomes more difficult.\n\nDiscernment often protects you before willpower is even needed.\n\nReflection Question:\n\nWhich pattern tends to weaken you most often—lies, isolation, shame, fatigue, discouragement, or compromise?"}}, {"type": "mentor_note", "content": {"note": "Many visible failures are prepared long before they can be seen."}}, {"type": "video", "content": {"title": "The Enemy''s Strategies", "description": "A mentor-led lesson exploring how destructive spiritual pressure often works through repeated lies, compromise, isolation, emotional exhaustion, and attacks against identity, and how recognizing these patterns early strengthens recovery."}}, {"type": "pause_reflect", "content": {"question": "Think about the times your recovery became weaker.", "context": "What happened before the visible struggle became obvious?\n\nReflect on whether you noticed:\n\nLess prayer or spiritual focus.\n\nMore secrecy.\n\nIncreased fatigue.\n\nIsolation.\n\nShame.\n\nNegative thinking.\n\nWeakened boundaries.\n\nQuiet compromise.\n\nWhich early sign appears most often in your life?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about one repeated pattern that has often set you up for struggle.\n\nThen answer:\n\nHow does it usually begin?\n\nWhy is it easy to overlook?\n\nWhat could help you recognize it earlier next time?"}}, {"type": "mood_checkin", "content": {"question": "How aware are you of early warning signs in your recovery today?"}}, {"type": "daily_action", "content": {"title": "Watch for the Setup", "action": "Spend a few quiet moments in prayer or personal reflection according to your faith.\n\nChoose one early warning sign you know often appears before greater struggle.\n\nPay close attention to that area today, and if it appears, respond immediately with one healthy action such as honesty, prayer, reaching out for support, or strengthening a boundary."}}, {"type": "mentor_note", "content": {"note": "Discernment often protects a person earlier than willpower alone ever could."}}, {"type": "quiz", "content": {"question": "According to this lesson, destructive spiritual pressure often works through:", "options": [{"text": "Only dramatic moments.", "is_correct": false}, {"text": "Subtle and repeated strategies that weaken recovery over time.", "is_correct": true}, {"text": "Public failure only.", "is_correct": false}, {"text": "Random events with no pattern.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Visible failure is often prepared earlier by smaller compromises and repeated unhealthy patterns.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What strengthens lasting recovery according to this lesson?", "options": [{"text": "Ignoring early warning signs.", "is_correct": false}, {"text": "Recognizing repeated patterns and responding to them early.", "is_correct": true}, {"text": "Waiting until the struggle becomes overwhelming.", "is_correct": false}, {"text": "Relying only on last-minute determination.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 2.", "encouragement": "Today you learned that many struggles in recovery are prepared long before they become visible. Repeated lies, isolation, fatigue, shame, and small compromises can quietly weaken your resolve if they remain unnoticed. As you continue growing in discernment and responding early with truth, prayer, healthy support, and strong boundaries, you strengthen your ability to protect your recovery before greater pressure takes hold.\n\nIn the next lesson, we will explore Temptation and Resistance, discovering how temptation grows and how responding early and decisively can prevent destructive patterns from gaining momentum."}}]}, {"number": 3, "title": "Temptation and Resistance", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Temptation Is Real, but It Does Not Have to Control You", "message": "Temptation is part of every life journey and recovery journey in the case of drug abuse and addiction.\n\nIt can feel powerful, sudden, and persuasive.\n\nTemptation itself is not the same as failure. What matters is how we respond when temptation appears.\n\nThis lesson explores how temptation grows and why resistance becomes stronger when we recognize what temptation looks like and what type of temptation it is."}}, {"type": "reading", "content": {"title": "Resistance Is Strongest When Temptation Is Recognized Early", "body": "Temptation rarely begins at full strength.\n\nIt often starts quietly through:\n\nA thought.\n\nA memory.\n\nA feeling.\n\nA rationalization.\n\nA craving.\n\nA moment of loneliness.\n\nA desire for quick relief.\n\nA small compromise.\n\nIf it is ignored or entertained, it usually grows stronger.\n\nMany people wait until temptation becomes overwhelming before trying to resist it.\n\nBy then, the struggle often feels much harder.\n\nMany faith traditions teach that wisdom means responding early.\n\nResistance becomes stronger when we interrupt temptation before it gains momentum.\n\nThis may include:\n\nRecognizing the thought quickly.\n\nReplacing it with truth.\n\nChanging your environment.\n\nReaching out for support.\n\nPraying immediately.\n\nRedirecting your attention.\n\nStrengthening a boundary.\n\nRecovery becomes more stable when we stop treating temptation casually.\n\nThe earlier you respond, the more power you have to choose wisely.\n\nTemptation may be real, but it is not automatically stronger than truth, preparation, and action.\n\nReflection Question:\n\nAt what stage do you usually take temptation seriously—early, late, or only after it has already gained strength?"}}, {"type": "mentor_note", "content": {"note": "What is resisted early rarely grows as strong as what is quietly entertained."}}, {"type": "video", "content": {"title": "Temptation and Resistance", "description": "A mentor-led lesson exploring how temptation grows, why early resistance is stronger, and how practical action helps prevent destructive patterns from gaining momentum."}}, {"type": "pause_reflect", "content": {"question": "Think about the last time you felt strong temptation.", "context": "Ask yourself:\n\nHow did it begin?\n\nWhat early sign did I ignore?\n\nWhen did it start gaining strength?\n\nWhat could I have done earlier to interrupt it?\n\nWhat do you notice?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about one way temptation usually begins in your life.\n\nThen describe:\n\nWhat early warning sign appears first.\n\nWhat happens if you ignore it.\n\nOne specific action that could help you resist it earlier next time."}}, {"type": "mood_checkin", "content": {"question": "How ready do you feel to respond early to temptation today?"}}, {"type": "daily_action", "content": {"title": "Interrupt Temptation Early", "action": "Today, if a tempting thought or urge appears, do not wait for it to grow.\n\nSpend a few quiet moments in prayer or personal reflection according to your faith.\n\nImmediately choose one concrete response:\n\nSpeak a truth out loud and repeat it.\n\nLeave the situation.\n\nContact someone supportive.\n\nRedirect your attention.\n\nStrengthen a boundary.\n\nPractice early resistance instead of delayed resistance."}}, {"type": "mentor_note", "content": {"note": "Early resistance is one of the most practical forms of wisdom in recovery."}}, {"type": "quiz", "content": {"question": "According to this lesson, resistance becomes stronger when:", "options": [{"text": "Temptation is ignored.", "is_correct": false}, {"text": "Temptation is recognized and addressed early.", "is_correct": true}, {"text": "You wait until the urge is overwhelming.", "is_correct": false}, {"text": "You treat temptation casually.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Delayed resistance often becomes weaker resistance.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What is one healthy response to temptation?", "options": [{"text": "Entertaining the thought quietly.", "is_correct": false}, {"text": "Interrupting it quickly with truth and action.", "is_correct": true}, {"text": "Waiting to see how strong it becomes.", "is_correct": false}, {"text": "Pretending it is not happening.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 3.", "encouragement": "Today you learned that temptation is real, but it does not have to control you. Resistance becomes much stronger when you respond early instead of waiting for the struggle to intensify. As you continue practicing early recognition, truth-based thinking, prayer, healthy boundaries, and immediate action, you strengthen your ability to protect your recovery and remain steady under pressure.\n\nIn the next lesson, we will explore Strongholds and Bondage, helping you understand how repeated compromise and false beliefs create deeper patterns that must be confronted honestly in order for lasting freedom to grow."}}]}, {"number": 4, "title": "Strongholds and Bondage", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Some Patterns Become More Than Habits", "message": "Not every struggle remains small.\n\nSome unhealthy patterns become deeply rooted over time.\n\nWe recognize that repeated compromise, false beliefs, emotional wounds, and secrecy can create stronger forms of bondage that are harder to break if they remain unchallenged.\n\nThis lesson explores how strongholds are formed and why freedom from drug abuse requires more than simply changing behavior on the surface."}}, {"type": "reading", "content": {"title": "Strongholds Grow Where Lies and Compromise Are Repeated", "body": "A stronghold is not just a bad day or a moment of weakness.\n\nIt is a deeper pattern that has been reinforced again and again through repeated thoughts, repeated choices, and repeated agreements with what is false.\n\nIn addiction, strongholds may appear through:\n\nIdentity lies such as \"This is just who I am.\"\n\nHopelessness.\n\nChronic secrecy.\n\nEmotional numbing.\n\nRepeated justifications.\n\nFear of change.\n\nBelieving freedom is impossible.\n\nContinuing to protect destructive habits.\n\nOver time, these patterns can feel normal or permanent.\n\nThat is what makes them dangerous.\n\nTrue freedom requires more than interrupting one behavior and overcoming it, yet its step by step, and one victory over a strong hold is a great achievement.\n\nIt also requires confronting the beliefs system, negative agreements, and emotional patterns that keep the bad behavior protected.\n\nRecovery becomes stronger when we ask not only,\n\n\"What behavior must stop?\"\n\nbut also,\n\n\"What lie, wound, or agreement has been keeping this pattern alive?\"\n\nStrongholds lose power when they are brought into the light and challenged with truth, honesty, support, and faithful action.\n\nReflection Question:\n\nWhat deeper pattern or false belief has had the strongest hold on your life?"}}, {"type": "mentor_note", "content": {"note": "What is reinforced repeatedly can begin to feel permanent—until it is honestly confronted."}}, {"type": "video", "content": {"title": "Strongholds and Bondage", "description": "A mentor-led lesson exploring how strongholds develop through repeated compromise, false beliefs, and hidden agreements, and how truth helps break deeper forms of bondage in recovery."}}, {"type": "pause_reflect", "content": {"question": "Think about the struggles that feel hardest to change.", "context": "Ask yourself:\n\nWhat belief keeps reinforcing this pattern?\n\nWhat pain or fear may be hiding beneath it?\n\nWhat excuse have I repeated most often?\n\nWhat agreement have I quietly made with this struggle?\n\nWhat stands out most?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about one stronghold you believe needs deeper attention.\n\nThen describe:\n\nHow it has shown up in your life.\n\nWhat belief or emotional pattern has helped keep it strong.\n\nWhat truth could begin weakening its hold.\n\nWhat one practical step you can take this week to confront it honestly."}}, {"type": "mood_checkin", "content": {"question": "How free or trapped do you feel in your inner life today?"}}, {"type": "daily_action", "content": {"title": "Name the Stronghold Honestly", "action": "Spend a few quiet moments in prayer or personal reflection according to your faith.\n\nIdentify one deeper struggle that has remained strongly rooted in your life.\n\nWrite it down clearly.\n\nThen write the false belief or hidden agreement that has been helping it stay in place, and one truth that challenges it."}}, {"type": "mentor_note", "content": {"note": "Bondage becomes stronger when it stays hidden and defended.\n\nIt begins weakening when it is named honestly and confronted with truth."}}, {"type": "quiz", "content": {"question": "According to this lesson, a stronghold is:", "options": [{"text": "A passing emotion.", "is_correct": false}, {"text": "A reinforced pattern built through repeated lies, compromise, and agreement.", "is_correct": true}, {"text": "A harmless habit.", "is_correct": false}, {"text": "Only an external problem.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Lasting recovery requires confronting hidden beliefs and agreements, not only visible behavior.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What helps weaken a stronghold?", "options": [{"text": "Pretending it is not there.", "is_correct": false}, {"text": "Bringing it into the light and confronting it with truth.", "is_correct": true}, {"text": "Protecting the underlying excuses.", "is_correct": false}, {"text": "Waiting for it to disappear on its own.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 4.", "encouragement": "Today you learned that some struggles become deeply rooted because they are reinforced by repeated lies, compromise, and hidden agreements. Lasting recovery grows stronger when you confront not only the outward behavior, but also the deeper beliefs and emotional patterns that keep it alive. As you continue bringing strongholds into the light through honesty, truth, and the guidance of your faith, you weaken their hold and strengthen your path toward lasting freedom.\n\nIn the next lesson, we will explore The Armor of God and discover how spiritual preparation helps you remain steady, protected, and ready when pressure rises."}}]}, {"number": 5, "title": "The Armor of God", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Lasting Recovery Requires Daily Spiritual Preparation", "message": "Recovery is not only about reacting when pressure becomes overwhelming.\n\nIt is also about preparing yourself before difficult moments arrive.\n\nIt would be wise to be consistently spiritually aware in your faith. When we are spiritually prepared, we are better able to respond to temptation, discouragement, fear, and spiritual pressure with steadiness and truth.\n\nThis lesson explores the importance of spiritual preparation and how building a strong foundation each day strengthens lasting recovery."}}, {"type": "reading", "content": {"title": "Spiritual Preparation Helps You Stand Firm Under Pressure", "body": "Many people only focus on recovery when they are already struggling.\n\nBut lasting strength is often built before the moment of temptation arrives.\n\nMany faith traditions teach that spiritual preparation includes building your life around:\n\nTruth.\n\nFaith.\n\nIntegrity.\n\nReadiness.\n\nPrayer.\n\nWise boundaries.\n\nA clear sense of identity.\n\nThe teachings and guidance of your faith.\n\nThese daily practices strengthen your inner life.\n\nThey help protect your mind when lies appear.\n\nThey help protect your heart when discouragement rises.\n\nThey help protect your decisions when temptation becomes strong.\n\nRecovery becomes more durable when preparation and understanding becomes a daily habit rather than an emergency response.\n\nInstead of waiting until you feel weak, you begin strengthening yourself consistently.\n\nSpiritual preparation is not about fear.\n\nIt is about wisdom.\n\nIt is the choice to take your recovery seriously enough to prepare for the battles you know will come.\n\nReflection Question:\n\nWhich part of your spiritual preparation feels weakest right now?"}}, {"type": "mentor_note", "content": {"note": "A person who prepares before pressure rises often stands stronger when it comes."}}, {"type": "video", "content": {"title": "The Armor of God", "description": "A mentor-led lesson exploring spiritual preparation, truth, faith, integrity, readiness, and how daily practices strengthen recovery before difficult moments arrive."}}, {"type": "pause_reflect", "content": {"question": "Think about your current spiritual preparation.", "context": "Reflect on areas such as:\n\nTruth-based thinking.\n\nPrayer or reflection.\n\nDaily faith practices.\n\nHealthy boundaries.\n\nYour sense of identity.\n\nSupportive relationships.\n\nReadiness for temptation.\n\nWhich area needs the most strengthening?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about one area where you need stronger spiritual preparation.\n\nThen describe:\n\nWhy this area matters in your recovery.\n\nHow weakness in this area affects you.\n\nOne practical step you can begin taking this week to strengthen it."}}, {"type": "mood_checkin", "content": {"question": "How spiritually prepared do you feel for pressure today?"}}, {"type": "daily_action", "content": {"title": "Strengthen One Area of Readiness", "action": "Spend a few quiet moments in prayer or personal reflection according to your faith.\n\nChoose one area where you need greater readiness.\n\nTake one practical step today to strengthen it, such as reviewing a truth you need, setting a stronger boundary, reaching out for support, or creating a healthier daily routine."}}, {"type": "mentor_note", "content": {"note": "Preparation is one of the quiet forms of strength that protects long-term recovery."}}, {"type": "quiz", "content": {"question": "According to this lesson, spiritual preparation should be:", "options": [{"text": "Used only in emergencies.", "is_correct": false}, {"text": "Practiced daily to strengthen recovery before pressure rises.", "is_correct": true}, {"text": "Avoided until temptation becomes severe.", "is_correct": false}, {"text": "Based only on feelings.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Daily spiritual preparation can help you respond more wisely when temptation and pressure appear.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What strengthens lasting recovery according to this lesson?", "options": [{"text": "Waiting until pressure becomes overwhelming.", "is_correct": false}, {"text": "Daily readiness built through truth, faith, boundaries, and the practices of your faith.", "is_correct": true}, {"text": "Ignoring weak areas.", "is_correct": false}, {"text": "Depending only on willpower.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 5.", "encouragement": "Today you learned that lasting recovery is strengthened by daily spiritual preparation. When truth, faith, integrity, healthy boundaries, and wise routines become part of your everyday life, you become more ready to stand firm when pressure rises. Preparation is not fear—it is wisdom, and it protects the healing you are working hard to build.\n\nIn the next lesson, we will explore Victory Through Christ and discover how lasting victory is strengthened not by self-reliance alone, but through dependence on Christ, truth, and faithful perseverance."}}]}, {"number": 6, "title": "Victory Through Christ", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Lasting Victory Does Not Come from Personal Strength Alone", "message": "Many people approach recovery believing that success depends entirely on their own willpower.\n\nWhen they struggle, they often conclude that they are simply not strong enough.\n\nWe have to understand that lasting victory is not built on self-reliance alone. It grows through dependence on your faith, knowledge and wisdom, and not only personally, but those qualities others share with you.\n\nThis lesson explores how victory becomes stronger when confidence shifts away from personal strength alone and toward the sustaining help of God."}}, {"type": "reading", "content": {"title": "Dependence on your faith Strengthens the Recovery Journey", "body": "Recovery still requires effort.\n\nIt still requires honesty, discipline, responsibility, and wise choices.\n\nBut many faith traditions teach that true strength grows when we stop carrying everything alone.\n\nVictory becomes stronger when we understand that:\n\nWe do not have to fight every battle through willpower alone.\n\nSpiritual strength is available when we seek it.\n\nHope does not disappear because we feel weak.\n\nFaith gives us a stronger foundation than self-reliance.\n\nLasting recovery grows through dependence, humility, and perseverance.\n\nMany people become discouraged because they interpret struggle as proof that they are failing.\n\nBut weakness does not mean recovery is over.\n\nIt often means we need greater support, deeper prayer, stronger truth, and renewed dependence on the Divine.\n\nVictory is not the absence of struggle.\n\nIt is the ability to continue moving toward healing with faith, courage, and sustained dependence on a power greater than ourselves.\n\nAs confidence shifts from self-sufficiency to spiritual dependence, recovery becomes steadier and less driven by fear.\n\nReflection Question:\n\nWhere in your recovery are you still depending mostly on your own strength?"}}, {"type": "mentor_note", "content": {"note": "Lasting victory grows stronger when confidence moves from self-reliance to spiritual dependence."}}, {"type": "video", "content": {"title": "Victory Through Christ", "description": "A mentor-led lesson exploring how lasting victory is strengthened through dependence on Christ, truth, perseverance, and a life rooted in faith rather than self-reliance alone."}}, {"type": "pause_reflect", "content": {"question": "Think about the places where you feel most pressure in recovery.", "context": "Ask yourself:\n\nWhere do I feel I have to carry this alone?\n\nWhere do I become discouraged when I feel weak?\n\nWhere do I need deeper faith, support, and dependence on the Divine?\n\nWhich area stands out most?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about one area where you want to depend less on your own strength and more on the help of the Divine.\n\nThen describe:\n\nWhy self-reliance has been difficult or exhausting.\n\nWhat spiritual dependence looks like for you.\n\nOne practical way you can strengthen that dependence this week."}}, {"type": "mood_checkin", "content": {"question": "How dependent on spiritual strength do you feel today?"}}, {"type": "daily_action", "content": {"title": "Shift Your Confidence", "action": "Spend a few quiet moments in prayer or personal reflection according to your faith.\n\nIdentify one pressure you have been trying to carry by yourself.\n\nRelease it honestly to the Divine, and choose one practical action today that reflects humility, trust, and willingness to seek help instead of carrying everything alone."}}, {"type": "mentor_note", "content": {"note": "Strength becomes steadier when it no longer depends only on you."}}, {"type": "quiz", "content": {"question": "According to this lesson, lasting victory is strengthened by:", "options": [{"text": "Self-reliance alone.", "is_correct": false}, {"text": "Dependence on your God and spiritual strength rather than willpower alone.", "is_correct": true}, {"text": "Avoiding responsibility.", "is_correct": false}, {"text": "Pretending weakness does not exist.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: This lesson teaches that effort is still important, but victory is not built on willpower alone.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What changes when confidence shifts away from self-sufficiency?", "options": [{"text": "Recovery becomes steadier and less fear-driven.", "is_correct": true}, {"text": "Discipline becomes unnecessary.", "is_correct": false}, {"text": "Truth matters less.", "is_correct": false}, {"text": "Weakness becomes proof of failure.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 6.", "encouragement": "Today you learned that lasting victory is not built on personal strength alone. Recovery becomes steadier when you stop trying to carry every struggle by yourself and instead lean into the strength, truth, and sustaining help of the Creator. As your confidence shifts from self-reliance to faith, humility, and perseverance, you build a stronger foundation for lasting healing.\n\nIn the final lesson of this chapter, we will explore Standing Firm in Recovery and discover how steadiness, preparation, truth, and faithful daily choices protect long-term freedom.\n\n."}}]}, {"number": 7, "title": "Standing Firm in Recovery", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Lasting Recovery Requires Steadiness, Not Just Breakthrough Moments", "message": "Recovery is not sustained only by dramatic moments of change.\n\nIt is often protected by steady daily choices, clear boundaries, spiritual alertness, and the willingness to keep going even when pressure does not disappear quickly.\n\nStrength is not always loud. Sometimes it is shown through endurance, patience, faithfulness, and the decision to remain grounded when life becomes difficult.\n\nThis final lesson explores what it means to stand firm in recovery and why steadiness and consistency is one of the most powerful forms of long-term strength."}}, {"type": "reading", "content": {"title": "Standing Firm Means Staying Grounded Under Pressure", "body": "Standing firm does not mean never feeling weak.\n\nIt does not mean never feeling tempted, discouraged, or tired.\n\nIt means refusing to surrender your values, boundaries, and faith when those pressures appear.\n\nMany faith traditions teach that lasting recovery is strengthened through:\n\nTruth.\n\nHealthy boundaries.\n\nSpiritual preparation.\n\nPrayer or reflection.\n\nHonest relationships.\n\nDaily discipline.\n\nHumility.\n\nPerseverance.\n\nMany people expect recovery to feel strong only during moments of motivation.\n\nBut lasting freedom is usually protected through steady perseverance.\n\nStanding firm means:\n\nHolding to truth when lies appear.\n\nKeeping boundaries when compromise feels easier.\n\nAsking for help when isolation feels safer.\n\nContinuing healthy habits when motivation is low.\n\nRemaining committed to healing even when progress feels slow.\n\nSteadiness may not feel dramatic.\n\nBut it is often what protects recovery over time.\n\nMany great victories in life come not from speed, but from refusing to totally give up.\n\nReflection Question:\n\nWhere in your recovery do you most need greater steadiness right now?"}}, {"type": "mentor_note", "content": {"note": "Many battles are won not through speed, but through steadiness."}}, {"type": "video", "content": {"title": "Standing Firm in Recovery", "description": "A mentor-led conclusion to the chapter exploring how lasting recovery is protected through truth, boundaries, spiritual readiness, perseverance, and faithful daily choices."}}, {"type": "pause_reflect", "content": {"question": "Think about the area where you feel most vulnerable.", "context": "Ask yourself:\n\nWhere am I most likely to drift?\n\nWhere do I become discouraged most easily?\n\nWhich boundary do I most need to protect?\n\nWhat helps me remain grounded when pressure rises?\n\nWhat stands out most?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about one practical way you can stand firmer in your recovery this week.\n\nThen describe:\n\nWhy this area needs more steadiness.\n\nWhat usually weakens you there.\n\nWhat truth, habit, or support can help you remain grounded."}}, {"type": "mood_checkin", "content": {"question": "How steady do you feel in your recovery today?"}}, {"type": "daily_action", "content": {"title": "Hold Your Ground Today", "action": "Spend a few quiet moments in prayer or personal reflection according to your faith.\n\nChoose one boundary, truth, or healthy practice that you will hold firmly today without negotiating with it.\n\nLet that act of steadiness become one more step toward lasting freedom."}}, {"type": "mentor_note", "content": {"note": "Steady perseverance is one of the quiet strengths that protects long-term freedom."}}, {"type": "quiz", "content": {"question": "According to this lesson, standing firm means:", "options": [{"text": "Never feeling weak.", "is_correct": false}, {"text": "Remaining grounded in truth, faith, and healthy boundaries under pressure.", "is_correct": true}, {"text": "Avoiding every challenge.", "is_correct": false}, {"text": "Waiting for dramatic breakthroughs only.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Lasting recovery is often protected through steady daily faithfulness rather than dramatic moments alone.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What most strengthens long-term recovery according to this lesson?", "options": [{"text": "Drifting when pressure rises.", "is_correct": false}, {"text": "Persevering with steadiness, preparation, truth, and healthy boundaries.", "is_correct": true}, {"text": "Ignoring weak areas.", "is_correct": false}, {"text": "Depending only on motivation.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 7.", "encouragement": "You have now completed Chapter 8: The Spiritual War. Throughout this chapter, you learned that recovery involves more than breaking habits—it also requires spiritual awareness, discernment, preparation, resistance, and perseverance. You explored the deeper strategies that weaken recovery, the importance of responding early to temptation, the role of strongholds and spiritual readiness, and the strength that comes through dependence on Christ and faithful endurance.\n\nMost importantly, you discovered that lasting freedom is often protected not by dramatic moments alone, but by steady daily faithfulness. As you continue standing firm in truth, strengthening your spiritual preparation, maintaining healthy boundaries, and relying on the guidance of your faith, you build a recovery that can remain strong even under pressure.\n\nIn Chapter 9, you will begin exploring the battle of the mind, learning how thoughts, beliefs, attention, and mental habits influence recovery—and how renewing the mind helps strengthen lasting healing, peace, and spiritual stability."}}]}]}, {"number": 9, "title": "The Mind Battlefield", "description": "Chapter 9 focuses on the internal battle of thoughts, interpretation, emotions, and mental discipline during recovery. It shifts the focus from external behavior to the inner world, where many decisions are formed long before actions take place.\n\nThe goal of this chapter is to help you become mentally disciplined, emotionally steady, and grounded in truth so that your recovery is not constantly destabilized by unhealthy thinking patterns. As you learn to renew your mind, challenge harmful thoughts, and build healthier mental habits, you create a stronger foundation for lasting freedom.", "lessons": [{"number": 1, "title": "Renewing the Mind", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Recovery Strengthens When the Mind Changes, Not Just Behavior", "message": "Recovery is not only about stopping harmful actions.\n\nIf the thinking behind those actions stays the same, the patterns usually return.\n\nLasting change begins in the mind. The way you think shapes how you interpret life, respond to temptation, and understand yourself.\n\nThis lesson introduces the idea that your mind is a battlefield—and renewing it is essential for lasting recovery."}}, {"type": "reading", "content": {"title": "Renewal Retrains How You See Everything", "body": "Addiction captures the mind in negative ways.\n\nOver time, thinking patterns may become shaped by:\n\nDrug dependency.\n\nEscaping reality.\n\nShame.\n\nFear.\n\nHopelessness.\n\nDistorted identity.\n\nSelf-justification.\n\nThese patterns do not always disappear automatically when behavior changes.\n\nThey must be replaced.\n\nWe have to teach ourselves that renewal of the mind means replacing false, distorted, or harmful thinking with truth shaped by the teachings of your faith.\n\nRenewing the mind means:\n\nRecognizing unhealthy thought patterns.\n\nQuestioning them instead of automatically believing them.\n\nReplacing them with truth, values and principles.\n\nPracticing new ways of thinking consistently.\n\nThis process takes time.\n\nIt is not instant.\n\nBut it is essential.\n\nLasting recovery becomes stronger when your thinking begins aligning with truth instead of old patterns.\n\nChange becomes durable when the negative ways you interpreted life before begins to change.\n\nReflection Question:\n\nWhere in your thinking do you most need renewal right now?"}}, {"type": "mentor_note", "content": {"note": "A renewed life requires a renewed way of thinking."}}, {"type": "video", "content": {"title": "Renewing the Mind", "description": "A mentor-led introduction to mental renewal and how changing thought patterns strengthens lasting recovery."}}, {"type": "pause_reflect", "content": {"question": "Think about your current thought patterns.", "context": "Where do you notice the most struggle?\n\nIdentity.\n\nCravings.\n\nFear.\n\nShame.\n\nHopeless thinking.\n\nHow you interpret setbacks.\n\nWhich area needs the most renewal?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about one recurring thought pattern that has been influencing your recovery.\n\nThen describe:\n\nWhy it is harmful.\n\nWhen it usually appears.\n\nWhat truth could replace it."}}, {"type": "mood_checkin", "content": {"question": "How clear or cluttered does your mind feel today?"}}, {"type": "daily_action", "content": {"title": "Replace One Thought Today", "action": "Pay attention to your thoughts today.\n\nWhen one unhealthy or repeated thought appears, do not ignore it.\n\nPause.\n\nSpend a few quiet moments in prayer or personal reflection according to your faith.\n\nReplace that thought with one truth-based alternative that reflects the values of your faith."}}, {"type": "mentor_note", "content": {"note": "Lasting change often begins when thinking patterns begin to change from negative and destructive, to positive and life giving."}}, {"type": "quiz", "content": {"question": "According to this lesson, renewing the mind means:", "options": [{"text": "Ignoring thoughts.", "is_correct": false}, {"text": "Replacing harmful thinking with truth.", "is_correct": true}, {"text": "Only controlling behavior.", "is_correct": false}, {"text": "Avoiding reflection.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Renewing the mind is essential for lasting recovery.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "Why does renewing the mind matter?", "options": [{"text": "It retrains how you interpret life, temptation, and identity.", "is_correct": true}, {"text": "It removes all effort.", "is_correct": false}, {"text": "It replaces discipline.", "is_correct": false}, {"text": "It avoids responsibility.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 1.", "encouragement": "This is where things get serious.\n\nIf your mind stays wired the old way, you’ll keep getting pulled back into the same cycles—even if your intentions are good.\n\nBut if you retrain your thinking, everything changes:\n\nYou respond differently.\n\nYou see temptation earlier.\n\nYou stop believing lies automatically.\n\nIn the next lesson, we’re going to break down Identifying Harmful Thought Patterns—because you can’t fix what you’re still blindly believing."}}]}, {"number": 2, "title": "Identifying Harmful Thought Patterns", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "You Cannot Fix What You Refuse to See", "message": "You keep thinking “I’ll just stop.”\n\nThat’s lazy thinking.\n\nIf you don’t identify the exact pattern driving the behavior, you’re just reacting blindly.\n\nThis lesson forces you to stop being vague and start being precise."}}, {"type": "reading", "content": {"title": "Harmful Thought Patterns Quietly Run Your Behavior", "body": "Most people think their problem is behavior.\n\nWrong.\n\nThe real problem is the thinking pattern that keeps producing that behavior.\n\nThese patterns feel normal because you’ve repeated them so many times.\n\nCommon ones:\n\nAll-or-nothing thinking → “I messed up once, so it’s over.”\n\nHopeless thinking → “Nothing will change anyway.”\n\nSelf-pity → “No one understands me.”\n\nEntitlement → “I deserve this.”\n\nMinimizing → “It’s not that bad.”\n\nEscape thinking → “I just need relief right now.”\n\nHere’s the problem:\n\nIf you don’t name the pattern, you keep obeying it.\n\nAddiction survives in unnamed thinking.\n\nThe moment you recognize it and name it, you weaken it.\n\nThat’s the leverage.\n\nReflection Question:\n\nWhich thought pattern keeps showing up before your worst decisions?"}}, {"type": "mentor_note", "content": {"note": "A repeated thought becomes a trusted lie when it is never challenged."}}, {"type": "video", "content": {"title": "Identifying Harmful Thought Patterns", "description": "A breakdown of how destructive thinking patterns form and how to recognize them early before they control your actions."}}, {"type": "pause_reflect", "content": {"question": "Look at your last mistake.", "context": "Don’t analyze the action—analyze the thinking before it.\n\nAsk:\n\nWhat was I telling myself?\n\nWhat did I justify?\n\nWhat did I ignore?\n\nWhat did I exaggerate?\n\nThat’s your pattern."}}, {"type": "journal_prompt", "content": {"prompt": "Write down ONE harmful thought pattern.\n\nNot five. One.\n\nThen break it down:\n\nWhen does it show up?\n\nWhat does it say?\n\nWhat action does it lead to?\n\nIf you can’t answer this clearly, you’re still guessing—and guessing doesn’t fix anything."}}, {"type": "mood_checkin", "content": {"question": "How aware are you of your thinking right now?\n\nBe honest—are you aware, or just reacting?"}}, {"type": "daily_action", "content": {"title": "Name It Immediately", "action": "Today, you’re not allowed to stay vague.\n\nWhen a harmful thought appears:\n\nStop.\n\nLabel it.\n\nExample:“This is entitlement.”“This is escape thinking.”“This is self-pity.”\n\nOnce it’s named, it loses control."}}, {"type": "mentor_note", "content": {"note": "What stays vague stays powerful.\n\nWhat gets named starts losing control."}}, {"type": "quiz", "content": {"question": "What is the main job in this lesson?", "options": [{"text": "Identifying damaging thought patterns", "is_correct": true}, {"text": "Ignoring thoughts", "is_correct": false}, {"text": "Only tracking behavior", "is_correct": false}, {"text": "Avoiding honesty", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Harmful thinking can quietly keep you stuck.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "Why does identifying patterns matter?", "options": [{"text": "It prepares them to be challenged", "is_correct": true}, {"text": "It ends all struggle instantly", "is_correct": false}, {"text": "It removes responsibility", "is_correct": false}, {"text": "It replaces truth", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 2", "encouragement": "Now you’re starting to see the real problem.\n\nNot “I relapsed.”Not “I felt tempted.”\n\nIt’s:“I believed a pattern.”\n\nThat’s what you fix.\n\nNext lesson → Taking Thoughts Captive\n\nThat’s where you stop being passive and start controlling what gets to live in your head."}}]}, {"number": 3, "title": "Taking Thoughts Captive", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Not Every Thought Deserves Your Agreement", "message": "Right now, you’re still letting thoughts walk in and take over like they own the place.\n\nThat’s the problem.\n\nJust because a thought appears doesn’t mean:\n\nIt’s true\n\nIt’s useful\n\nOr you should follow it\n\nThis lesson is where you stop being passive and start taking control."}}, {"type": "reading", "content": {"title": "If You Don’t Control Your Thoughts, They Control You", "body": "Most people treat thoughts like facts.\n\nThat’s weak.\n\nA thought is just a suggestion until you agree with it.\n\nHere’s what’s actually happening:\n\nThought appears\n\nYou assume it’s valid\n\nYou follow it\n\nIt becomes behavior\n\nThat’s the loop.\n\nTaking thoughts captive breaks that loop.\n\nIt means:\n\nYou pause\n\nYou examine the thought\n\nYou test it against truth\n\nYou reject it if it’s false\n\nExamples:\n\nThought: “I need this right now.”→ Reality: Urgency is fake. You won’t die without it.\n\nThought: “I already messed up, so it doesn’t matter.”→ Reality: That’s all-or-nothing thinking.\n\nThought: “I deserve this.”→ Reality: That’s entitlement trying to justify damage.\n\nYou don’t kill bad patterns by avoiding them.You kill them by challenging them directly.\n\nReflection Question:\n\nWhich type of thought do you accept too quickly without questioning?"}}, {"type": "mentor_note", "content": {"note": "A thought only gains power when you agree with it without testing it."}}, {"type": "video", "content": {"title": "Taking Thoughts Captive", "description": "A breakdown of how to stop blindly believing thoughts and start testing them with discipline and truth."}}, {"type": "pause_reflect", "content": {"question": "Think about your last bad decision.", "context": "Go back to the thought before it.\n\nAsk:\n\nWhat did I believe?\n\nDid I question it?\n\nOr did I just follow it?\n\nThat’s where you lost control."}}, {"type": "journal_prompt", "content": {"prompt": "Write one thought that recently led you in the wrong direction.\n\nThen break it down:\n\nWhat did it say?\n\nWhy did you believe it?\n\nWhat truth would expose it?\n\nIf you can’t answer this clearly, you’re still letting thoughts run you."}}, {"type": "mood_checkin", "content": {"question": "How controlled is your thinking right now?\n\nBe honest—are you thinking, or just reacting?"}}, {"type": "daily_action", "content": {"title": "Test One Thought Today", "action": "Today, you’re not allowed to blindly follow strong thoughts.\n\nWhen one hits:\n\nStop\n\nQuestion it\n\nTest it against truth\n\nDecide if it’s worth following\n\nIf it’s false → reject it immediately."}}, {"type": "mentor_note", "content": {"note": "Uncontrolled thoughts build weak lives.Disciplined thinking builds strength."}}, {"type": "quiz", "content": {"question": "What does taking thoughts captive mean?", "options": [{"text": "Testing thoughts against truth", "is_correct": true}, {"text": "Believing every thought", "is_correct": false}, {"text": "Avoiding reflection", "is_correct": false}, {"text": "Only controlling actions", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Thoughts should be examined before you believe them.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What changes when you control your thoughts?", "options": [{"text": "You become less reactive and more disciplined", "is_correct": true}, {"text": "Thoughts disappear", "is_correct": false}, {"text": "Temptation stops forever", "is_correct": false}, {"text": "Life becomes easy", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 3", "encouragement": "Now you’re starting to get control.\n\nBefore:You had a thought → you followed it.\n\nNow:You have a thought → you decide.\n\nThat’s power.\n\nNext lesson → Managing Cravings Through Truth\n\nThat’s where you deal with urges properly instead of folding under pressure."}}]}, {"number": 4, "title": "Managing Cravings Through Truth", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Cravings Feel Urgent—But They’re Not in Control", "message": "This is where most people lose.\n\nNot because they don’t “know better”…But because cravings feel like commands.\n\n“I need this now.”“I can’t handle this.”“This won’t go away unless I give in.”\n\nThat’s not truth.That’s pressure."}}, {"type": "reading", "content": {"title": "Cravings Lie About Urgency, Power, and Control", "body": "Cravings do three things:\n\nThey create urgency → “Now or never”\n\nThey exaggerate need → “You can’t handle this”\n\nThey remove choice → “You have to do it”\n\nAll of that is false.\n\nHere’s the reality:\n\nCravings are temporary\n\nThey are intense, not permanent\n\nThey are signals, not commands\n\nYou still have control\n\nThe mistake?\n\nYou treat the craving like authority.\n\nThat’s why you fold.\n\nManaging cravings isn’t about ignoring them.It’s about interpreting them correctly and responding with truth + action.\n\nExample:\n\nCraving: “I need this right now.”Truth: “This will pass whether I act or not.”\n\nCraving: “I can’t handle this feeling.”Truth: “I’ve handled worse. This is temporary.”\n\nCraving: “Just one time won’t matter.”Truth: “That’s the same lie that keeps restarting the cycle.”\n\nYou don’t fight cravings emotionally.\n\nYou answer them with truth and then move your body into action.\n\nReflection Question:\n\nWhen cravings hit, do you treat them like a signal… or a command?"}}, {"type": "mentor_note", "content": {"note": "A craving becomes dangerous when it is treated like an order instead of a signal."}}, {"type": "video", "content": {"title": "Managing Cravings Through Truth", "description": "A breakdown of how cravings manipulate urgency and how truth cuts through the pressure so you can respond with control."}}, {"type": "pause_reflect", "content": {"question": "Think about your last strong craving with drug abuse and addiction.", "context": "Ask:\n\nWhat did it tell me?\n\nDid I believe it?\n\nDid I act fast or pause?\n\nThat moment determines everything."}}, {"type": "journal_prompt", "content": {"prompt": "Write one time your drug addiction craving pattern you deal with was like.\n\nThen define:\n\nWhat it says\n\nWhen it shows up\n\nWhat truth shuts it down\n\nIf you don’t have a prepared truth, you’ll keep losing in real time."}}, {"type": "mood_checkin", "content": {"question": "How intense do cravings feel for you right now?\n\nAnd more importantly:Do you feel in control… or reactive?"}}, {"type": "daily_action", "content": {"title": "Answer the Urge Immediately", "action": "Today, when a craving hits:\n\nPause immediately\n\nSay a truth out loud and keep repeating it\n\nMove your body (leave, distract, act)\n\nNo delay. No debate.\n\nSpeed matters."}}, {"type": "mentor_note", "content": {"note": "Cravings don’t disappear because you feel strong.They weaken when you respond correctly."}}, {"type": "quiz", "content": {"question": "What does this lesson teach about cravings?", "options": [{"text": "They control your actions", "is_correct": false}, {"text": "They are final authority", "is_correct": false}, {"text": "They can be answered with truth", "is_correct": true}, {"text": "They remove choice", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Cravings can deminish even when they feel intense.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What actually works when cravings hit?", "options": [{"text": "Panic", "is_correct": false}, {"text": "Ignoring it", "is_correct": false}, {"text": "Truth + action", "is_correct": true}, {"text": "Waiting it out passively", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 4", "encouragement": "This is a turning point.\n\nBefore:Craving → reaction → regret\n\nNow:Craving → truth → controlled response\n\nThat’s how you break cycles.\n\nNext lesson → Replacing Lies with Truth\n\nThat’s where you stop fighting vague pressure and start using precise weapons."}}]}, {"number": 5, "title": "Replacing Lies with Truth", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Vague Thinking Gets Destroyed by Specific Truth", "message": "Right now, you’re still trying to fight precise lies with vague motivation.\n\nThat doesn’t work.\n\n“Stay strong.”“Do better.”“I’ll try harder.”\n\nThat’s weak.\n\nLies are specific.So your response needs to be just as specific."}}, {"type": "reading", "content": {"title": "If You Don’t Answer the Lie Directly, It Wins", "body": "Every destructive drug abusive pattern is backed by a lie.\n\nNot a general feeling — a specific statement you’ve believed.\n\nExamples:\n\n“I need this to feel okay.”\n\n“I can’t handle this.”\n\n“I’ve already failed, so it doesn’t matter.”\n\n“This is just who I am.”\n\n“No one would understand.”\n\nNow here’s the mistake:\n\nYou don’t confront the lie directly.\n\nYou just “hope to do better.”\n\nThat’s why it keeps winning.\n\nReplacing lies with truth means:\n\nIdentify the exact lie\n\nMatch it with exact truth\n\nRepeat it until it sticks\n\nExample:\n\nLie: “I need this to cope.”Truth: “I’ve handled discomfort before. This is temporary.”\n\nLie: “I’ve already failed.”Truth: “One mistake doesn’t define the outcome.”\n\nLie: “This is who I am.”Truth: “Patterns can change. I’m not fixed.”\n\nThis is precision work.\n\nIf you stay vague → you stay stuck.\n\nIf you get precise → you gain control.\n\nReflection Question:\n\nWhat is the ONE lie that keeps repeating in your head?"}}, {"type": "mentor_note", "content": {"note": "Specific lies require specific truth."}}, {"type": "video", "content": {"title": "Replacing Lies with Truth", "description": "A breakdown of how to identify exact lies and destroy them using direct, targeted truth instead of vague motivation."}}, {"type": "pause_reflect", "content": {"question": "Think about your last bad decision.", "context": "What lie did you believe right before it?\n\nNot emotion. Not behavior.\n\nThe exact sentence in your head."}}, {"type": "journal_prompt", "content": {"prompt": "Write it down clearly:\n\nThe lie\n\nWhen it shows up\n\nThe truth that destroys it\n\nIf your “truth” is weak or general, fix it.\n\nMake it sharp."}}, {"type": "mood_checkin", "content": {"question": "How clear is your thinking right now?\n\nAre you operating on truth… or running on unchallenged lies created by drug abuse?"}}, {"type": "daily_action", "content": {"title": "Prepare Your Counterattack", "action": "Pick ONE recurring lie.\n\nWrite the exact truth that destroys it.\n\nMemorize it.\n\nToday, when that lie shows up:\n\nDon’t think about it\n\nDon’t debate it\n\nShut it down immediately with truth"}}, {"type": "mentor_note", "content": {"note": "Truth only works when it is used precisely."}}, {"type": "quiz", "content": {"question": "What is the main practice in this lesson?", "options": [{"text": "Answering lies with specific truth", "is_correct": true}, {"text": "Using vague motivation", "is_correct": false}, {"text": "Ignoring thoughts", "is_correct": false}, {"text": "Avoiding precision", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: General motivation is enough to defeat specific lies.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "Why does precision matter?", "options": [{"text": "It directly exposes and defeats a specific lie or thought", "is_correct": true}, {"text": "It makes things easier", "is_correct": false}, {"text": "It removes effort", "is_correct": false}, {"text": "It avoids thinking", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 5", "encouragement": "Now you’re getting dangerous (in a good way).\n\nBefore:You felt pressure → you reacted\n\nNow:You feel pressure → you identify the lie → you destroy it\n\nThat’s control.\n\nNext lesson → Building Strong Thinking\n\nBecause stopping lies isn’t enough.\n\nYou need to build a mind that produces strength automatically."}}]}, {"number": 6, "title": "Building Strong Thinking", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Stopping Bad Thoughts Isn’t Enough", "message": "Right now you’re still playing defense.\n\nSpot the lie\n\nReplace it\n\nMove on\n\nThat’s good… but it’s not enough.\n\nIf your mind is empty, weak, or undisciplined — bad patterns just come back.\n\nYou don’t just need to block negativityYou need to build strength"}}, {"type": "reading", "content": {"title": "Your Mind Becomes What You Rehearse", "body": "Your brain is not neutral.\n\nIt’s being trained every day by what you:\n\nThink about\n\nRepeat\n\nFocus on\n\nJustify\n\nEntertain\n\nIf you keep replaying:\n\nFear → you become anxious\n\nShame → you become stuck\n\nEscape → you become weak\n\nIf you start building:\n\nTruth → you become clear\n\nDiscipline → you become controlled\n\nPatience → you become stable\n\nGratitude → you become grounded\n\nStrong thinking doesn’t happen randomly.\n\nIt is built through repetition, intention and discipline.\n\nThis is where most people fail:They remove bad thinking… but never replace it with strong thinking.\n\nSo the same space gets filled again with garbage.\n\nYou need to train your mind like a system:\n\nChoose what you think about\n\nRepeat what matters\n\nBuild patterns that support your future\n\nReflection Question:\n\nWhat kind of thinking are you training daily—weak or strong?"}}, {"type": "mentor_note", "content": {"note": "What you repeat internally becomes what you live externally."}}, {"type": "video", "content": {"title": "Building Strong Thinking", "description": "A breakdown of how to stop reacting and start intentionally building a disciplined, stable, and truth-driven mind."}}, {"type": "pause_reflect", "content": {"question": "Be honest:", "context": "What do you think about the most?\n\nProblems\n\nEscape\n\nRegret\n\nFear\n\nOr growth, truth, and solutions?\n\nThat answer tells you exactly why you feel the way you do."}}, {"type": "journal_prompt", "content": {"prompt": "Write ONE thinking pattern you want to build.\n\nThen define:\n\nWhat it looks like daily\n\nWhen you will practice it\n\nWhat triggers you’ll attach it to\n\nIf it’s not specific, you won’t do it."}}, {"type": "mood_checkin", "content": {"question": "Does your mind feel:\n\nControlled\n\nDirected\n\nOr chaotic and reactive?\n\nBe honest."}}, {"type": "daily_action", "content": {"title": "Rehearse Strength", "action": "Pick ONE strong thought today.\n\nExample:\n\n“This feeling will pass.”\n\n“I stay in control.”\n\n“Short-term discomfort = long-term freedom.”\n\nRepeat it intentionally throughout the day.\n\nNot once. Multiple times.\n\nYou’re installing a new system."}}, {"type": "mentor_note", "content": {"note": "A strong mind is built by principles it practices daily."}}, {"type": "quiz", "content": {"question": "What does this lesson focus on?", "options": [{"text": "Building strong principled mindset", "is_correct": true}, {"text": "Only stopping bad thoughts", "is_correct": false}, {"text": "Ignoring the mind", "is_correct": false}, {"text": "Avoiding discipline", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: A strong mental life must be built intentionally.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What shapes your thinking long term?", "options": [{"text": "Repetition and focus", "is_correct": true}, {"text": "Random thoughts", "is_correct": false}, {"text": "Avoiding thinking", "is_correct": false}, {"text": "Waiting for motivation", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 6", "encouragement": "Now you’re leveling up.\n\nBefore:You were reacting to thoughts.\n\nNow:You’re building your mind like a system.\n\nThat’s leverage.\n\nNext lesson → Emotional Control\n\nBecause if your emotions still control you, all this thinking work collapses under pressure."}}]}, {"number": 7, "title": "Developing Emotional Maturity", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Your Emotions Are Real—But They Are Not in Charge", "message": "This is where a lot of people give in.\n\nNot because they don’t know the truth.But because they feel something strongly… and follow it instantly.\n\n“I feel stressed” → escape\n\n“I feel alone” → bad decision\n\n“I feel angry” → impulsive reaction\n\nThat’s not maturity.That’s emotional control running your life."}}, {"type": "reading", "content": {"title": "Strong People Feel Emotions—They Just Don’t Obey Them Blindly", "body": "Let’s get this straight:\n\nEmotions are not the problem.\n\nBlind obedience to emotions is.\n\nEmotions are:\n\nSignals\n\nReactions\n\nInformation\n\nThey are NOT:\n\nCommands\n\nTruth\n\nFinal decisions\n\nEmotional maturity means:\n\nYou feel it\n\nYou name it\n\nYou slow it down\n\nYou decide based on truth—not feeling\n\nExample:\n\nFeeling: “I feel overwhelmed”Weak response: escapeStrong response: pause + break it down + act intentionally\n\nFeeling: “I feel like giving up”Weak response: quitStrong response: recognize discouragement + keep moving\n\nFeeling: “I feel like I need relief now”Weak response: reactStrong response: identify craving + apply truth\n\nAddiction thrives when emotions take control.\n\nRecovery strengthens when emotions are managed, not obeyed.\n\nReflection Question:\n\nWhich emotion controls your decisions the most?"}}, {"type": "mentor_note", "content": {"note": "Maturity is not feeling less.It is being ruled less by what you feel."}}, {"type": "video", "content": {"title": "Developing Emotional Maturity", "description": "A breakdown of how to handle emotions without letting them control your thinking, decisions, and recovery."}}, {"type": "pause_reflect", "content": {"question": "Think about your last bad decision.", "context": "What were you feeling right before it?\n\nStress\n\nAnger\n\nLoneliness\n\nBoredom\n\nShame\n\nThat emotion didn’t force you.\n\nYou followed it.\n\nThat’s the gap you fix."}}, {"type": "journal_prompt", "content": {"prompt": "Write ONE emotion that keeps messing you up.\n\nThen define:\n\nWhen it shows up\n\nWhat it pushes you to do\n\nWhat a controlled response looks like\n\nIf you don’t define it, you’ll keep repeating it."}}, {"type": "mood_checkin", "content": {"question": "Right now—are you:\n\nCalm and controlled\n\nOr reacting to how you feel?\n\nBe honest."}}, {"type": "daily_action", "content": {"title": "Slow the Emotion Down", "action": "Today, when you feel something strong:\n\nPause immediately\n\nName the emotion (“This is stress”)\n\nDon’t act yet\n\nDecide based on truth\n\nThat pause is everything.\n\nWithout it → reactionWith it → control"}}, {"type": "mentor_note", "content": {"note": "A stable life is built by slowing emotion under control."}}, {"type": "quiz", "content": {"question": "What is emotional maturity?", "options": [{"text": "Ignoring emotions", "is_correct": false}, {"text": "Following every feeling", "is_correct": false}, {"text": "Feeling emotions but controlling responses with truth", "is_correct": true}, {"text": "Avoiding emotional situations", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Emotions should automatically control your decisions.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "Why does emotional control matter?", "options": [{"text": "Because emotions can take over decisions if unmanaged", "is_correct": true}, {"text": "Because emotions don’t matter", "is_correct": false}, {"text": "Because truth is optional", "is_correct": false}, {"text": "Because recovery removes feelings", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 7", "encouragement": "Now you’re getting control on another level.\n\nBefore:Emotion → reaction → regret\n\nNow:Emotion → pause → control → decision\n\nThat’s discipline.\n\nFinal lesson next → Long-Term Freedom & Stability\n\nThat’s where we lock everything in so you don’t keep restarting."}}]}, {"number": 8, "title": "Long-Term Freedom and Stability", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "This Isn’t About Winning Today—It’s About Not Falling Back Tomorrow", "message": "You’ve made progress before.\n\nThen you lost it.\n\nWhy?\n\nBecause you treated recovery like a moment, not a system.\n\nThis lesson fixes that."}}, {"type": "reading", "content": {"title": "Freedom That Isn’t Supported Will Collapse", "body": "Short-term wins are easy.\n\nMotivation spike\n\nClean for a few days\n\nFeel in control\n\nThen what?\n\nNo structure → no stability → back to old patterns.\n\nHere’s the truth:\n\nFreedom is not something you reach.It’s something you maintain.\n\nLong-term stability is built through:\n\nRepeated truth\n\nDaily discipline\n\nEmotional control\n\nStructured habits\n\nStrong thinking patterns\n\nDependence on your faith\n\nConsistent routines\n\nMost people fail because they rely on:\n\nMood\n\nMotivation\n\n“Feeling ready”\n\nThat’s unstable.\n\nYou need systems.\n\nDaily structure beats motivation every time.\n\nIf your recovery isn’t supported → it won’t last.\n\nReflection Question:\n\nWhat part of your life is still unstable and could pull you back?"}}, {"type": "mentor_note", "content": {"note": "Freedom becomes permanent when it is supported daily."}}, {"type": "video", "content": {"title": "Long-Term Freedom and Stability", "description": "A breakdown of how to stop relying on short-term wins and start building a stable system that protects your future."}}, {"type": "pause_reflect", "content": {"question": "Look at your current support setup.", "context": "Be honest:\n\nDo you have structure?\n\nDo you have habits?\n\nDo you have systems?\n\nOr are you just “trying your best”?\n\nThat’s the difference."}}, {"type": "journal_prompt", "content": {"prompt": "Write ONE change that would make your recovery more stable.\n\nNot 10 things.\n\nOne.\n\nThen define:\n\nWhy it matters\n\nWhen you’ll do it\n\nHow you’ll stay consistent\n\nIf it’s not specific → it won’t happen."}}, {"type": "mood_checkin", "content": {"question": "How stable does your recovery feel right now?\n\nSolid\n\nShaky\n\nCompletely reactive\n\nDon’t lie to yourself."}}, {"type": "daily_action", "content": {"title": "Build for Tomorrow, Not Just Today", "action": "Do ONE thing today that helps your future self:\n\nSet a routine\n\nPrepare a response plan\n\nRemove a trigger\n\nStrengthen a habit\n\nThis isn’t about today’s comfort.\n\nThis is about tomorrow’s control."}}, {"type": "mentor_note", "content": {"note": "Stability is built slowly—but lost quickly if ignored."}}, {"type": "quiz", "content": {"question": "What does long-term freedom require?", "options": [{"text": "Motivation", "is_correct": false}, {"text": "Luck", "is_correct": false}, {"text": "Structure and consistent support", "is_correct": true}, {"text": "Waiting until you feel ready", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Stability is built intentionally over time.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What actually creates lasting recovery?", "options": [{"text": "Short bursts of effort", "is_correct": false}, {"text": "Repeated daily discipline and structure", "is_correct": true}, {"text": "Avoiding responsibility", "is_correct": false}, {"text": "Waiting for change", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 10", "encouragement": "Now here’s the reality:\n\nMost people restart over and over because they never build stability.\n\nYou just did the work most people avoid:\n\nYou fixed your thinking\n\nYou took control of your thoughts\n\nYou learned to handle cravings\n\nYou built emotional discipline\n\nYou created structure\n\nThat’s how you stop looping.\n\nNext → Chapter 10 (relationships, healing, real life impact)\n\nBut understand this:\n\nIf you don’t apply what you just learned daily…You will end up back at the start.\n\nExecution is everything now."}}]}]}, {"number": 10, "title": "The Tree of Life", "description": "Chapter 10 shifts the focus from simply overcoming addiction to building a life that is deeply rooted in spiritual growth, healing, and purpose. Rather than centering on one specific faith tradition, this chapter explores how drawing closer to the Divine, living according to the values of your faith, and developing a healthy spiritual foundation can support lasting recovery.\n\nThe goal of this chapter is to help you move beyond defensive recovery into a life rooted in faith, shaped by grace, strengthened through personal growth, and reflected in the way you live each day.", "lessons": [{"number": 1, "title": "The Source of True Life", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Lasting Healing Begins by Turning to the Right Source", "message": "Recovery is about more than breaking free from addiction.\n\nIt is about discovering your true purpose beyond drug abuse and addiction, what your gifts are in life, your personal expression.\n\nLasting peace cannot be found through temporary substitutes. Instead, it is found by drawing closer to the Divine and living according to the values of one''s faith.\n\nThis chapter begins by exploring the importance of building your recovery on a source that can truly sustain you."}}, {"type": "reading", "content": {"title": "A Fulfilling Life Comes from a Strong Spiritual Foundation", "body": "Addiction often leads people to search for comfort, peace, acceptance, or relief in places that cannot truly satisfy them.\n\nSome look to misusing or abusing drugs and substances whether legal or illegal.\n\nOthers rely on financial success, bad relationships, possessions, distractions, or unhealthy habits.\n\nWhile these things may provide temporary relief, they cannot provide life fulfillment in itself.\n\nMany faith traditions teach that true life begins when we reconnect with the Divine and allow our faith to become the foundation of our lives.\n\nThe source of our progress and development is not found in temporary pleasures but in a growing relationship with the One we trust and worship.\n\nRecovery becomes deeper when faith is no longer treated as something we turn to only during difficult moments.\n\nInstead, it becomes the daily source of wisdom, strength, hope, and direction.\n\nAs we become rooted in our faith, we begin replacing temporary substitutes with something eternal.\n\nHealing grows stronger when we draw life from a source that does not disappear when circumstances become difficult.\n\nReflection Question:\n\nWhere have you been searching for peace, comfort, or purpose instead of seeking them through your faith?"}}, {"type": "mentor_note", "content": {"note": "Temporary solutions satisfy for a moment.\n\nA lasting spiritual foundation strengthens a lifetime."}}, {"type": "video", "content": {"title": "The Source of True Life", "description": "A mentor-led lesson exploring why lasting recovery is strengthened when our lives are rooted in the Divine, guided by our faith, and built on a lasting spiritual foundation."}}, {"type": "pause_reflect", "content": {"question": "Think about the places where you have searched for lasting peace.", "context": "Reflect on whether you have looked for fulfillment through:\n\nSubstances.\n\nRelationships.\n\nSuccess.\n\nPossessions.\n\nDistractions.\n\nTemporary pleasure.\n\nYour relationship with the Divine.\n\nWhich source has truly brought lasting peace?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about one place where you have looked for life or fulfillment that ultimately left you feeling empty.\n\nThen describe:\n\nWhat you were hoping to find.\n\nWhy did it not last.\n\nHow building a stronger relationship with the Divine could change your recovery."}}, {"type": "mood_checkin", "content": {"question": "How connected do you feel to the spiritual foundation of your faith today?"}}, {"type": "daily_action", "content": {"title": "Return to the Right Source", "action": "Spend a few quiet moments in prayer or personal reflection according to your faith.\n\nIdentify one unhealthy source of comfort or security that has influenced your life.\n\nChoose one practical way to strengthen your connection with the Divine today instead."}}, {"type": "mentor_note", "content": {"note": "Build a life that is able to stand the test of time, difficulties and challenges, a life rooted in faith."}}, {"type": "quiz", "content": {"question": "According to this lesson, lasting recovery is strengthened when:", "options": [{"text": "We depend only on temporary sources of comfort.", "is_correct": false}, {"text": "We build our lives on a lasting spiritual foundation guided by our faith.", "is_correct": true}, {"text": "We avoid spiritual growth.", "is_correct": false}, {"text": "We focus only on changing our behavior.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Temporary sources of comfort can replace a lasting spiritual foundation.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What is the main focus of this lesson?", "options": [{"text": "A solid foundation through the Divine and the guidance of your faith.", "is_correct": true}, {"text": "Managing behavior alone.", "is_correct": false}, {"text": "Avoiding personal responsibility.", "is_correct": false}, {"text": "Depending only on willpower.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 1.", "encouragement": "Today you learned that lasting recovery is built on more than resisting addiction—it is strengthened by drawing life, wisdom, and hope from a pure spiritual foundation. As you continue growing in your faith and seeking the guidance of the Divine, you build a stronger foundation for healing, purpose, and lifelong recovery.\n\nIn the next lesson, we will explore Returning to Your Intended Purpose and discover how recovery becomes more meaningful when it is directed toward the life your faith calls you to live."}}]}, {"number": 2, "title": "Returning to Your Intended Purpose", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Recovery Is More Than Escaping Addiction—It Is Returning to Your Purpose", "message": "Recovery becomes more meaningful when it is about more than avoiding destructive behaviors.\n\nMany faith traditions teach that every person has inherent worth, purpose, and the ability to grow into the life they were created and designed to live.\n\nThis lesson explores how recovery becomes stronger when we stop focusing only on surviving and begin rebuilding a life guided by purpose, wisdom, and the values of our faith."}}, {"type": "reading", "content": {"title": "Purpose Gives Direction to Healing", "body": "Many people define recovery by what they are leaving behind.\n\nThey focus on stopping unhealthy behaviors, avoiding relapse, or escaping the consequences of addiction.\n\nWhile these are important goals, they are only part of the journey.\n\nLasting recovery also asks:\n\nWhat kind of person am I becoming?\n\nWhat values will guide my life?\n\nHow can my faith shape my future?\n\nHow can I use my life to serve others and live with purpose?\n\nHealing is not simply about repairing what has been damaged.\n\nIt is about returning to a life rooted in truth, compassion, responsibility, and spiritual growth.\n\nPurpose gives recovery direction.\n\nInstead of merely trying not to fail, we begin intentionally building a life filled with meaning, healthy relationships, service to self, others, and hope.\n\nRecovery becomes stronger when we pursue something greater than simply avoiding addiction.\n\nA life guided by purpose creates lasting motivation to continue growing.\n\nReflection Question:\n\nWhat purpose or calling do you believe your recovery is helping you move toward?"}}, {"type": "mentor_note", "content": {"note": "Healing becomes more meaningful when it leads toward purpose, not only away from pain."}}, {"type": "video", "content": {"title": "Returning to Your Intended Purpose", "description": "A mentor-led lesson exploring how recovery becomes stronger when it is guided by purpose, spiritual growth, and the values of your faith."}}, {"type": "pause_reflect", "content": {"question": "Think about the future you hope to build.", "context": "Reflect on:\n\nYour character.\n\nYour relationships.\n\nYour contribution to others.\n\nYour spiritual life.\n\nYour personal growth.\n\nThe values you want to live by.\n\nWhich area feels most important right now?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about one area where you want your recovery to become more than simply avoiding addiction.\n\nThen describe:\n\nThe kind of person you hope to become.\n\nThe purpose you want to pursue.\n\nHow your faith can help guide that journey."}}, {"type": "mood_checkin", "content": {"question": "How purposeful does your recovery feel today?"}}, {"type": "daily_action", "content": {"title": "Choose One Purposeful Step", "action": "Spend a few quiet moments in prayer or personal reflection according to your faith.\n\nChoose one action today that reflects the person you want to become rather than the person addiction tried to make you.\n\nCommit to completing that action before the day ends."}}, {"type": "mentor_note", "content": {"note": "Recovery becomes stronger when your future is guided by purpose instead of fear."}}, {"type": "quiz", "content": {"question": "According to this lesson, lasting recovery is strengthened when:", "options": [{"text": "It focuses only on avoiding relapse.", "is_correct": false}, {"text": "It is guided by purpose, spiritual growth, and the values of your faith.", "is_correct": true}, {"text": "It ignores personal growth.", "is_correct": false}, {"text": "It avoids responsibility.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Recovery becomes more meaningful when it moves toward purpose instead of only away from addiction.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What gives recovery positive direction?", "options": [{"text": "Focusing only on past mistakes.", "is_correct": false}, {"text": "Living with purpose and allowing your faith to guide your future.", "is_correct": true}, {"text": "Waiting for motivation.", "is_correct": false}, {"text": "Avoiding long-term goals.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 2.", "encouragement": "Today you learned that lasting recovery is about more than leaving addiction behind—it is about returning to a life filled with purpose, meaning, and hope. As you continue allowing your faith to shape your character, decisions, and future, you strengthen the foundation for lasting healing and become the person you were created to be.\n\nIn the next lesson, we will explore The Gift of Salvation and Spiritual Renewal, discovering how spiritual renewal brings hope, transforms identity, and supports lifelong recovery."}}]}, {"number": 3, "title": "The Gift of Salvation and Spiritual Renewal", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Lasting Recovery Begins with Inner Renewal", "message": "Recovery can improve behavior, restore relationships, and rebuild daily life.\n\nFaith and traditions teach that our deepest need is not only outward change—it is inner renewal and reconciliation with your faith.\n\nThis lesson explores how salvation and spiritual renewal provide hope, restore identity, and strengthen the foundation for complete healing."}}, {"type": "reading", "content": {"title": "Spiritual Renewal Changes More Than Behavior", "body": "Many people begin recovery hoping simply to stop harmful behaviors.\n\nWhile this is an important goal, lasting transformation reaches much deeper.\n\nSalvation is a gift of divine mercy that restores our relationship with our faith and begins the work of renewing our hearts, minds, and lives.\n\nSpiritual renewal reminds us that:\n\nWe are more than our past mistakes.\n\nHealing is possible even after failure.\n\nForgiveness opens the door to hope.\n\nOur identity is not defined by addiction.\n\nA renewed relationship with our faith gives meaning and purpose.\n\nRecovery becomes stronger when we understand that healing is not only about managing symptoms.\n\nIt is about becoming a new person through faith, spiritual growth, and a restored relationship with the One we trust and worship.\n\nAs our inner lives are renewed, our choices, relationships, and daily actions begin reflecting that transformation.\n\nLasting change grows from the inside outward.\n\nReflection Question:\n\nHow has your faith changed the way you see yourself and your future?"}}, {"type": "mentor_note", "content": {"note": "The deepest transformation begins within the heart before it becomes visible in everyday life."}}, {"type": "video", "content": {"title": "The Gift of Salvation and Spiritual Renewal", "description": "A mentor-led lesson exploring how salvation, spiritual renewal, and a restored relationship with the Divine provide the foundation for lasting recovery and personal transformation."}}, {"type": "pause_reflect", "content": {"question": "Think about how your faith has influenced your recovery.", "context": "Reflect on:\n\nYour identity.\n\nYour hope.\n\nYour understanding of forgiveness.\n\nYour relationship with the Divine.\n\nYour purpose.\n\nYour future.\n\nWhich area has changed the most?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about what spiritual renewal means to you.\n\nThen describe:\n\nHow your faith has changed your understanding of recovery.\n\nOne area where you still desire deeper healing.\n\nHow a renewed relationship with the Divine can strengthen your future."}}, {"type": "mood_checkin", "content": {"question": "How spiritually renewed do you feel today?"}}, {"type": "daily_action", "content": {"title": "Reflect on New Beginnings", "action": "Spend a few quiet moments in prayer or personal reflection according to your faith.\n\nThink about one way your life has already begun to change.\n\nThen choose one practical action today that reflects the renewed person you are becoming through your faith."}}, {"type": "mentor_note", "content": {"note": "When the heart is renewed, hope begins shaping every step that follows."}}, {"type": "quiz", "content": {"question": "According to this lesson, spiritual renewal:", "options": [{"text": "Focuses only on changing outward behavior.", "is_correct": false}, {"text": "Brings inner spiritual transformation that is the essence of freedom.", "is_correct": true}, {"text": "Removes the need for personal growth.", "is_correct": false}, {"text": "Happens without faith or commitment.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Spiritual renewal can change the way you see yourself, your future, and your recovery.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What is one purpose of salvation and spiritual renewal in this lesson?", "options": [{"text": "To restore hope, identity, and a relationship with our faith.", "is_correct": true}, {"text": "To eliminate every struggle immediately.", "is_correct": false}, {"text": "To replace responsibility.", "is_correct": false}, {"text": "To focus only on outward behavior.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 3.", "encouragement": "Today you learned that lasting recovery involves more than changing behavior—it begins with inner renewal. As your relationship with your Creator grows stronger and your identity becomes rooted in faith rather than addiction, you develop a foundation for lasting hope, healing, and transformation. Every step you take in spiritual growth strengthens the life you are building and reminds you that your future is not defined by your past.\n\nIn the next lesson, we will explore Receiving Grace, discovering how accepting divine mercy strengthens perseverance, overcomes shame, and supports lifelong recovery."}}]}, {"number": 4, "title": "Receiving Grace", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Grace Becomes Life-Changing When It Is Truly Received", "message": "Many people believe in grace but still live as though they must earn acceptance, prove their worth, or hide every failure.\n\nBelief systems teach that grace is more than an idea. It is the life force of compassion, mercy, and sometimes seemingly undeserved favor of the Creator that helps us continue growing, even when we stumble.\n\nThis lesson explores what it means to truly receive grace and how it strengthens complete freedom from drug abuse and addiction."}}, {"type": "reading", "content": {"title": "Receiving Grace Replaces Shame with Hope", "body": "Grace is not permission to ignore unhealthy choices.\n\nNeither is it something that must be earned.\n\nGrace is freely given and invites us into healing, growth, and restoration, which is a journey of discovery of our God, who we are, and also understanding, loving and accepting others .\n\nReceiving grace means allowing divine mercy to reshape the way we respond to failure.\n\nInstead of hiding mistakes or believing we are beyond hope, we learn to:\n\nAdmit our failures honestly.\n\nAccept forgiveness.\n\nLearn from our mistakes.\n\nContinue growing instead of giving up.\n\nTrust that healing is possible.\n\nMany people understand grace with their minds but struggle to receive it in their hearts.\n\nThey continue carrying unnecessary shame, believing they must become perfect before they are worthy of healing.\n\nGrace reminds us that recovery is strengthened by honesty, humility, and perseverance—not perfection.\n\nAs we receive grace, we become more willing to face the truth, seek help, and continue moving forward with hope.\n\nReflection Question:\n\nWhere do you find it most difficult to receive grace in your recovery journey?"}}, {"type": "mentor_note", "content": {"note": "Grace becomes life-changing when it moves from something you understand to something you truly accept."}}, {"type": "video", "content": {"title": "Receiving Grace", "description": "A mentor-led lesson exploring how receiving divine grace helps overcome shame, strengthens hope, and supports lasting healing throughout recovery."}}, {"type": "pause_reflect", "content": {"question": "Think about the areas where you are hardest on yourself.", "context": "Reflect on:\n\nPast mistakes.\n\nFeelings of shame.\n\nFear of failure.\n\nDifficulty accepting forgiveness.\n\nFeeling unworthy of healing.\n\nWhich area do you most need to place in the hands of God?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about one area where you struggle to receive grace.\n\nThen describe:\n\nWhy it has been difficult.\n\nHow continuing to carry shame has affected your recovery.\n\nHow accepting divine grace could help you continue moving forward."}}, {"type": "mood_checkin", "content": {"question": "How open do you feel to receiving grace today?"}}, {"type": "daily_action", "content": {"title": "Receive Grace and Keep Moving Forward", "action": "Spend a few quiet moments in prayer or personal reflection according to your faith.\n\nIdentify one mistake or regret you have continued carrying.\n\nEntrust it to the Divine, accept the possibility of forgiveness and healing, and choose one practical step that reflects hope rather than shame."}}, {"type": "mentor_note", "content": {"note": "Grace does not erase responsibility.\n\nIt gives you the strength to continue growing despite your imperfections."}}, {"type": "quiz", "content": {"question": "According to this lesson, grace:", "options": [{"text": "Must be earned through perfect behavior.", "is_correct": false}, {"text": "Is received through faith and supports healing, growth, and hope.", "is_correct": true}, {"text": "Removes personal responsibility.", "is_correct": false}, {"text": "Excuses unhealthy choices.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Receiving grace helps people move beyond shame and continue growing.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "Why is receiving grace important in recovery?", "options": [{"text": "It helps us continue the path of healing without becoming trapped by shame or hopelessness.", "is_correct": true}, {"text": "It removes the need for honesty.", "is_correct": false}, {"text": "It guarantees immediate change.", "is_correct": false}, {"text": "It replaces personal growth.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 4.", "encouragement": "Today you learned that grace is more than a belief—it is something to be received and lived. As you allow the compassion and mercy of your Creator to replace shame with hope, you strengthen your ability to continue growing after setbacks. Recovery becomes more sustainable when you accept grace, remain honest about your struggles, and keep moving forward with faith, perseverance, and renewed purpose.\n\nIn the next lesson, we will explore Spiritual Growth and Healing, discovering how lasting recovery is strengthened as healing and spiritual maturity grow together."}}]}, {"number": 5, "title": "Spiritual Growth and Healing", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Healing Is Not Only About Overcoming Addiction—It Is Also About Growing", "message": "Recovery often begins with stopping destructive behaviors.\n\nAs healing continues, however, a new question emerges:\n\nWho am I becoming?\n\nOur faith and traditions teach that true healing involves ongoing spiritual growth. It is not only about recovering from the past, but about becoming a wiser, stronger, and more compassionate person through the guidance of one''s faith.\n\nThis lesson explores how spiritual growth and healing work together to create lasting recovery."}}, {"type": "reading", "content": {"title": "Growth and Healing Strengthen One Another", "body": "Many people begin recovery in survival mode.\n\nTheir focus is on resisting temptation, avoiding relapse, and rebuilding stability.\n\nThese are important first steps.\n\nHowever, lasting recovery requires more than simply surviving.\n\nMany faith traditions teach that healing is accompanied by spiritual growth.\n\nAs we continue growing in faith, we also grow in:\n\nWisdom.\n\nHumility.\n\nPatience.\n\nSelf-discipline.\n\nCompassion.\n\nHonesty.\n\nPerseverance.\n\nTrust in the Divine.\n\nOver time, recovery becomes less about escaping addiction and more about becoming the person we are meant to be.\n\nSpiritual growth gives recovery direction.\n\nHealing becomes deeper when we no longer see ourselves only as people recovering from past wounds, but as people continually growing in character, purpose, and faith.\n\nGrowth is not measured by perfection.\n\nIt is measured by steady progress.\n\nEvery healthy decision, every act of faith, and every moment of honesty strengthens both healing and personal transformation.\n\nReflection Question:\n\nIn what area of your life do you most want to continue growing as you heal?"}}, {"type": "mentor_note", "content": {"note": "Healing restores what was damaged.\n\nGrowth develops what is possible."}}, {"type": "video", "content": {"title": "Spiritual Growth and Healing", "description": "A mentor-led lesson exploring how spiritual growth strengthens healing and how lasting recovery develops through faith, character, and continual personal growth."}}, {"type": "pause_reflect", "content": {"question": "Think about your recovery today.", "context": "Where do you most need growth?\n\nReflect on:\n\nYour character.\n\nYour relationships.\n\nYour patience.\n\nYour self-discipline.\n\nYour honesty.\n\nYour faith.\n\nYour emotional resilience.\n\nWhich area needs the most attention?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about one area where you want spiritual growth to become part of your healing.\n\nThen describe:\n\nWhy this area is important.\n\nWhat healthy changes you hope to see.\n\nHow your faith can help you continue growing over time."}}, {"type": "mood_checkin", "content": {"question": "How much do you feel you are growing—not simply coping—today?"}}, {"type": "daily_action", "content": {"title": "Choose Growth Today", "action": "Spend a few quiet moments in prayer or personal reflection according to your faith.\n\nIdentify one area where you usually seek immediate relief instead of long-term growth.\n\nChoose one practical action today that strengthens your character and supports lasting healing."}}, {"type": "mentor_note", "content": {"note": "Recovery becomes lasting when healing is accompanied by continual growth."}}, {"type": "quiz", "content": {"question": "According to this lesson, lasting healing is strengthened by:", "options": [{"text": "Only avoiding addiction.", "is_correct": false}, {"text": "Spiritual growth, personal development, and the guidance of your faith.", "is_correct": true}, {"text": "Ignoring character development.", "is_correct": false}, {"text": "Waiting for life to become easier.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Spiritual growth is an important part of lasting recovery.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What does this lesson encourage?", "options": [{"text": "Remaining focused only on survival.", "is_correct": false}, {"text": "Growing in character, faith, and wisdom as healing continues.", "is_correct": true}, {"text": "Avoiding personal responsibility.", "is_correct": false}, {"text": "Expecting instant transformation.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 5.", "encouragement": "Today you learned that recovery is not only about overcoming addiction—it is also about becoming the person you are capable of being. As healing and spiritual growth continue together, you build a life marked by wisdom, resilience, compassion, and hope. Every step you take toward growth strengthens your recovery and helps create a future rooted in lasting purpose and the guidance of your faith.\n\nIn the next lesson, we will explore Living a Fruitful Life, discovering how lasting recovery becomes visible through the way you think, serve, build relationships, and positively influence the lives of others."}}]}, {"number": 6, "title": "Living a Fruitful Life", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Recovery Is Not Complete Until It Begins Producing Good Fruit", "message": "Recovery is about more than avoiding addiction.\n\nIt is also about becoming someone whose life positively influences others.\n\nOur faith teaches that a healthy spiritual life naturally produces visible qualities such as compassion for others, honesty in action, patience, all forms of generosity, wisdom, and faithful service.\n\nThis lesson explores how lasting recovery becomes visible through the way we live each day."}}, {"type": "reading", "content": {"title": "A Healthy Inner Life Produces Healthy Outward Living", "body": "A fruitful life is not measured by outward success alone.\n\nIt is revealed through the steady growth of character, purpose, and the positive influence we have on others.\n\nWhen our lives are rooted in our God and guided by the values of our faith, healthy fruit naturally begins to appear.\n\nThis fruit may be seen through:\n\nGreater patience.\n\nHonest relationships.\n\nCompassion toward others.\n\nSelf-control.\n\nConsistency.\n\nHumility.\n\nFaithfulness.\n\nService.\n\nHope during difficult times.\n\nAddiction often causes life to become focused on survival and immediate relief.\n\nRecovery invites us to look beyond ourselves.\n\nAs healing continues, we begin asking not only,\n\n\"How can I stay free?\"\n\nbut also,\n\n\"How can my life become a source of hope, encouragement, and support for others?\"\n\nA fruitful life does not require perfection.\n\nIt grows gradually through faithful daily choices.\n\nAs your character develops, your recovery becomes visible in the way you think, speak, serve, and care for those around you.\n\nReflection Question:\n\nWhat kind of positive influence do you hope your recovery will have on others?"}}, {"type": "mentor_note", "content": {"note": "A life rooted in truth becomes visible through the good it brings into the lives of others."}}, {"type": "video", "content": {"title": "Living a Fruitful Life", "description": "A mentor-led lesson exploring how lasting recovery becomes visible through character, healthy relationships, compassionate service, and a life guided by the values of your faith."}}, {"type": "pause_reflect", "content": {"question": "What qualities are beginning to grow in your life?", "context": "Reflect on:\n\nPatience.\n\nCompassion.\n\nHonesty.\n\nSelf-control.\n\nFaithfulness.\n\nKindness.\n\nService.\n\nHope.\n\nWhich quality do you most want to strengthen?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about one quality you want your recovery to produce more clearly.\n\nThen describe:\n\nWhy this quality matters.\n\nHow it could positively influence your life and the lives of others.\n\nWhat daily practice could help it continue growing."}}, {"type": "mood_checkin", "content": {"question": "How much do you feel your recovery is producing positive growth in your life today?"}}, {"type": "daily_action", "content": {"title": "Let Your Recovery Bless Someone Else", "action": "Spend a few quiet moments in prayer or personal reflection according to your faith.\n\nThen intentionally perform one act of kindness, encouragement, or service today that reflects the healthier person you are becoming.\n\nNotice how choosing to bless someone else also strengthens your own recovery."}}, {"type": "mentor_note", "content": {"note": "The healthiest recovery is not only seen in what you leave behind, but in the good you begin creating."}}, {"type": "quiz", "content": {"question": "According to this lesson, a fruitful life is:", "options": [{"text": "Measured only by outward success.", "is_correct": false}, {"text": "Seen through growing character and a positive influence on others.", "is_correct": true}, {"text": "Focused only on personal survival.", "is_correct": false}, {"text": "Achieved through perfection.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Lasting recovery should eventually become visible through the way you live and treat others.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What question does this lesson encourage us to ask?", "options": [{"text": "How can my life become a source of hope, encouragement, and support for others?", "is_correct": true}, {"text": "How can I hide my struggles better?", "is_correct": false}, {"text": "How can I avoid helping others?", "is_correct": false}, {"text": "How can I focus only on myself?", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 6.", "encouragement": "Today you learned that lasting recovery is not only about breaking free from addiction—it is also about living a life that reflects growth, compassion, and purpose. As your character develops and your faith continues to guide your choices, your recovery becomes visible through the positive influence you have on those around you. Every act of kindness, honesty, and service is evidence of the healthier life you are building.\n\nIn the final lesson of this chapter, we will explore Walking in Newness of Life, bringing together everything you have learned as you continue living each day with renewed purpose, lasting hope, and the guidance of your faith."}}]}, {"number": 7, "title": "Walking in Newness of Life", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Recovery Is Meant to Be Lived, Not Just Understood", "message": "Recovery is not simply about learning new ideas.\n\nIt is about living differently each day.\n\nSpiritual renewal becomes visible through the way we think, speak, choose, and relate to others. New life is not only something we hope for—it is something we practice.\n\nThis final lesson brings together everything you have learned throughout this chapter and encourages you to continue walking forward with renewed purpose, hope, and faith."}}, {"type": "reading", "content": {"title": "New Life Is Revealed Through Daily Living", "body": "Walking in newness of life means choosing not to let your past define your future.\n\nIt does not mean pretending your struggles never happened.\n\nInstead, it means recognizing that addiction no longer has to determine your identity or the direction of your life.\n\nMany faith traditions teach that as we grow in faith, we begin living differently.\n\nThis new way of living can be seen through:\n\nHealthier daily choices.\n\nGreater self-control.\n\nHonest relationships.\n\nCompassion toward others.\n\nWise decision-making.\n\nA deeper trust in the Divine.\n\nLiving according to the values of our faith.\n\nContinuing to grow despite setbacks.\n\nRecovery is not measured by never facing temptation again.\n\nIt is measured by the direction you continue choosing.\n\nEvery day offers another opportunity to leave unhealthy patterns behind and strengthen the purpose driven life you are building.\n\nAs your actions begin reflecting your renewed values, your recovery becomes visible—not only to you, but also to those around you.\n\nWalking in newness of life means continuing to move forward with courage, humility, perseverance, and hope.\n\nReflection Question:\n\nWhat is one area of your life where you most want your new direction to become visible?"}}, {"type": "mentor_note", "content": {"note": "A new life becomes visible through the direction you consistently choose."}}, {"type": "video", "content": {"title": "Walking in Newness of Life", "description": "A mentor-led conclusion to the chapter exploring how renewed purpose, healthy choices, and the guidance of your faith become visible through everyday living."}}, {"type": "pause_reflect", "content": {"question": "Think about the person you are becoming.", "context": "Reflect on:\n\nYour daily choices.\n\nYour routines.\n\nYour relationships.\n\nYour attitude toward challenges.\n\nYour spiritual life.\n\nYour future.\n\nWhere do you already see signs of positive change?"}}, {"type": "journal_prompt", "content": {"prompt": "Write about one clear sign that your life is moving in a healthier direction.\n\nThen describe:\n\nWhat has changed.\n\nWhat habits have helped.\n\nHow your faith continues to strengthen your recovery.\n\nWhat you want to keep building in the months ahead."}}, {"type": "mood_checkin", "content": {"question": "How much does your daily life reflect the healthier person you are becoming?"}}, {"type": "daily_action", "content": {"title": "Walk in Your New Direction", "action": "Spend a few quiet moments in prayer or personal reflection according to your faith.\n\nChoose one action today that reflects your new direction rather than your old habits.\n\nLet that decision become another step toward the life you are building."}}, {"type": "mentor_note", "content": {"note": "Your future is shaped less by who you were and more by the direction you choose to walk today."}}, {"type": "quiz", "content": {"question": "According to this lesson, walking in newness of life means:", "options": [{"text": "Pretending the past never happened.", "is_correct": false}, {"text": "Living each day according to your renewed values and the guidance of your faith.", "is_correct": true}, {"text": "Avoiding all responsibility.", "is_correct": false}, {"text": "Expecting recovery to become effortless.", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Recovery is demonstrated through the direction of your daily life rather than by perfection.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What best reflects a life of ongoing recovery?", "options": [{"text": "Returning to old destructive patterns.", "is_correct": false}, {"text": "Consistently choosing healthier actions, guided by faith and hope.", "is_correct": true}, {"text": "Waiting for change without taking action.", "is_correct": false}, {"text": "Hiding past struggles.", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 7.", "encouragement": "You have now completed Chapter 10: The Tree of Life. Throughout this chapter, you discovered that lasting recovery is about more than overcoming addiction—it is about building a life rooted in faith, purpose, grace, healing, and continual growth. You learned that as your relationship with the Divine grows stronger, your recovery becomes visible through your character, your choices, your relationships, and the way you positively influence others.\n\nAs you continue into Chapter 11, you will explore how love overcomes all of life''s issues and give the ultimate understanding and way of living in complete freedom."}}]}]}, {"number": 11, "title": "Love", "description": "This is where everything either comes together… or falls apart.\n\nYou can fix habits.You can train your mind.You can build discipline.\n\nBut if your heart is still messed up—you’ll sabotage everything later.\n\nChapter 11 is about love as the final system.\n\nNot soft nonsense.Real, structured, disciplined love that stabilizes your life.\n\nThis chapter focuses on:\n\nGod’s love as your foundation\n\nFixing your identity\n\nRemoving shame properly\n\nHealing relationships\n\nLearning to actually love people (without being weak)\n\nBuilding a life that doesn’t collapse under pressure\n\nThe goal is simple:\n\nStop living in survival mode.Start living in restored, stable, grounded identity and relationships.", "lessons": [{"number": 1, "title": "Understanding the Creators Love", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "This Is the Foundation You’ve Been Avoiding", "message": "You’ve been building discipline, control, and structure.\n\nGood.\n\nBut if you don’t fix this part, something will remain missing from your life.\n\nBecause deep down, most people in recovery still operate from:\n\nShame\n\nFear\n\nFeeling “not enough”\n\nTrying to prove something\n\nThis lesson fixes the foundation."}}, {"type": "reading", "content": {"title": "If You Don’t Understand Love Properly, You Build on Instability", "body": "You’ve heard “God is love.”\n\nBut let’s be real—you haven’t actually built your life on it.\n\nWhy?\n\nBecause you probably see your Creator as:\n\nDisappointed\n\nDistant\n\nWatching for mistakes\n\nWaiting for you to “get it right”\n\nThat mindset keeps you stuck in:\n\nPressure\n\nFear\n\nPerformance\n\nHere’s the correction:\n\nGod’s love is not weak.It’s not soft.It’s not “anything goes.”\n\nIt is:\n\nTruthful (doesn’t ignore your mistakes)\n\nPatient (doesn’t quit on you)\n\nPursuing (doesn’t leave you stuck)\n\nRestorative (actually rebuilds you)\n\nIf you misunderstand this, everything else breaks:\n\nDiscipline becomes pressure\n\nFailure becomes identity\n\nGrowth feels impossible\n\nBut when you understand it correctly:\n\nYou stop running\n\nYou stop hiding\n\nYou stop performing\n\nAnd you actually start changing properly and foundationally\n\nReflection Question:\n\nRight now—do you see your God as someone helping you grow… or someone you’re trying not to disappoint?"}}, {"type": "mentor_note", "content": {"note": "Love understood correctly stabilizes what fear keeps unstable."}}, {"type": "video", "content": {"title": "Understanding God’s Love", "description": "A breakdown of what God’s love actually is—and why misunderstanding it keeps you stuck in fear, shame, and unstable recovery."}}, {"type": "pause_reflect", "content": {"question": "Be honest:", "context": "How do you actually see God?\n\nDistant\n\nStrict\n\nDisappointed\n\nPatient\n\nPresent\n\nRestoring\n\nYour answer explains your entire mindset right now."}}, {"type": "journal_prompt", "content": {"prompt": "Write what you believe God’s love means.\n\nThen answer:\n\nHow has your current belief affected your recovery?\n\nHas it made you stronger… or more pressured?\n\nIf it’s pressure-based, it’s wrong."}}, {"type": "mood_checkin", "content": {"question": "How “accepted” do you feel right now?\n\nNot what you say.What you actually feel."}}, {"type": "daily_action", "content": {"title": "Reset the Foundation", "action": "Today, do one thing:\n\nWhen shame or pressure shows up, stop and say:\n\n“God’s love is not based on my performance right now.”\n\nLet that interrupt your normal pattern."}}, {"type": "mentor_note", "content": {"note": "Recovery becomes stable when love becomes the foundation—not an afterthought."}}, {"type": "quiz", "content": {"question": "What does God’s love provide?", "options": [{"text": "Pressure", "is_correct": false}, {"text": "Performance", "is_correct": false}, {"text": "A foundation for identity and healing", "is_correct": true}, {"text": "Excuses", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: God’s love is weak and ignores truth.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "Why does this lesson matter?", "options": [{"text": "It changes how you see yourself, failure, and growth", "is_correct": true}, {"text": "It removes discipline", "is_correct": false}, {"text": "It avoids responsibility", "is_correct": false}, {"text": "It weakens recovery", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 1", "encouragement": "This is the base layer.\n\nIf you get this wrong:\n\nYou’ll always feel like you’re chasing\n\nYou’ll always feel like you’re failing\n\nYou’ll always run back to old patterns\n\nIf you get this right:\n\nYou stop operating from fear\n\nYou build from stability\n\nYou actually grow\n\nNext → Lesson 2: Receiving Love and Acceptance\n\nThat’s where most people choke.\n\nBecause understanding love is easy.\n\nReceiving it is what exposes your ego, your shame, and your excuses."}}]}, {"number": 2, "title": "Receiving Love and Acceptance", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "You Say You Understand Love—But You Still Don’t Receive It", "message": "You just learned what God’s love is.\n\nNow comes the real problem:\n\nYou don’t actually accept it.\n\nYou still live like:\n\nYou need to earn it\n\nYou need to fix yourself first\n\nYou need to “be better” before it applies\n\nThat’s why you’re stuck."}}, {"type": "reading", "content": {"title": "If You Don’t Receive Acceptance, You Stay in Shame", "body": "Here’s the pattern most people are trapped in:\n\nMess up\n\nFeel shame\n\nTry harder\n\nFail again\n\nRepeat\n\nWhy?\n\nBecause you’re still operating like acceptance is earned.\n\nThat blocks real healing.\n\nReceiving love and acceptance means:\n\nYou stop trying to qualify for it\n\nYou stop running from it\n\nYou stop arguing with it\n\nAnd here’s where people get it wrong:\n\nAcceptance equals approval of everything you do\n\nThis is what acceptance really means:\n\nYou are not abandoned while you are being corrected\n\nYou are not rejected while you are growing\n\nYou are not worthless because you failed\n\nIf you don’t receive this properly:\n\nYou hide more\n\nYou lie more\n\nYou isolate more\n\nIf you do receive it:\n\nYou become more honest\n\nYou face things directly\n\nYou actually improve faster\n\nBecause shame loses control.\n\nReflection Question:\n\nWhere are you still trying to “earn” acceptance instead of receiving it?"}}, {"type": "mentor_note", "content": {"note": "What you refuse to receive cannot stabilize you."}}, {"type": "video", "content": {"title": "Receiving Love and Acceptance", "description": "A breakdown of why people resist acceptance and how receiving it properly removes shame and strengthens recovery."}}, {"type": "pause_reflect", "content": {"question": "Be honest:", "context": "Where do you still feel like:\n\n“I need to fix myself first”\n\n“I’m not good enough yet”\n\n“I shouldn’t be accepted like this”\n\nThat’s exactly where you’re resisting."}}, {"type": "journal_prompt", "content": {"prompt": "Write ONE area where you struggle to receive acceptance.\n\nThen answer:\n\nWhat are you believing instead?\n\nHow is that belief affecting your behavior?\n\nWhat would change if you actually accepted it?\n\nIf you don’t answer honestly, nothing changes."}}, {"type": "mood_checkin", "content": {"question": "How accepted do you actually feel right now?\n\nNot what you say.\n\nWhat you operate from."}}, {"type": "daily_action", "content": {"title": "Stop Fighting It", "action": "Today, when shame shows up:\n\nDon’t argue\n\nDon’t explain\n\nDon’t justify\n\nJust respond:\n\n“I am not rejected while I am being corrected.”\n\nRepeat it until your reaction changes."}}, {"type": "mentor_note", "content": {"note": "Accepted people become more honest.Rejected people keep hiding."}}, {"type": "quiz", "content": {"question": "What is the main principle in this lesson?", "options": [{"text": "Receiving love and acceptance", "is_correct": true}, {"text": "Earning worth", "is_correct": false}, {"text": "Avoiding truth", "is_correct": false}, {"text": "Hiding failure", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Acceptance means everything you do is okay.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "What does acceptance actually do?", "options": [{"text": "It removes shame and allows honesty", "is_correct": true}, {"text": "It removes responsibility", "is_correct": false}, {"text": "It weakens growth", "is_correct": false}, {"text": "It creates laziness", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 2", "encouragement": "This is where most people fail.\n\nNot because they don’t know truth—But because they refuse to receive it.\n\nIf you don’t fix this:\n\nYou’ll stay stuck in shame loops\n\nYou’ll keep hiding\n\nYou’ll keep restarting\n\nIf you do fix it:\n\nYou become honest\n\nYou stop performing\n\nYou actually heal\n\nNext → Lesson 3: Loving Yourself Through God’s Eyes\n\nThis is where identity gets rebuilt.\n\nAnd if your identity is wrong, everything else breaks."}}]}, {"number": 3, "title": "Loving Yourself Through God’s Eyes", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Self-Hatred Is Not Discipline—It’s a Hidden Problem", "message": "You think being hard on yourself is helping you.\n\nIt’s not.\n\nThere’s a difference between:\n\nTaking responsibility\n\nAnd constantly tearing yourself down\n\nIf your identity is:\n\n“I’m useless”\n\n“I always mess up”\n\n“I’m broken”\n\nThen guess what?\n\nYou’ll keep acting like it.\n\nYou don’t rise above the negative identity.You fall back to it."}}, {"type": "reading", "content": {"title": "You Can’t Build a Strong Life on a Broken Identity", "body": "Right now you’re probably swinging between two extremes:\n\nSelf-hatred\n\n“I’m trash”\n\n“I’ll never change”\n\n“I deserve this”\n\nSelf-protection\n\n“It’s not that bad”\n\n“I’ll deal with it later”\n\n“I’m fine”\n\nBoth are wrong.\n\nOne destroys you.The other lies to you.\n\nLoving yourself properly is not:\n\nEgo\n\nPride\n\nExcusing mistakes\n\nIt’s this:\n\nSeeing yourself truthfully under God.\n\nThat means:\n\nYou acknowledge your mistakes\n\nBut you don’t define yourself by them\n\nYou accept responsibility\n\nBut you don’t accept worthlessness\n\nIf you stay in self-hatred:\n\nYou lose motivation\n\nYou stay stuck\n\nYou repeat cycles\n\nIf you see yourself correctly:\n\nYou become honest\n\nYou take responsibility properly\n\nYou actually improve\n\nBecause now you''re building from truth—not emotion.\n\nReflection Question:\n\nWhere are you still believing something negative about yourself that isn’t actually true?"}}, {"type": "mentor_note", "content": {"note": "Self-hatred or dislike destroys growth.Truthful identity builds it."}}, {"type": "video", "content": {"title": "Loving Yourself Through God’s Eyes", "description": "A breakdown of how to stop operating from self-hatred or ego and start building a stable, truthful identity."}}, {"type": "pause_reflect", "content": {"question": "What do you actually believe about yourself?", "context": "Not what you say publicly.\n\nWhat runs in your head:\n\n“I’m weak”\n\n“I always fail”\n\n“I can’t change”\n\n“I’m not enough”\n\nThat belief is controlling your behavior."}}, {"type": "journal_prompt", "content": {"prompt": "Write ONE false belief about yourself.\n\nThen break it down:\n\nWhere did it come from?\n\nWhen does it show up?\n\nWhat truth replaces it?\n\nIf you don’t replace it, it stays."}}, {"type": "mood_checkin", "content": {"question": "Right now—how do you relate to yourself?\n\nCalm and honest\n\nOr critical and negative\n\nBe real."}}, {"type": "daily_action", "content": {"title": "Kill the False Identity", "action": "Today, when self-condemnation hits:\n\nDon’t sit in it.\n\nAnswer it immediately with truth.\n\nExample:\n\n“I made a mistake” ≠ “I am a mistake”\n\n“I’m improving” > “I’m stuck”\n\nSay it out loud if you have to."}}, {"type": "mentor_note", "content": {"note": "You don’t fix your life by attacking yourself.You fix it by seeing yourself clearly and acting correctly."}}, {"type": "quiz", "content": {"question": "What does loving yourself properly mean?", "options": [{"text": "Ignoring your mistakes", "is_correct": false}, {"text": "Worshipping yourself", "is_correct": false}, {"text": "Seeing yourself truthfully in your Creator", "is_correct": true}, {"text": "Excusing everything", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Self-hatred is the same as humility.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "Why does this lesson matter?", "options": [{"text": "It replaces false identity with truth", "is_correct": true}, {"text": "It removes responsibility", "is_correct": false}, {"text": "It avoids honesty", "is_correct": false}, {"text": "It weakens discipline", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 3", "encouragement": "This is identity work.\n\nAnd this is where people stay stuck for YEARS.\n\nIf you keep thinking:“I’m broken”\n\nYou’ll keep acting broken.\n\nIf you switch to:“I’m responsible, but I can change”\n\nNow you have leverage.\n\nNext → Lesson 4: Forgiveness and Healing\n\nThis is where you deal with the stuff you’ve been carrying.\n\nAnd if you don’t handle that properly…It will keep controlling you from underneath everything."}}]}, {"number": 4, "title": "Forgiveness and Healing", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "You Can’t Heal What You Keep Holding Onto", "message": "Let’s cut the nonsense.\n\nYou say you want healing…But you’re still holding onto:\n\nAnger\n\nResentment\n\nPast hurt\n\n“What they did”\n\nThat’s not healing.\n\nThat’s recycling pain."}}, {"type": "reading", "content": {"title": "Unforgiveness Keeps You Stuck in the Past", "body": "Here’s where people get it wrong:\n\nThey think forgiveness means:\n\nSaying it didn’t matter\n\nPretending it didn’t hurt\n\nLetting people off easily\n\nWrong.\n\nForgiveness is not:\n\nDenial\n\nWeakness\n\nIgnoring justice\n\nIt is this:\n\nYou stop letting the offense control your internal state.\n\nRight now, if you haven’t forgiven:\n\nThat person still controls your emotions\n\nThat event still shapes your reactions\n\nThat pain keeps replaying\n\nYou think you’re holding onto it.\n\nReality?\n\nIt’s holding onto you.\n\nForgiveness breaks that control.\n\nIt doesn’t say:“What happened was okay”\n\nIt says:“I’m not staying trapped under this anymore”\n\nIf you don’t deal with this:\n\nBitterness builds\n\nAnger leaks into everything\n\nRelationships stay damaged\n\nYou stay reactive\n\nIf you do deal with it:\n\nYou get control back\n\nYour thinking clears\n\nHealing actually starts\n\nReflection Question:\n\nWho or what are you still holding onto that is keeping you stuck?"}}, {"type": "mentor_note", "content": {"note": "What you refuse to release will continue to control you."}}, {"type": "video", "content": {"title": "Forgiveness and Healing", "description": "A breakdown of how unforgiveness keeps pain active—and how releasing it gives you control back."}}, {"type": "pause_reflect", "content": {"question": "Be honest:", "context": "Where do you feel resistance when you think about forgiving?\n\nSomeone who hurt you\n\nSomething unfair\n\nSomething you didn’t deserve\n\nThat resistance is exactly where you’re stuck."}}, {"type": "journal_prompt", "content": {"prompt": "Write ONE thing you’re holding onto.\n\nThen answer:\n\nWhat happened?\n\nHow has it affected you?\n\nWhat has holding onto it cost you?\n\nIf you can’t answer this clearly, you’re still avoiding it."}}, {"type": "mood_checkin", "content": {"question": "Right now—does your heart feel:\n\nHeavy\n\nAngry\n\nTight\n\nOr calm and free\n\nYour answer tells you everything."}}, {"type": "daily_action", "content": {"title": "Take Back Control", "action": "Today, do ONE step:\n\nYou don’t need to “feel ready.”\n\nYou decide.\n\nSay this:\n\n“I’m not letting this control me anymore.”\n\nThen:\n\nStop replaying it\n\nStop feeding it\n\nStop justifying holding onto it\n\nYou’re choosing freedom."}}, {"type": "mentor_note", "content": {"note": "Forgiveness isn’t forgetting.It’s refusing to stay controlled."}}, {"type": "quiz", "content": {"question": "What does forgiveness actually do?", "options": [{"text": "Pretends nothing happened", "is_correct": false}, {"text": "Removes all consequences", "is_correct": false}, {"text": "Releases your heart from being controlled by the offense", "is_correct": true}, {"text": "Weakens you", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Unforgiveness keeps pain active in your life.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "Why does this lesson matter?", "options": [{"text": "It connects healing with release", "is_correct": true}, {"text": "It avoids responsibility", "is_correct": false}, {"text": "It excuses everything", "is_correct": false}, {"text": "It weakens recovery", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 4", "encouragement": "This is one of the biggest blocks.\n\nYou can train your mind.You can control your actions.\n\nBut if you’re still carrying unresolved pain…\n\nIt leaks into everything:\n\nYour decisions\n\nYour relationships\n\nYour identity\n\nFix this, and you remove a massive hidden weight.\n\nIgnore this, and it keeps dragging you back.\n\nNext → Lesson 5: Loving Others Well\n\nNow you stop just fixing yourself…and start fixing how you deal with people."}}]}, {"number": 5, "title": "Loving Others Well", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "If You Can’t Relate Properly, You’ll Keep Breaking Things", "message": "Let’s be direct.\n\nYou can fix yourself…But if you still:\n\nLie\n\nAvoid\n\nGet defensive\n\nShut down\n\nReact emotionally\n\nYou’ll destroy relationships again.\n\nRecovery isn’t complete until you fix how you deal with people."}}, {"type": "reading", "content": {"title": "Loving Others Well Requires Discipline, Not Just Emotion", "body": "Most people think love is:\n\nA feeling\n\nBeing nice\n\nAvoiding conflict\n\nThat’s weak.\n\nReal love is:\n\nTruthful with self and others (you don’t lie or hide)\n\nPatient (you don’t react instantly)\n\nHumble (keep your ego in check)\n\nBoundaries (you don’t get involved where not needed)\n\nAddiction messes this up badly.\n\nYou get used to:\n\nProtecting yourself\n\nHiding things\n\nActing selfishly\n\nAvoiding responsibility\n\nSo when it’s time to love people properly…you don’t know how.\n\nLoving others well means:\n\nYou stop making everything about you\n\nYou stop reacting just on emotion\n\nYou stop avoiding the truth with others\n\nYou start showing consistency in relationships\n\nAnd here’s the important part:\n\nLove ≠ being soft\n\nYou can love someone and:\n\nSay no\n\nSet boundaries\n\nTell the truth\n\nIf you don’t fix this:\n\nYou’ll damage trust\n\nYou’ll stay isolated\n\nYou’ll repeat the same relationship problems\n\nIf you do fix it:\n\nYou build real connections\n\nYou become stable\n\nPeople can actually trust you\n\nReflection Question:\n\nWhere do you mess up most with people—truth, patience, humility, or boundaries?"}}, {"type": "mentor_note", "content": {"note": "Love gets real when truth and responsibility are involved."}}, {"type": "video", "content": {"title": "Loving Others Well", "description": "A breakdown of how to stop reacting emotionally and start building disciplined, truthful relationships."}}, {"type": "pause_reflect", "content": {"question": "Be honest:", "context": "What’s your biggest problem in relationships?\n\nYou avoid\n\nYou react\n\nYou lie\n\nYou get defensive\n\nYou shut down\n\nThat’s the thing you fix first."}}, {"type": "journal_prompt", "content": {"prompt": "Write ONE pattern that ruins your relationships.\n\nThen break it down:\n\nWhen does it show up?\n\nWhat triggers it?\n\nWhat would a controlled response look like?\n\nIf you don’t define it, you’ll repeat it."}}, {"type": "mood_checkin", "content": {"question": "Right now—are you:\n\nOpen and honest\n\nOr guarded and defensive\n\nBe real."}}, {"type": "daily_action", "content": {"title": "Fix One Interaction Today", "action": "Pick ONE person today.\n\nAnd do ONE thing better than usual:\n\nBe more honest\n\nBe more patient\n\nTake responsibility\n\nDon’t react emotionally\n\nOne controlled response > 10 emotional ones."}}, {"type": "mentor_note", "content": {"note": "Love matures when it becomes disciplined, not emotional."}}, {"type": "quiz", "content": {"question": "What does loving others well require?", "options": [{"text": "Just feelings", "is_correct": false}, {"text": "Avoiding conflict", "is_correct": false}, {"text": "Truth, patience, humility, and boundaries", "is_correct": true}, {"text": "Being passive", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Loving well means having no boundaries.", "options": [{"text": "True", "is_correct": false}, {"text": "False", "is_correct": true}]}}, {"type": "quiz", "content": {"question": "Why does this lesson matter?", "options": [{"text": "It builds real, stable relationships", "is_correct": true}, {"text": "It removes responsibility", "is_correct": false}, {"text": "It avoids honesty", "is_correct": false}, {"text": "It keeps things easy", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 5", "encouragement": "This is where you stop being self-focused.\n\nBefore:Everything was about your survival.\n\nNow:You learn how to function properly with people.\n\nIf you don’t fix this:You’ll keep burning relationships.\n\nIf you do:You build trust, stability, and real connection.\n\nNext → Lesson 6: Restoring Relationships\n\nThis is where you deal with damage already done.\n\nAnd if you rush it or do it wrong—you make it worse."}}]}, {"number": 6, "title": "Restoring Relationships", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "You Don’t Fix Broken Relationships with Words Alone", "message": "You probably think:\n\n“I’ll just say sorry and fix it.”\n\nNo.\n\nThat’s lazy—and it doesn’t work.\n\nBroken relationships aren’t fixed by:\n\nOne apology\n\nOne conversation\n\nOne “I’ve changed”\n\nThey’re fixed by proof over time."}}, {"type": "reading", "content": {"title": "Restoration Is Built, Not Claimed", "body": "Let’s be real.\n\nIf you’ve:\n\nLied\n\nBroken trust\n\nHurt people\n\nBeen inconsistent\n\nThen people don’t owe you instant trust.\n\nThat’s ego.\n\nRestoration actually works like this:\n\nTruth\n\nNo more hiding\n\nNo more half-truths\n\nNo more manipulation\n\nTime\n\nTrust doesn’t come back fast\n\nIt rebuilds slowly\n\nChanged behavior\n\nNot promises\n\nNot intentions\n\nConsistent actions\n\nRealistic expectations\n\nSome relationships won’t go back to how they were\n\nSome will improve\n\nSome will stay distant\n\nYou don’t control the outcome.\n\nYou control your behavior.\n\nMost people mess this up by:\n\nRushing people\n\nGetting frustrated\n\nPlaying victim\n\nExpecting forgiveness to equal trust\n\nWrong.\n\nForgiveness ≠ trust\n\nTrust is earned.\n\nReflection Question:\n\nWhere are you expecting trust back faster than you’ve actually earned it?"}}, {"type": "mentor_note", "content": {"note": "Trust returns through consistent truth—not rushed intention."}}, {"type": "video", "content": {"title": "Restoring Relationships", "description": "A breakdown of how real restoration works and why rushing it destroys progress."}}, {"type": "pause_reflect", "content": {"question": "Think about one damaged relationship.", "context": "Be honest:\n\nWhat did you actually do?\n\nWhat did it cost them?\n\nWhy would they struggle to trust you?\n\nIf you can’t answer that, you’re still avoiding responsibility."}}, {"type": "journal_prompt", "content": {"prompt": "Write about ONE relationship that needs repair.\n\nThen define:\n\nWhat damage was done\n\nWhat needs to change in you\n\nWhat consistent action would rebuild trust\n\nNot words. Actions."}}, {"type": "mood_checkin", "content": {"question": "How patient are you right now?\n\nPatient and steady\n\nOr frustrated and rushing\n\nThat determines if you’ll fix it—or break it again."}}, {"type": "daily_action", "content": {"title": "Take One Real Step", "action": "Today, do ONE of these:\n\nBe honest where you normally hide\n\nTake responsibility without excuses\n\nShow consistency where you’ve been unreliable\n\nNo speeches. Just action."}}, {"type": "mentor_note", "content": {"note": "Restoration becomes believable when behavior stays consistent."}}, {"type": "quiz", "content": {"question": "What builds real restoration?", "options": [{"text": "Apologies only", "is_correct": false}, {"text": "Pressure", "is_correct": false}, {"text": "Time, truth, and consistent change", "is_correct": true}, {"text": "Ignoring the past", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Not every relationship will be restored the same way.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "What’s the main focus here?", "options": [{"text": "Rushing trust", "is_correct": false}, {"text": "Forced closeness", "is_correct": false}, {"text": "Wise, patient rebuilding", "is_correct": true}, {"text": "Avoiding responsibility", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 6", "encouragement": "This is where you prove change is real.\n\nBefore:You said things.\n\nNow:You show things.\n\nIf you rush this:You destroy trust again.\n\nIf you do it right:You rebuild slowly—but solid.\n\nNext → Lesson 7: Living a Life of Compassion\n\nThis is where your pain stops being a weakness…and starts becoming something that actually builds your character."}}]}, {"number": 7, "title": "Living a Life of Compassion", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "Your Pain Either Hardens You… or Refines You", "message": "You’ve been through things.\n\nNow the question is:\n\nDid it make you:\n\nBitter\n\nClosed off\n\nDefensive\n\nOr:\n\nWiser\n\nMore patient\n\nMore understanding\n\nBecause it won’t stay neutral.\n\nPain always shapes you."}}, {"type": "reading", "content": {"title": "Compassion Comes from Transformed Pain—not Untouched Pain", "body": "Most people go one of two ways after being hurt:\n\nThey harden\n\n“I don’t trust anyone”\n\n“I don’t care anymore”\n\nDefensive, closed, reactive\n\nThey grow\n\n“I understand struggle better”\n\n“I can be patient”\n\n“I won’t repeat that damage”\n\nCompassion is not:\n\nBeing soft\n\nLetting people walk over you\n\nAgreeing with wrong\n\nThat’s weakness.\n\nReal compassion is:\n\nUnderstanding without excusing\n\nPatience without losing boundaries\n\nMercy without losing truth\n\nYour pain can either:\n\nTurn into resentmentOR\n\nTurn into perspective\n\nIf you don’t process it properly:You become harder, colder, more reactive.\n\nIf you do:You become controlled, aware, and stronger.\n\nReflection Question:\n\nWhere has your pain made you harder instead of wiser?"}}, {"type": "mentor_note", "content": {"note": "Healed pain creates clarity.Unhealed pain creates reaction."}}, {"type": "video", "content": {"title": "Living a Life of Compassion", "description": "A breakdown of how to turn past pain into controlled, disciplined compassion instead of resentment and defensiveness."}}, {"type": "pause_reflect", "content": {"question": "Be honest:", "context": "Who do you struggle to show compassion to?\n\nPeople who remind you of your past\n\nPeople who hurt you\n\nPeople who frustrate you\n\nThat’s the exact area you need growth."}}, {"type": "journal_prompt", "content": {"prompt": "Write ONE situation where you lack compassion.\n\nThen define:\n\nWhy it triggers you\n\nWhat you feel\n\nWhat a controlled, compassionate response would look like\n\nIf you don’t define it, you’ll keep reacting."}}, {"type": "mood_checkin", "content": {"question": "Right now—does your mindset feel:\n\nOpen and controlled\n\nOr reactive and defensive\n\nBe honest."}}, {"type": "daily_action", "content": {"title": "Respond with Control, Not Reaction", "action": "Today, pick ONE interaction.\n\nInstead of reacting:\n\nPause\n\nStay controlled\n\nRespond with patience\n\nNot weakness. Control."}}, {"type": "mentor_note", "content": {"note": "Compassion doesn’t remove strength.It directs it properly."}}, {"type": "quiz", "content": {"question": "What is real compassion?", "options": [{"text": "Being weak", "is_correct": false}, {"text": "Accepting everything", "is_correct": false}, {"text": "Mercy with truth and boundaries", "is_correct": true}, {"text": "Avoiding conflict", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Pain can either harden you or refine you.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "Why does this lesson matter?", "options": [{"text": "It turns pain into strength and awareness", "is_correct": true}, {"text": "It removes boundaries", "is_correct": false}, {"text": "It creates passivity", "is_correct": false}, {"text": "It avoids growth", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 7", "encouragement": "Now your pain becomes useful.\n\nBefore:Pain → reaction → damage\n\nNow:Pain → awareness → control → strength\n\nThat’s maturity.\n\nFinal lesson next → Walking in Love Daily\n\nThis is where everything becomes real.\n\nNot theory.Not ideas.\n\nDaily execution."}}]}, {"number": 8, "title": "Walking in Love Daily", "minutes": 15, "blocks": [{"type": "welcome", "content": {"heading": "This Is Where Everything Becomes Real", "message": "You’ve learned everything.\n\nNow the question is simple:\n\nDo you actually live it?\n\nBecause love is not:\n\nA only a feeling\n\nA concept\n\nA “good intention”\n\nIt’s also a daily decision.\n\nAnd most people fail here—because they wait to feel like it."}}, {"type": "reading", "content": {"title": "Love Is Built Through Daily Discipline, Not Occasional Emotion", "body": "You don’t “arrive” at love.\n\nYou practice it.\n\nEvery day.\n\nIn normal situations.\n\nThat’s where it matters.\n\nWalking in love daily means:\n\nYou stay patient when it’s inconvenient\n\nYou tell the truth when it’s uncomfortable\n\nYou forgive when it’s hard\n\nYou stay disciplined when emotions rise\n\nYou act with integrity when no one sees\n\nThis is not:\n\nBig dramatic moments\n\nEmotional highs\n\nPerfect behavior\n\nIt’s:Consistent, controlled, repeated actions\n\nThat’s what makes it real.\n\nIf you don’t do this:\n\nYou’ll fall back into old patterns\n\nYou’ll react emotionally\n\nYou’ll damage relationships again\n\nIf you do:\n\nYour life stabilizes\n\nYour relationships strengthen\n\nYour recovery becomes visible\n\nReflection Question:\n\nWhere in your daily life do you choose emotion over disciplined love?"}}, {"type": "mentor_note", "content": {"note": "Love becomes real when it shows up on ordinary days."}}, {"type": "video", "content": {"title": "Walking in Love Daily", "description": "A breakdown of how to turn everything you’ve learned into consistent daily action."}}, {"type": "pause_reflect", "content": {"question": "Be honest:", "context": "Where do you fail daily?\n\nTo love with Patience\n\nHonesty with love\n\nDisciplined because of love\n\nConsistency\n\nThat’s where your growth is."}}, {"type": "journal_prompt", "content": {"prompt": "Write ONE way you want to live differently daily.\n\nThen define:\n\nWhen it will happen\n\nWhat it looks like\n\nHow you’ll stay consistent\n\nIf it’s not clear—you won’t do it."}}, {"type": "mood_checkin", "content": {"question": "Right now—are you:\n\nConsistent and controlled\n\nOr reactive and emotional\n\nYour answer shows your level."}}, {"type": "daily_action", "content": {"title": "Make It Visible", "action": "Today, pick ONE normal situation.\n\nAnd do it differently:\n\nBe more patient\n\nBe more honest\n\nStay controlled\n\nFollow through\n\nNot big.Just consistent."}}, {"type": "mentor_note", "content": {"note": "The strongest love is the one repeated daily—not the one felt occasionally."}}, {"type": "quiz", "content": {"question": "What does walking in love daily mean?", "options": [{"text": "Waiting for feelings", "is_correct": false}, {"text": "Being perfect", "is_correct": false}, {"text": "Making love visible through consistent action", "is_correct": true}, {"text": "Avoiding effort", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "True or False: Love must be chosen repeatedly.", "options": [{"text": "True", "is_correct": true}, {"text": "False", "is_correct": false}]}}, {"type": "quiz", "content": {"question": "How does this chapter close the course?", "options": [{"text": "By turning recovery into daily lived action", "is_correct": true}, {"text": "By ending growth", "is_correct": false}, {"text": "By removing discipline", "is_correct": false}, {"text": "By simplifying everything", "is_correct": false}]}}, {"type": "complete", "content": {"message": "Congratulations on completing Lesson 8", "encouragement": "You’re done.\n\nBut this is where most people fail.\n\nThey finish learning…And stop executing.\n\nHere’s the truth:\n\nYou don’t “graduate” from this\n\nYou either apply it daily\n\nOr you drift back slowly\n\nEverything you’ve built:\n\nDiscipline\n\nThinking\n\nControl\n\nIdentity\n\nRelationships\n\nIt all depends on this:\n\nDaily execution.\n\nNo excuses."}}]}]}]'::jsonb) loop
    select id into chapter_record from chapters
    where course_version_id = course_version and title = chapter_item->>'title'
    order by created_at limit 1;
    if chapter_record is null then
      select id into chapter_record from chapters
      where course_version_id = course_version and sort_order = case (chapter_item->>'number')::integer when 8 then 9 when 9 then 10 when 10 then 8 else (chapter_item->>'number')::integer end
      order by created_at limit 1;
    end if;
    if chapter_record is null then
      raise exception 'Missing chapter: %', chapter_item->>'title';
    end if;
    update chapters set title = chapter_item->>'title', description = chapter_item->>'description',
      sort_order = (chapter_item->>'number')::integer, updated_at = now()
    where id = chapter_record;

    for lesson_item in select value from jsonb_array_elements(chapter_item->'lessons') loop
      select id into lesson_record from lessons
      where chapter_id = chapter_record and lesson_number = (lesson_item->>'number')::integer
      order by created_at limit 1;
      if lesson_record is null then
        raise exception 'Missing lesson % in chapter %', lesson_item->>'number', chapter_item->>'title';
      end if;
      update lessons set title = lesson_item->>'title', estimated_minutes = (lesson_item->>'minutes')::integer,
        opening_message = lesson_item->'blocks'->0->'content'->>'message',
        encouragement_message = lesson_item->'blocks'->12->'content'->>'encouragement',
        sort_order = (lesson_item->>'number')::integer, updated_at = now()
      where id = lesson_record;

      block_position := 0;
      for block_item in select value from jsonb_array_elements(lesson_item->'blocks') loop
        block_position := block_position + 1;
        select id into block_record from lesson_content_blocks
        where lesson_id = lesson_record and sort_order = block_position
        order by created_at limit 1;
        if block_record is null then
          insert into lesson_content_blocks (lesson_id, block_type, content, sort_order)
          values (lesson_record, block_item->>'type', block_item->'content', block_position);
        else
          update lesson_content_blocks set block_type = block_item->>'type', content = block_item->'content',
            updated_at = now() where id = block_record;
        end if;
      end loop;
      delete from lesson_content_blocks where lesson_id = lesson_record and sort_order > block_position;
    end loop;
  end loop;
end $$;
